INSERT INTO `automation` VALUES (1,'ai.cerb.automationBuilder.action.dataQuery','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  set:\r\n    query_examples:\r\n      custom:\r\n        label: Build it myself\r\n      records_search:\r\n        label: Get record dictionaries by search\r\n      records_subtotal:\r\n        label: Subtotal records by field\r\n\r\n  await/objective:\r\n    form:\r\n      title: Execute a data query\r\n      elements:\r\n        sheet/prompt_example:\r\n          label: What would you like to do?\r\n          data@key: query_examples\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              filtering@bool: no\r\n              headings@bool: no\r\n              paging@bool: no\r\n            columns:\r\n              selection/__index:\r\n                params:\r\n                  mode: single\r\n                  label_key: label\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  decision/example:\r\n    outcome/records_search:\r\n      if@bool: {{\'records_search\' == prompt_example}}\r\n      then:\r\n        await/record_type:\r\n          form:\r\n            elements:\r\n              sheet/prompt_record_type@ref: promptRecordType\r\n        \r\n        set:\r\n          snippet@text:\r\n            type:worklist.records\r\n            of:{{prompt_record_type}}\r\n            query:(\r\n              limit:25\r\n              sort:id\r\n            )\r\n            format:dictionaries\r\n\r\n    outcome/records_subtotal:\r\n      if@bool: {{\'records_subtotal\' == prompt_example}}\r\n      then:\r\n        await/record_type:\r\n          form:\r\n            elements:\r\n              sheet/prompt_record_type@ref: promptRecordType\r\n        \r\n        set:\r\n          snippet@text:\r\n            type:worklist.subtotals\r\n            of:{{prompt_record_type}}\r\n            by:[{{prompt_record_fields|join(\',\')}}]\r\n            query:(\r\n              \r\n            )\r\n            format:dictionaries\r\n\r\n    outcome/custom:\r\n      then:\r\n        data.query/dataTypes:\r\n          inputs:\r\n            query@text:\r\n              type:data.query.types\r\n              format:dictionaries\r\n          output: results\r\n          on_success:\r\n            await:\r\n              form:\r\n                elements:\r\n                  sheet/prompt_type:\r\n                    label: What kind of data query?\r\n                    required@bool: yes\r\n                    limit: 50\r\n                    data@key: results:data\r\n                    schema:\r\n                      layout:\r\n                        title_column: name;\r\n                        headings@bool: no\r\n                        filtering@bool: yes\r\n                        style: grid\r\n                      columns:\r\n                        selection/name:\r\n                          params:\r\n                            mode: single\r\n                            label_key: name\r\n                        text/description:\r\n                  submit:\r\n                    continue@bool: no\r\n                    reset@bool: no\r\n            \r\n            set:\r\n              snippet@text:\r\n                type:{{prompt_type}}\r\n                \r\n                format:dictionaries\r\n\r\n  await/custom:\r\n    form:\r\n      elements:\r\n        editor/prompt_query:\r\n          label: Query:\r\n          required@bool: yes\r\n          syntax: cerb_query_data\r\n          default@key: snippet\r\n        \r\n        text/prompt_output_key:\r\n          label: Output Key:\r\n          required@bool: yes\r\n          default: results\r\n          placeholder: results\r\n\r\n  return:\r\n    snippet@text:\r\n      data.query/{{random_string(6)|lower}}:\r\n        inputs:\r\n          query@text:\r\n            {{prompt_query|indent(\'      \',2)}}\r\n        output: {{prompt_output_key}}\r\n        #on_simulate:\r\n        #on_error:\r\n        #on_success:\r\n\r\n&promptRecordType:\r\n  label: Which record type?\r\n  required@bool: yes\r\n  data:\r\n    automation:\r\n      uri: cerb:automation:cerb.data.record.types\r\n  limit: 100\r\n  schema:\r\n    layout:\r\n      style: grid\r\n      filtering@bool: yes\r\n      headings@bool: no\r\n    columns:\r\n      selection/uri:\r\n        params:\r\n          mode: single\r\n          label_key: label_plural\r\n','commands:\r\n  data.query:\r\n    deny/type@bool: {{query.type != \'data.query.types\'}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (2,'ai.cerb.automationBuilder.action.emailParser','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        editor/prompt_message_source:\r\n          label: Message source;\r\n          syntax: text\r\n          default@text:\r\n            From: customer@cerb.example\r\n            To: support@cerb.example\r\n            Subject: This is an example\r\n            \r\n            This is an example message.\r\n\r\n  return:\r\n    snippet@text:\r\n      email.parse/{{random_string(6)|lower}}:\r\n        output: results\r\n        inputs:\r\n          message@text:\r\n            {{prompt_message_source|indent(\'      \', 2)}}\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:\r\n','');
INSERT INTO `automation` VALUES (3,'ai.cerb.automationBuilder.action.function','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        say:\r\n          content@text: ## Function\r\n\r\n        sheet/prompt_function_id:\r\n          label: Name:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: automation\r\n                query@text:\r\n                  trigger:cerb.trigger.automation.function\r\n          required@bool: yes\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              filtering@bool: yes\r\n              #paging@bool: no\r\n              headings@bool: no\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n              text/_label:\r\n                params:\r\n                  bold@bool: yes\r\n\r\n  set/load_function:\r\n    function_data__context: automation\r\n    function_data_id@key: prompt_function_id\r\n\r\n  return:\r\n    snippet@text:\r\n      function/{{random_string(6)|lower}}:\r\n        uri: cerb:automation:{{function_data_name}}\r\n        inputs:\r\n          {% for input in function_data_inputs -%}\r\n          {{input.key}}:\r\n          {% endfor %}\r\n\r\n        output: results\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (4,'ai.cerb.automationBuilder.action.httpRequest','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Execute an HTTP request\r\n      elements:\r\n        text/prompt_url:\r\n          label: URL:\r\n          default: https://example.com\r\n          type: url\r\n          required@bool: yes\r\n          \r\n        sheet/prompt_method:\r\n          label: Method:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              name: GET\r\n            1:\r\n              name: POST\r\n            2:\r\n              name: PUT\r\n            3:\r\n              name: DELETE\r\n          limit: 10\r\n          default: GET\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              style: grid\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n        \r\n        sheet/has_auth:\r\n          label: Authorization:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              name: None\r\n            1:\r\n              name: OAuth\r\n            2:\r\n              name: AWS\r\n            3:\r\n              name: Bearer Token\r\n            4:\r\n              name: Other\r\n          limit: 10\r\n          default: None\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              style: grid\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n              \r\n  decision/needs_auth:\r\n    outcome:\r\n      if@bool:\r\n        {{has_auth != \'None\' ? \'yes\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            elements:\r\n              sheet/prompt_account_id:\r\n                label: Sign requests with which account?\r\n                data:\r\n                  automation:\r\n                    uri: cerb:automation:cerb.data.records\r\n                    inputs:\r\n                      record_type: connected_account\r\n                      query@text:\r\n                        {% if has_auth == \'OAuth\' %}\r\n                        service:(type:oauth)\r\n                        {% elseif has_auth == \'AWS\' %}\r\n                        service:(type:aws)\r\n                        {% elseif has_auth == \'Bearer Token\' %}\r\n                        service:(type:bearer)\r\n                        {% endif %}\r\n                limit: 10\r\n                #default:\r\n                schema:\r\n                  layout:\r\n                    filtering@bool: yes\r\n                    headings@bool: no\r\n                  columns:\r\n                    selection/_selection:\r\n                      params:\r\n                        mode: single\r\n                        value_template@raw: {{uri ?: id}}\r\n                    card/_label:\r\n                      params:\r\n                        bold: yes\r\n                    text/uri:\r\n                    text/service_extension_name:\r\n                      params:\r\n                        underline@bool: no\r\n                      \r\n  return:\r\n    snippet@text:\r\n      http.request/{{random_string(6)|lower}}:\r\n        output: http_response\r\n        inputs:\r\n          method: {{prompt_method}}\r\n          url: {{prompt_url}}\r\n          #headers:\r\n          #  Content-Type: text/plain\r\n          #  X-HeaderName: Header value\r\n          #body@text:\r\n          #  This is the body content\r\n          {% if prompt_account_id -%}\r\n          authentication: cerb:connected_account:{{prompt_account_id}}\r\n          {% endif %}\r\n        # on_simulate:\r\n        #   set:\r\n        #     http_response:\r\n        #       status_code@int: 200\r\n        #       content_type: application/json\r\n        #       headers:\r\n        #         x-example: some header\r\n        #       body@text:\r\n        #         {status:\"ok\"}\r\n        on_success:\r\n        on_error:','');
INSERT INTO `automation` VALUES (5,'ai.cerb.automationBuilder.action.pgpDecrypt','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  return:\r\n    snippet@text:\r\n      decrypt.pgp/{{random_string(6)|lower}}:\r\n        output: decrypted_message\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/decrypt.pgp/\r\n          # [TODO] Set `message:`\r\n          #message: -----BEGIN PGP MESSAGE-----...\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (6,'ai.cerb.automationBuilder.action.pgpEncrypt','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        sheet/prompt_keys:\r\n          label: Encrypt with these keys:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: gpg_public_key\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              filtering@bool: yes\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              title_column: _label\r\n            columns:\r\n              selection/fingerprint:\r\n                params:\r\n                  mode: multiple\r\n              card/_label:\r\n                params:\r\n                  bold@bool: yes\r\n              text/_fingerprint:\r\n                params:\r\n                  value_key: fingerprint\r\n  \r\n  return:\r\n    snippet@text:\r\n      encrypt.pgp/{{random_string(6)|lower}}:\r\n        output: encrypted_message\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/encrypt.pgp/\r\n          message@text:\r\n            This is a secret message.\r\n          public_keys:\r\n            {% for fingerprint in prompt_keys -%}\r\n            uri: cerb:gpg_public_key:{{fingerprint}}\r\n            {% endfor -%}\r\n        \r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (7,'ai.cerb.automationBuilder.action.recordCreate','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Create a record\r\n      elements:\r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 100\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: grid\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n                  label_key: label_singular\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n        \r\n  data.query/recordFields:\r\n    inputs:\r\n      query@text:\r\n        type:record.fields\r\n        of:{{prompt_record_type}}\r\n        limit:0\r\n        format:dictionaries\r\n    output: record_fields\r\n  \r\n  await/fields:\r\n    form:\r\n      title: Create {{prompt_record_type}} record\r\n      elements:\r\n        sheet/prompt_record_fields:\r\n          label: Record Fields:\r\n          data@key: record_fields:data\r\n          limit: 50\r\n          default@csv:\r\n            {{\r\n              record_fields.data|filter((field) => field.is_required)|keys|join(\',\')\r\n            }}\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: columns\r\n            columns:\r\n              selection/__index:\r\n                params:\r\n                  mode: multiple\r\n                  label_key: key\r\n                  icon_template@raw: {{is_required ? \'asterisk\'}}\r\n              text/type:\r\n                params:\r\n                  value_template@raw: ({{type}})\r\n\r\n  set:\r\n    uniq: {{random_string(6)|lower}}\r\n  \r\n  var.set/command:\r\n    inputs:\r\n      key: command:record.create/{{uniq}}\r\n      value:\r\n        output: new_{{prompt_record_type}}\r\n        inputs:\r\n          record_type: {{prompt_record_type}}\r\n          fields@list:\r\n        on_error@list:\r\n        on_success@list:\r\n  \r\n  repeat/fields:\r\n    each@csv: {{prompt_record_fields|sort|join(\',\')}}\r\n    as: prompt_record_field\r\n    do:\r\n      set:\r\n        record_field_type@text,trim:\r\n          {{record_fields.data[prompt_record_field].type}}\r\n        record_field_key@text,trim:\r\n          command:record.create/{{uniq}}:inputs:fields:{{prompt_record_field}}\r\n      decision/type:\r\n        outcome/bit:\r\n          if@bool: {{\'bit\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@int: 1\r\n        outcome/file:\r\n          if@bool: {{\'file\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@int: 123\r\n        outcome/id:\r\n          if@bool: {{\'id\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@int: 123\r\n        outcome/image:\r\n          if@bool: {{\'image\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}@text\r\n                value@text:\r\n                  data:image/png;base64,[...Base64-encoded bytes here...]\r\n        outcome/links:\r\n          if@bool: {{\'links\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@list:\r\n                  ticket:123\r\n                  -ticket:456\r\n        outcome/list:\r\n          if@bool: {{\'list\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@list:\r\n                  option1\r\n                  option2\r\n        outcome/multicheckbox:\r\n          if@bool: {{\'multi-checkbox\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@list:\r\n                  option1\r\n                  option2\r\n        outcome/object:\r\n          if@bool: {{\'object\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value:\r\n                  key: value\r\n        outcome/timestamp:\r\n          if@bool: {{\'timestamp\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}@date\r\n                value: now\r\n        outcome/url:\r\n          if@bool: {{\'url\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value: https://example.com\r\n        outcome/worker:\r\n          if@bool: {{\'worker\' == record_field_type}}\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@int: 123\r\n        outcome/else:\r\n          then:\r\n            var.set:\r\n              inputs:\r\n                key: {{record_field_key}}\r\n                value@text: value\r\n\r\n  return:\r\n    snippet: {{command|kata_encode}}','commands:\r\n  data.query:\r\n    deny/type@bool: {{query.type != \'record.fields\'}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (8,'ai.cerb.automationBuilder.action.recordDelete','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Delete a record\r\n      elements:\r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 100\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: grid\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n                  label_key: label_plural\r\n\r\n  return:\r\n    snippet@text:\r\n      {% set record_uri = prompt_record_type %}\r\n      record.delete/{{random_string(6)|lower}}:\r\n        output: results\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/record.delete/\r\n          record_type: {{record_uri}}\r\n          # [TODO] Set `record_id:`\r\n          #record_id: 123\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (9,'ai.cerb.automationBuilder.action.recordGet','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\n  await/type:\n    form:\n      elements:\n        sheet/prompt_record_type:\n          label: Record Type:\n          required@bool: yes\n          data:\n            automation:\n              uri: cerb:automation:cerb.data.record.types\n              inputs:\n          limit: 65\n          schema:\n            layout:\n              style: grid\n              headings@bool: no\n              paging@bool: yes\n              filtering@bool: yes\n            columns:\n              selection/uri:\n                params:\n                  mode: single\n              text/label_singular:\n                params:\n                  bold@bool: yes\n        submit:\n          continue@bool: no\n          reset@bool: no\n\n  return:\n    snippet@text:\n      {% set record_uri = prompt_record_type %}\n      record.get/{{random_string(6)|lower}}:\n        output: record_{{record_uri}}\n        inputs:\n          # See: https://cerb.ai/docs/automations/commands/record.get/\n          record_type: {{record_uri}}\n          # [TODO] Set `record_id:`\n          #record_id: 123\n        #on_simulate:\n        #on_success:\n        #on_error:','');
INSERT INTO `automation` VALUES (10,'ai.cerb.automationBuilder.action.recordSearch','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Search records\r\n      elements:\r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 100\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: grid\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n                  label_key: label_plural\r\n\r\n  return:\r\n    snippet@text:\r\n      {% set record_uri = prompt_record_type %}\r\n      record.search/{{random_string(6)|lower}}:\r\n        output: results_{{record_uri}}\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/record.search/\r\n          record_type: {{record_uri}}\r\n          # [TODO]: Set `record_query:` and `record_query_params:`\r\n          #record_query: id:${example}\r\n          #record_query_params:\r\n          #  example: 123\r\n            \r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (11,'ai.cerb.automationBuilder.action.recordUpdate','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Update a record\r\n      elements:\r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 100\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: grid\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n                  label_key: label_plural\r\n\r\n  await/fields:\r\n    form:\r\n      elements:\r\n        sheet/prompt_record_fields:\r\n          label: Record Fields:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.fields\r\n              inputs:\r\n                of: {{prompt_record_type}}\r\n          limit: 15\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              title_column: _key\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: multiple\r\n              text/_key:\r\n                params:\r\n                  bold@bool: yes\r\n                  value_key: key\r\n                  icon:\r\n                    image_template@raw: {{is_required ? \'asterisk\'}}\r\n              text/type:\r\n              text/notes:\r\n\r\n  return:\r\n    snippet@text:\r\n      {% set record_uri = prompt_record_type %}\r\n      record.update/{{random_string(6)|lower}}:\r\n        output: updated_{{record_uri}}\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/record.update/\r\n          record_type: {{record_uri}}\r\n          # [TODO] Set `record_id:`\r\n          #record_id: 123\r\n          fields:\r\n            {% for field in prompt_record_fields -%}\r\n            {{field}}:\r\n            {% endfor %}\r\n            \r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (12,'ai.cerb.automationBuilder.action.recordUpsert','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Upsert a record\r\n      elements:\r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 100\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              style: grid\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n                  label_key: label_plural\r\n\r\n  await/fields:\r\n    form:\r\n      elements:\r\n        sheet/prompt_record_fields:\r\n          label: Record Fields:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.fields\r\n              inputs:\r\n                of: {{prompt_record_type}}\r\n          limit: 15\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              title_column: _key\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: multiple\r\n              text/_key:\r\n                params:\r\n                  bold@bool: yes\r\n                  value_key: key\r\n                  icon:\r\n                    image_template@raw: {{is_required ? \'asterisk\'}}\r\n              text/type:\r\n              text/notes:\r\n\r\n  return:\r\n    snippet@text:\r\n      {% set record_uri = prompt_record_type %}\r\n      record.upsert/{{random_string(6)|lower}}:\r\n        output: record_{{record_uri}}\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/record.upsert/\r\n          record_type: {{record_uri}}\r\n          # [TODO] Set `record_query:` to match zero (insert) or one (update) rows\r\n          #record_query@text:\r\n          #  id:123 limit:1 sort:-id\r\n          fields:\r\n            {% for field in prompt_record_fields -%}\r\n            {{field}}:\r\n            {% endfor %}\r\n            \r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (13,'ai.cerb.automationBuilder.action.storageDelete','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          required@bool: yes\r\n          type: freeform\r\n          default@text:\r\n            some.arbitrary.identifier\r\n          placeholder: (some.arbitrary.identifier)\r\n        \r\n  return:\r\n    snippet@text:\r\n      storage.delete/{{random_string(6)|lower}}:\r\n        output: result\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/storage.delete/\r\n          key: {{prompt_key}}\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (14,'ai.cerb.automationBuilder.action.storageGet','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          required@bool: yes\r\n          type: freeform\r\n          default@text:\r\n            some.arbitrary.identifier\r\n          placeholder: (some.arbitrary.identifier)\r\n        text/prompt_default:\r\n          label: Default:\r\n          type: freeform\r\n          default@text:\r\n            This is a default value.\r\n          placeholder: (an arbitrary default value)\r\n        \r\n  return:\r\n    snippet@text:\r\n      storage.get/{{random_string(6)|lower}}:\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/storage.get/\r\n          key: {{prompt_key}}\r\n          default: {{prompt_default}}\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (15,'ai.cerb.automationBuilder.action.storageSet','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          required@bool: yes\r\n          type: freeform\r\n          default@text:\r\n            some.arbitrary.identifier\r\n          placeholder: (some.arbitrary.identifier)\r\n        text/prompt_value:\r\n          label: Value:\r\n          required@bool: yes\r\n          type: freeform\r\n          default@text:\r\n            This is the saved value.\r\n          placeholder: (an arbitrary value)\r\n        text/prompt_expires:\r\n          label: Expires:\r\n          type: freeform\r\n          default@text: +15 mins\r\n          placeholder: (e.g. +15 mins)\r\n        \r\n  return:\r\n    snippet@text:\r\n      storage.set/{{random_string(6)|lower}}:\r\n        output: result\r\n        inputs:\r\n          # See: https://cerb.ai/docs/automations/commands/storage.set/\r\n          key: {{prompt_key}}\r\n          value: {{prompt_value}}\r\n          expires: {{prompt_expires}}\r\n        #on_simulate:\r\n        #on_success:\r\n        #on_error:','');
INSERT INTO `automation` VALUES (16,'ai.cerb.automationBuilder.help','Help for the automation editor','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/topic:\r\n    type: freeform\r\n    required@bool: yes\r\n\r\nstart:\r\n  decision:\r\n    outcome/editor:\r\n      if@bool: {{inputs.topic == \'editor\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            title: Help: Automation Editor\r\n            elements:\r\n              say/markdown:\r\n                content@text:\r\n                  ## Documentation\r\n                  See: <https://cerb.ai/docs/automations/>\r\n    outcome/input:\r\n      if@bool: {{inputs.topic == \'input\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            title: Help: Automation Input\r\n            elements:\r\n              say/markdown:\r\n                content@text:\r\n                  ## Documentation\r\n                  See: <https://cerb.ai/docs/automations/#inputs>\r\n\r\n    outcome/output:\r\n      if@bool: {{inputs.topic == \'output\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            title: Help: Automation Output\r\n            elements:\r\n              say/markdown:\r\n                content@text:\r\n                  ## Documentation\r\n                  See: <https://cerb.ai/docs/automations/#dictionaries>\r\n    \r\n    outcome/policy:\r\n      if@bool: {{inputs.topic == \'policy\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            title: Help: Automation Policies\r\n            elements:\r\n              say/markdown:\r\n                content@text:\r\n                  ## Documentation\r\n                  See: <https://cerb.ai/docs/automations/#policies>','');
INSERT INTO `automation` VALUES (17,'ai.cerb.automationBuilder.input.array','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          type: uri\r\n          required@bool: yes\r\n  \r\n        sheet/prompt_required:\r\n          label: Required:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              { \"name\": \"yes\" },\r\n              { \"name\": \"no\" }\r\n            ]\r\n          limit: 10\r\n          default: yes\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n\r\n  return:\r\n    snippet@text:\r\n      array/{{prompt_key|lower}}:\r\n        required@bool: {{prompt_required}}\r\n','');
INSERT INTO `automation` VALUES (18,'ai.cerb.automationBuilder.input.record','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          type: uri\r\n          required@bool: yes\r\n  \r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n              text/label_singular:\r\n                params:\r\n                  bold@bool: yes\r\n  \r\n        sheet/prompt_required:\r\n          label: Required:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              { \"name\": \"yes\" },\r\n              { \"name\": \"no\" }\r\n            ]\r\n          limit: 10\r\n          default: yes\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n\r\n  return:\r\n    snippet@text:\r\n      record/{{prompt_key|lower}}:\r\n        record_type: {{prompt_record_type}}\r\n        required@bool: {{prompt_required}}\r\n','');
INSERT INTO `automation` VALUES (19,'ai.cerb.automationBuilder.input.records','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_key:\r\n          label: Key:\r\n          type: uri\r\n          required@bool: yes\r\n  \r\n        sheet/prompt_record_type:\r\n          label: Record Type:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.record.types\r\n              inputs:\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n            columns:\r\n              selection/uri:\r\n                params:\r\n                  mode: single\r\n              text/label_singular:\r\n                params:\r\n                  bold@bool: yes\r\n  \r\n        sheet/prompt_required:\r\n          label: Required:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              { \"name\": \"yes\" },\r\n              { \"name\": \"no\" }\r\n            ]\r\n          limit: 10\r\n          default: yes\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n\r\n  return:\r\n    snippet@text:\r\n      records/{{prompt_key|lower}}:\r\n        record_type: {{prompt_record_type}}\r\n        required@bool: {{prompt_required}}\r\n','');
INSERT INTO `automation` VALUES (20,'ai.cerb.automationBuilder.input.text','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        say/type:\r\n          content: ## Inputs: Text\r\n  \r\n        text/prompt_key:\r\n          label: Key:\r\n          required@bool: yes\r\n          type: uri\r\n          placeholder: lowercase, a-z, 0-9, and underscore\r\n  \r\n        sheet/prompt_type:\r\n          label: Type:\r\n          data:\r\n            freeform:\r\n              name: Freeform\r\n              description: An arbitrary string of text\r\n            bool:\r\n              name: Boolean\r\n              description: true or false\r\n            date:\r\n              name: Date\r\n              description: tomorrow 5pm, +2 weeks, Friday\r\n            decimal:\r\n              name: Decimal\r\n              description: 3.1415\r\n            email:\r\n              name: Email\r\n              description: client@example.com\r\n            geopoint:\r\n              name: Geopoint\r\n              description: 44.226737, 20.7953 (lat, long)\r\n            ip:\r\n              name: IP\r\n              description: 1.2.3.4 or a1b2:c3d4:e5f6:a1b2:c3d4:e5f6:a1b2:c3d4\r\n            ipv4:\r\n              name: IPv4\r\n              description: 1.2.3.4\r\n            ipv6:\r\n              name: IPv6\r\n              description: a1b2:c3d4:e5f6:a1b2:c3d4:e5f6:a1b2:c3d4\r\n            number:\r\n              name: Number\r\n              description: 1234\r\n            record_type:\r\n              name: Record Type\r\n              description: address, comment, ticket, worker\r\n            timestamp:\r\n              name: Timestamp\r\n              description: UNIX_TIMESTAMP()\r\n            uri:\r\n              name: URI\r\n              description: alphanumeric_with_underscores (a-z, 0-9, _)\r\n            url:\r\n              name: URL\r\n              description: https://example.com/path/file.png\r\n          default: freeform\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n            columns:\r\n              selection/__index:\r\n                params:\r\n                  mode: single\r\n              text/name:\r\n                params:\r\n                  bold@bool: yes\r\n              text/description:\r\n  \r\n        text/prompt_default:\r\n          label: Default:\r\n          type: freeform\r\n  \r\n        sheet/prompt_required:\r\n          label: Required:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              name: yes\r\n            1:\r\n              name: no\r\n          limit: 10\r\n          default: yes\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n\r\n  return:\r\n    snippet@text:\r\n      text/{{prompt_key|lower}}:\r\n        type: {{prompt_type}}\r\n        {% if prompt_required == \'yes\' -%}\r\n        required@bool: yes\r\n        {% endif -%}\r\n        {% if prompt_default -%}\r\n        default: {{prompt_default}}\r\n        {% endif -%}','');
INSERT INTO `automation` VALUES (21,'ai.cerb.automationBuilder.interaction.worker.await.map','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  # await:\r\n  #   form:\r\n  #     elements:\r\n      # [TODO] region: world, us, europe, asia, africa\r\n\r\n  return:\r\n    snippet@text:\r\n      map/respond_{{random_string(6)|lower}}:\r\n        # See: https://cerb.ai/docs/maps/\r\n        resource:\r\n            uri: cerb:resource:map.world.countries\r\n          projection:\r\n            type: mercator\r\n            scale: 90\r\n            center:\r\n              latitude: 0\r\n              longitude: 0\r\n        regions:\r\n        points:','');
INSERT INTO `automation` VALUES (22,'ai.cerb.automationBuilder.interaction.worker.await.promptEditor','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/setup:\r\n    form:\r\n      title: Prompt with a code editor:\r\n      elements:\r\n        text/prompt_label:\r\n          label: Label:\r\n          default: Enter code:\r\n          required@bool: yes\r\n  \r\n        sheet/prompt_syntax:\r\n          label: Syntax:\r\n          required@bool: yes\r\n          data:\r\n            cerb_query_data:\r\n              mode: cerb_query_data\r\n              name: Cerb Data Query\r\n            cerb_query_search:\r\n              mode: cerb_query_search\r\n              name: Cerb Search Query\r\n            html:\r\n              mode: html\r\n              name: HTML\r\n            json:\r\n              mode: json\r\n              name: JSON\r\n            kata:\r\n              mode: kata\r\n              name: KATA\r\n            markdown:\r\n              mode: markdown\r\n              name: Markdown\r\n            text:\r\n              mode: text\r\n              name: Text\r\n            yaml:\r\n              mode: yaml\r\n              name: YAML\r\n          default@list:\r\n            cerb_query_data\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              style: grid\r\n            columns:\r\n              selection/mode:\r\n                params:\r\n                  mode: single\r\n              text/name:\r\n                params:\r\n                  bold@bool: yes\r\n  await/default:\r\n    form:\r\n      elements:\r\n        editor/prompt_default:\r\n          label: Default:\r\n          mode: {{prompt_mode}}\r\n\r\n  return:\r\n    snippet@text:\r\n      editor/prompt_{{random_string(6)|lower}}:\r\n        label: {{prompt_label}}\r\n        syntax: {{prompt_syntax}}\r\n        {% if prompt_default -%}\r\n        default@text:\r\n          {{prompt_default|indent(\'    \', 2)}}\r\n        {% endif -%}\r\n','');
INSERT INTO `automation` VALUES (23,'ai.cerb.automationBuilder.interaction.worker.await.promptSheet','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Prompt with a sheet\r\n      elements:\r\n        sheet/prompt_style:\r\n          label: What kind of sheet do you want to build?\r\n          required@bool: yes\r\n          data:\r\n            custom:\r\n              key: custom\r\n              name: Custom\r\n              description: Provide your own data\r\n            record_chooser:\r\n              key: record_chooser\r\n              name: Record chooser\r\n              description: Select records of a given type\r\n            record_types:\r\n              key: record_types\r\n              name: Record types\r\n              description: Select a record type\r\n          limit: 10\r\n          default: custom\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              headings@bool: no\r\n              paging@bool: no\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n                  label_key: name\r\n              text/description:\r\n  \r\n  decision/style:\r\n    outcome/custom:\r\n      if@bool: {{prompt_style == \'custom\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            elements:\r\n              sheet/prompt_mode:\r\n                label: Row selection:\r\n                required@bool: yes\r\n                data:\r\n                  none:\r\n                    key: none\r\n                    name: None\r\n                    description: No selection\r\n                  single:\r\n                    key: single\r\n                    name: Single\r\n                    description: Select a single record\r\n                  option2:\r\n                    key: multiple\r\n                    name: Multiple\r\n                    description: Select multiple records\r\n                limit: 5\r\n                default: single\r\n                schema:\r\n                  layout:\r\n                    headings@bool: no\r\n                    paging@bool: no\r\n                    style: grid\r\n                  columns:\r\n                    selection/key:\r\n                      params:\r\n                        mode: single\r\n                    text/name:\r\n                      params:\r\n                        bold@bool: yes\r\n                    text/description:\r\n            \r\n        return:\r\n          snippet@text:\r\n            sheet/prompt_{{random_string(6)|lower}}:\r\n              label: Label:\r\n              required@bool: yes\r\n              data:\r\n                option1:\r\n                  key: option1\r\n                  name: Option 1\r\n                  description: This is a description of option one\r\n                option2:\r\n                  key: option2\r\n                  name: Option 2\r\n                  description: This is a description of option two\r\n              limit: 5\r\n              default: option1\r\n              schema:\r\n                layout:\r\n                  headings@bool: no\r\n                  paging@bool: no\r\n                columns:\r\n                  {% if prompt_mode != \'none\' -%}\r\n                  selection/id:\r\n                    params:\r\n                      mode: {{prompt_mode}}\r\n                  {% endif -%}\r\n                  text/name:\r\n                    params:\r\n                      bold@bool: yes\r\n                  text/description:\r\n    \r\n    outcome/record_chooser:\r\n      if@bool: {{prompt_style == \'record_chooser\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            elements:\r\n              sheet/prompt_record_type:\r\n                label: What record type?\r\n                required@bool: yes\r\n                data:\r\n                  automation:\r\n                    uri: cerb:automation:cerb.data.record.types\r\n                limit: 50\r\n                default: ticket\r\n                schema:\r\n                  layout:\r\n                    headings@bool: no\r\n                    paging@bool: yes\r\n                    filtering@bool: yes\r\n                    style: grid\r\n                  columns:\r\n                    selection/uri:\r\n                      params:\r\n                        mode: single\r\n                        label_key: label_plural\r\n              sheet/prompt_mode:\r\n                label: Row selection:\r\n                required@bool: yes\r\n                data:\r\n                  none:\r\n                    key: none\r\n                    name: None\r\n                    description: No selection\r\n                  single:\r\n                    key: single\r\n                    name: Single\r\n                    description: Select a single record\r\n                  option2:\r\n                    key: multiple\r\n                    name: Multiple\r\n                    description: Select multiple records\r\n                limit: 5\r\n                default: single\r\n                schema:\r\n                  layout:\r\n                    headings@bool: no\r\n                    paging@bool: no\r\n                    style: grid\r\n                  columns:\r\n                    selection/key:\r\n                      params:\r\n                        mode: single\r\n                    text/name:\r\n                      params:\r\n                        bold@bool: yes\r\n                    text/description:\r\n        return:\r\n          snippet@text:\r\n            sheet/prompt_record:\r\n              label: Label:\r\n              required@bool: yes\r\n              data:\r\n                automation:\r\n                  uri: cerb:automation:cerb.data.records\r\n                  inputs:\r\n                    record_type: {{prompt_record_type}}\r\n                    # [TODO] Your search query goes here\r\n                    query@text:\r\n              limit: 10\r\n              #default: option1\r\n              schema:\r\n                layout:\r\n                  headings@bool: no\r\n                  paging@bool: no\r\n                  filtering@bool: yes\r\n                  title_column: _label\r\n                columns:\r\n                  {% if prompt_mode != \'none\' -%}\r\n                  selection/id:\r\n                    params:\r\n                      mode: {{prompt_mode}}\r\n                  {% endif -%}\r\n                  {% if prompt_record_type == \'ticket\' -%}\r\n                  card/_label:\r\n                    params:\r\n                      bold@bool: yes\r\n                      image@bool: yes\r\n                  card/owner__label:\r\n                  card/group__label:\r\n                  text/status:\r\n                  date/updated:\r\n                  {% else -%}\r\n                  card/_label:\r\n                    params:\r\n                      bold@bool: yes\r\n                      #image@bool: yes\r\n                  {% endif -%}\r\n\r\n    outcome/record_types:\r\n      if@bool: {{prompt_style == \'record_types\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            title: Prompt for record type\r\n            elements:\r\n              sheet/prompt_mode:\r\n                label: Row selection:\r\n                required@bool: yes\r\n                data:\r\n                  none:\r\n                    key: none\r\n                    name: None\r\n                    description: No selection\r\n                  single:\r\n                    key: single\r\n                    name: Single\r\n                    description: Select a single record type\r\n                  option2:\r\n                    key: multiple\r\n                    name: Multiple\r\n                    description: Select multiple record types\r\n                limit: 5\r\n                default: single\r\n                schema:\r\n                  layout:\r\n                    headings@bool: no\r\n                    paging@bool: no\r\n                    style: grid\r\n                  columns:\r\n                    selection/key:\r\n                      params:\r\n                        mode: single\r\n                    text/name:\r\n                      params:\r\n                        bold@bool: yes\r\n                    text/description:\r\n        return:\r\n          snippet@text:\r\n            sheet/prompt_record_type:\r\n              label: Label:\r\n              required@bool: yes\r\n              data:\r\n                automation:\r\n                  uri: cerb:automation:cerb.data.record.types\r\n              limit: 100\r\n              schema:\r\n                layout:\r\n                  headings@bool: no\r\n                  paging@bool: no\r\n                  filtering@bool: yes\r\n                  title_column: label_singular\r\n                  style: grid\r\n                columns:\r\n                  {% if prompt_mode != \'none\' -%}\r\n                  selection/id:\r\n                    params:\r\n                      mode: {{prompt_mode}}\r\n                  {% endif -%}\r\n                  text/label_singular:\r\n                    params:\r\n                      bold@bool: yes\r\n                      #image@bool: yes\r\n','');
INSERT INTO `automation` VALUES (24,'ai.cerb.automationBuilder.interaction.worker.await.promptText','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/field:\r\n    form:\r\n      title: Prompt for text\r\n      elements:\r\n        text/prompt_label:\r\n          label: Label:\r\n          required@bool: yes\r\n          \r\n        sheet/prompt_type:\r\n          label: Type:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              {\r\n                \"key\": \"freeform\",\r\n                \"name\": \"Freeform\",\r\n                \"description\": \"An arbitrary string of text\"\r\n              },\r\n              {\r\n                \"key\": \"bool\",\r\n                \"name\": \"Boolean\",\r\n                \"description\": \"true or false\"\r\n              },\r\n              {\r\n                \"key\": \"date\",\r\n                \"name\": \"Date\",\r\n                \"description\": \"tomorrow 5pm, +2 weeks, Friday\"\r\n              },\r\n              {\r\n                \"key\": \"decimal\",\r\n                \"name\": \"Decimal\",\r\n                \"description\": \"3.1415\"\r\n              },\r\n              {\r\n                \"key\": \"email\",\r\n                \"name\": \"Email\",\r\n                \"description\": \"client@example.com\"\r\n              },\r\n              {\r\n                \"key\": \"geopoint\",\r\n                \"name\": \"Geopoint\",\r\n                \"description\": \"44.226737, 20.7953 (lat, long)\"\r\n              },\r\n              {\r\n                \"key\": \"ip\",\r\n                \"name\": \"IP\",\r\n                \"description\": \"1.2.3.4 or a1b2:c3d4:e5f6:a1b2:c3d4:e5f6:a1b2:c3d4\"\r\n              },\r\n              {\r\n                \"key\": \"IPv4\",\r\n                \"name\": \"IPv4\",\r\n                \"description\": \"1.2.3.4\"\r\n              },\r\n              {\r\n                \"key\": \"IPv6\",\r\n                \"name\": \"IPv6\",\r\n                \"description\": \"a1b2:c3d4:e5f6:a1b2:c3d4:e5f6:a1b2:c3d4\"\r\n              },\r\n              {\r\n                \"key\": \"number\",\r\n                \"name\": \"Number\",\r\n                \"description\": \"1234\"\r\n              },\r\n              {\r\n                \"key\": \"record_type\",\r\n                \"name\": \"Record Type\",\r\n                \"description\": \"address, comment, ticket, worker\"\r\n              },\r\n              {\r\n                \"key\": \"timestamp\",\r\n                \"name\": \"Timestamp\",\r\n                \"description\": \"UNIX_TIMESTAMP()\"\r\n              },\r\n              {\r\n                \"key\": \"uri\",\r\n                \"name\": \"URI\",\r\n                \"description\": \"alphanumeric_with_underscores (a-z, 0-9, _)\"\r\n              },\r\n              {\r\n                \"key\": \"url\",\r\n                \"name\": \"URL\",\r\n                \"description\": \"https://example.com/path/file.png\"\r\n              }\r\n            ]\r\n          default: freeform\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n              text/name:\r\n                params:\r\n                  bold@bool: yes\r\n              text/description:\r\n              \r\n        sheet/prompt_required:\r\n          label: Required:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              { \"name\": \"yes\" },\r\n              { \"name\": \"no\" }\r\n            ]\r\n          limit: 10\r\n          default: yes\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n            columns:\r\n              selection/_selection:\r\n                params:\r\n                  mode: single\r\n                  value_key: name\r\n              text/name:\r\n              \r\n  await/params:\r\n    form:\r\n      elements:\r\n        text/prompt_default:\r\n          label: Default:\r\n          default@text:\r\n            {% if \'bool\' == prompt_type -%}\r\n            true\r\n            {% endif -%}\r\n            \r\n        text/prompt_placeholder:\r\n          label: Placeholder:\r\n          default@text:\r\n            {% if \'bool\' == prompt_type -%}\r\n            true or false\r\n            {% endif -%}\r\n                \r\n        text/prompt_max_length:\r\n          label: Max Length:\r\n          type: number\r\n          hidden@bool:\r\n            {% if \'bool\' == prompt_type -%}\r\n            yes\r\n            {% endif -%}\r\n            \r\n  return:\r\n    snippet@text:\r\n      text/prompt_{{random_string(6)|lower}}:\r\n        label: {{prompt_label}}\r\n        required@bool: {{prompt_required == true ? \'yes\'}}\r\n        type: {{prompt_type}}\r\n        {% if prompt_default -%}\r\n        default@text:\r\n          {{prompt_default|indent(\'    \',2)}}\r\n        {% endif -%}\r\n        {% if prompt_placeholder -%}\r\n        placeholder: {{prompt_placeholder}}\r\n        {% endif -%}\r\n        {% if prompt_max_length -%}\r\n        max_length: {{prompt_max_length}}\r\n        {% endif -%}\r\n','');
INSERT INTO `automation` VALUES (25,'ai.cerb.automationBuilder.interaction.worker.await.say','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        editor/prompt_message:\r\n          label: Message:\r\n          mode: markdown\r\n          required@bool: yes\r\n  \r\n        sheet/prompt_format:\r\n          label: Format:\r\n          required@bool: yes\r\n          data@json:\r\n            [\r\n              {\r\n                \"key\": \"markdown\",\r\n                \"name\": \"Markdown\",\r\n                \"description\": \"Formatting with Markdown\"\r\n              },\r\n              {\r\n                \"key\": \"text\",\r\n                \"name\": \"Text\",\r\n                \"description\": \"Text with no formatting\"\r\n              }\r\n            ]\r\n          default: markdown\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              title_column: name\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n              text/name:\r\n                params:\r\n                  bold@bool: yes\r\n              text/description:\r\n\r\n  return:\r\n    snippet@text:\r\n      say/respond_{{random_string(6)|lower}}:\r\n        {{prompt_format == \'markdown\' ? \'content\' : \'message\'}}@text:\r\n          {{prompt_message|indent(\'    \', 2)}}\r\n','');
INSERT INTO `automation` VALUES (26,'ai.cerb.cardEditor.automation.triggerChooser','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        sheet/prompt_trigger:\r\n          label: Trigger:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.platform.extensions\r\n              inputs:\r\n                point: cerb.automation.trigger\r\n          limit: 50\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n              title_column: name\r\n              style: columns\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n                  label_key: name\r\n              text/description:\r\n                params:\r\n                  value_template@raw: {{params.description}}\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n  \r\n  return:\r\n    trigger:\r\n      id: {{prompt_trigger}}\r\n      name: {{prompt_trigger}}','');
INSERT INTO `automation` VALUES (27,'ai.cerb.editor.mapBuilder','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Map Builder\r\n      elements:\r\n        sheet/prompt_map_resource:\r\n          label: Resource:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: resource\r\n          limit: 5\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n            columns:\r\n              selection/name:\r\n                params:\r\n                  mode: single\r\n              card/_label:\r\n                params:\r\n                  bold@bool: yes\r\n        \r\n        sheet/prompt_projection:\r\n          label: Projection:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              key: mercator\r\n              name: Mercator\r\n              description: Optimized for flat representation of regions\r\n            1:\r\n              key: naturalEarth\r\n              name: Natural Earth\r\n              description: Optimized for full world view\r\n            2:\r\n              key: albersUsa\r\n              name: Albers (USA)\r\n              description: Optimized for a condensed view of all 50 states\r\n          limit: 5\r\n          default: mercator\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n              text/name:\r\n                params:\r\n                  bold@bool: yes\r\n              text/description:\r\n  return:\r\n    snippet@text:\r\n      map:\r\n        resource:\r\n          uri: cerb:automation:{{prompt_map_resource}}\r\n        projection:\r\n          type: {{prompt_projection}}\r\n          scale: 90\r\n          center:\r\n            longitude: 0\r\n            latitude: 0\r\n        #regions:\r\n        #points:','');
INSERT INTO `automation` VALUES (28,'ai.cerb.eventHandler.automation','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  outcome/notRoot:\r\n    if@bool: {{\'\' != caller_params.token_path}}\r\n    then:\r\n      await:\r\n        form:\r\n          title: Automation Event Editor\r\n          elements:\r\n            say:\r\n              content@text:\r\n                #### You can only add automations at the root level (no indentation).\r\n            submit:\r\n              buttons:\r\n                continue/close:\r\n                  label: Close\r\n                  value: close\r\n      return:\r\n  \r\n  await:\r\n    form:\r\n      title: Automation Event Builder\r\n      elements:\r\n        sheet/prompt_automation_id:\r\n          label: Choose an automation:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: automation\r\n                query@text:\r\n                  trigger:${trigger} sort:name\r\n                query_params:\r\n                  trigger: {{caller_params.trigger}}\r\n          limit: 20\r\n          required@bool: yes\r\n          schema:\r\n            layout:\r\n              paging@bool: yes\r\n              headings@bool: no\r\n              filtering@bool: yes\r\n              style: columns\r\n              params:\r\n                width: 300\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n                  label_key: _label\r\n              text/description:\r\n          toolbar:\r\n            interaction/add:\r\n              label: Create\r\n              icon: circle-plus\r\n              hidden@bool: {{not worker_is_superuser}}\r\n              uri: cerb:automation:ai.cerb.automation.create\r\n        \r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  set/load_automation:\r\n    automation_data__context: automation\r\n    automation_data_id@key: prompt_automation_id\r\n    snippet_uid: {{random_string(6)|lower}}\r\n    _load_inputs: {% do automation_data_inputs %}\r\n    \r\n  var.set/snippet:\r\n    inputs:\r\n      key: snippet:automation/{{snippet_uid}}\r\n      value:\r\n        uri: cerb:automation:{{automation_data_name}}\r\n        disabled@raw,bool: no\r\n  \r\n  outcome/inputs:\r\n    if@bool:\r\n      {{\r\n        automation_data_inputs is iterable\r\n        and automation_data_inputs is not empty\r\n      }}\r\n    then:\r\n      repeat:\r\n        each@csv: {{automation_data_inputs|keys|join(\',\')}}\r\n        as: idx\r\n        do:\r\n          decision/type:\r\n            outcome/array:\r\n              if@bool: {{\'array\' == automation_data_inputs[idx].type}}\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:automation/{{snippet_uid}}:inputs:{{automation_data_inputs[idx].key}}\r\n                    value@list:\r\n                      Option 1\r\n                      Option 2\r\n            outcome/record:\r\n              if@bool: {{\'record\' == automation_data_inputs[idx].type}}\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:automation/{{snippet_uid}}:inputs:{{automation_data_inputs[idx].key}}\r\n                    value@int: 123\r\n            outcome/records:\r\n              if@bool: {{\'records\' == automation_data_inputs[idx].type}}\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:automation/{{snippet_uid}}:inputs:{{automation_data_inputs[idx].key}}\r\n                    value@csv: 1,2,3\r\n            outcome/else:\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:automation/{{snippet_uid}}:inputs:{{automation_data_inputs[idx].key}}\r\n                    value: your value\r\n                \r\n  return:\r\n    snippet@text: {{snippet|kata_encode}}','');
INSERT INTO `automation` VALUES (29,'ai.cerb.toolbarBuilder.interaction','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        say/heading:\r\n          content: ## Add Interaction\r\n        \r\n        text/prompt_label:\r\n          label: Label:\r\n          required@bool: yes\r\n          type: freeform\r\n        \r\n        sheet/prompt_interaction_id:\r\n          label: Interaction:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: automation\r\n                query@text:\r\n                  trigger:cerb.trigger.interaction.worker\r\n          limit: 10\r\n          required@bool: yes\r\n          schema:\r\n            layout:\r\n              paging@bool: yes\r\n              headings@bool: no\r\n              filtering@bool: yes\r\n              title_column: _label\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n              text/_label:\r\n                params:\r\n                  bold@bool: yes\r\n              text/description:\r\n        \r\n        sheet/prompt_icon:\r\n          label: Icon:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.ui.icons\r\n          limit: 30\r\n          #default: menu-hamburger\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              headings@bool: no\r\n              #paging@bool: no\r\n              filtering@bool: yes\r\n            columns:\r\n              selection/icon:\r\n                params:\r\n                  mode: single\r\n              text/preview:\r\n                params:\r\n                  value_template@raw:\r\n                    <span class=\"glyphicons glyphicons-{{icon}}\" style=\"font-size:150%;\"></span> {{icon}}\r\n  \r\n  set/load_automation:\r\n    interaction_data__context: automation\r\n    interaction_data_id@key: prompt_interaction_id\r\n  \r\n  return:\r\n    snippet@text:\r\n      interaction/{{random_string(6)|lower}}:\r\n        label: {{prompt_label}}\r\n        uri: cerb:automation:{{interaction_data_name}}\r\n        {% if prompt_icon -%}\r\n        icon: {{prompt_icon}}\r\n        {% endif -%}\r\n        #hidden@bool: {% verbatim %}{{row_selections ? \'no\' : \'yes\'}}{% endverbatim %}\r\n        #badge: 0\r\n        {% set inputs = interaction_data_inputs -%}\r\n        {% if inputs -%}\r\n        inputs:\r\n        {% for input in inputs %}\r\n        {{input.key}}:\r\n        {% endfor -%}\r\n        {% endif -%}\r\n        after:\r\n          #refresh_widgets@list: Actions\r\n','');
INSERT INTO `automation` VALUES (30,'ai.cerb.toolbarBuilder.menu','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        say/heading:\r\n          content: ## Add Menu\r\n  \r\n        text/prompt_label:\r\n          label: Label:\r\n          required@bool: yes\r\n          type: freeform\r\n          default: Menu\r\n  \r\n        sheet/prompt_icon:\r\n          label: Icon:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.ui.icons\r\n          limit: 30\r\n          filter: down\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n            columns:\r\n              selection/icon:\r\n                params:\r\n                  mode: single\r\n              text/preview:\r\n                params:\r\n                  value_template@raw:\r\n                    <span class=\"glyphicons glyphicons-{{icon}}\" style=\"font-size:150%;\"></span> {{icon}}\r\n\r\n  return:\r\n    snippet@text:\r\n      menu/menu_{{random_string(6)|lower}}:\r\n        label: {{prompt_label}}\r\n        icon: {{prompt_icon}}\r\n        #hidden@bool: no\r\n        #badge: 0\r\n        items:\r\n          # menu items','');
INSERT INTO `automation` VALUES (31,'cerb.data.platform.extensions','A filterable, pageable list of platform extensions','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/point:\r\n    required@bool: yes\r\n\r\nstart:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query@text:\r\n        type:platform.extensions\r\n        point:{{inputs.point}}\r\n        {% if sheet_filter -%}\r\n        filter: {{sheet_filter}}\r\n        {% endif -%}\r\n        {% if sheet_limit -%}\r\n        limit: {{sheet_limit}}\r\n        {% endif -%}\r\n        {% if sheet_page -%}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        format: dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of\r\n    on_error:\r\n      error:\r\n        message@key: results:errorstart:\r\n  ','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (32,'cerb.data.record.fields','A filterable, pageable list of record fields','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/of:\r\n    type: record_type\r\n    required@bool: yes\r\n\r\nstart:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query@text:\r\n        type: record.fields\r\n        of: {{inputs.of}}\r\n        {% if sheet_filter -%}\r\n        filter: {{sheet_filter}}\r\n        {% endif -%}\r\n        {% if sheet_limit -%}\r\n        limit: {{sheet_limit}}\r\n        {% endif -%}\r\n        {% if sheet_page -%}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        format: dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of\r\n    on_error:\r\n      error:\r\n        message@key: results:error','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (33,'cerb.data.record.types','A filterable, pageable list of record types','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query@text:\r\n        type: record.types\r\n        {% if sheet_filter -%}\r\n        filter: {{sheet_filter}}\r\n        {% endif -%}\r\n        {% if sheet_limit -%}\r\n        limit: {{sheet_limit}}\r\n        {% endif -%}\r\n        {% if sheet_page -%}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        format: dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of\r\n    on_error:\r\n      error:\r\n        message@key: results:error','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (34,'cerb.data.records','A filterable, pageable list of a given record type','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/record_type:\r\n    type: record_type\r\n    required@bool: yes\r\n  text/query_required:\r\n    type: freeform\r\n  text/query:\r\n    type: freeform\r\n    default: {{inputs.query_required}}\r\n  array/query_params:\r\n    default@json: []\r\n\r\nstart:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query_params@key: inputs:query_params\r\n      query@text:\r\n        type: worklist.records\r\n        of: {{inputs.record_type}}\r\n        query.required:(\r\n          {{inputs.query}}\r\n          {% if sheet_limit %}limit: {{sheet_limit}}{% endif %}\r\n        )\r\n        {% if sheet_filter -%}\r\n        query:(\r\n          {{sheet_filter}}\r\n        )\r\n        {% endif -%}\r\n        {% if sheet_limit and sheet_page -%}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        format: dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of\r\n    on_error:\r\n      error:\r\n        message@key: results:error','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (35,'cerb.data.ui.icons','A filterable, pageable list of icons','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query@text:\r\n        type:ui.icons\r\n        {% if sheet_limit -%}\r\n        limit: {{sheet_limit}}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        {% if sheet_filter -%}\r\n        filter: {{sheet_filter}}\r\n        {% endif -%}\r\n        format:dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (36,'cerb.editor.toolbar.indentSelection','Indent selected lines with a given `prefix`','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/prefix:\r\n    required@bool: true\r\n\r\nstart:\r\n  return:\r\n    snippet@text:\r\n      {{caller_params.selected_text is empty ? inputs.prefix : caller_params.selected_text|indent(inputs.prefix)}}','');
INSERT INTO `automation` VALUES (37,'cerb.editor.toolbar.markdownImage','Insert an image with Markdown formatting','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Insert an image\r\n      elements:\r\n        fileUpload/prompt_file_id:\r\n          label: File:\r\n          required@bool: yes\r\n        text/prompt_alt:\r\n          label: Alternate text:\r\n          type: freeform\r\n          #default:\r\n  set:\r\n    prompt_file__context: attachment\r\n  return:\r\n    snippet@text,trim:\r\n      ![{{prompt_alt|default(prompt_file__label)}}]({{prompt_file_url_download}})','');
INSERT INTO `automation` VALUES (38,'cerb.editor.toolbar.markdownLink','Insert a Markdown link','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      elements:\r\n        text/prompt_url:\r\n          label: URL:\r\n          required@bool: yes\r\n          type: url\r\n          placeholder: https://example.com/\r\n          max_length@int: 2048\r\n        text/prompt_label:\r\n          label: Label:\r\n          type: freeform\r\n          default: {{caller_params.selected_text}}\r\n  \r\n  return:\r\n    snippet@text,trim:\r\n      {% if prompt_label %}\r\n      [{{prompt_label}}]({{prompt_url}})\r\n      {% else %}\r\n      <{{prompt_url}}>\r\n      {% endif %}','');
INSERT INTO `automation` VALUES (39,'cerb.editor.toolbar.markdownTable','Insert a Markdown formatted table','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  return:\r\n    snippet@text:\r\n      | Column1 | Column 2 | Column 3\r\n      |-|-|-\r\n      | Value 1 | Value 2 | Value 3\r\n      ','');
INSERT INTO `automation` VALUES (40,'cerb.editor.toolbar.wrapSelection','Wrap selected text using `start_with` and `end_with` sequences','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/start_with:\r\n    required@bool: true\r\n  text/end_with:\r\n\r\nstart:\r\n  return:\r\n    snippet@text:\r\n      {{inputs.start_with}}{{caller_params.selected_text}}{{inputs.end_with|default(inputs.start_with)}}','');
INSERT INTO `automation` VALUES (41,'cerb.mail.compose','Compose a new message','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/record_type:\r\n    type: record_type\r\n    required@bool: yes\r\n  text/record_id:\r\n    type: number\r\n    required@bool: yes\r\n\r\nstart:\r\n  record.get/load:\r\n    output: record\r\n    inputs:\r\n      record_type@key: inputs:record_type\r\n      record_id@key: inputs:record_id\r\n  \r\n  # Create a draft based on the record type (address, contact, org)\r\n  decision/type:\r\n    outcome/address:\r\n      if@bool: {{inputs.record_type is record type (\'address\')}}\r\n      then:\r\n        record.create:\r\n          output: draft_record\r\n          inputs:\r\n            record_type: draft\r\n            # See: https://cerb.ai/docs/records/types/draft/\r\n            fields:\r\n              name: Draft for {{record.email}}\r\n              type: mail.compose\r\n              worker_id@key,int: worker_id\r\n              params:\r\n                to: {{record.email}}\r\n                org_name: {{record.org_name}}\r\n                content@text:\r\n                  {% if record.contact_first_name %}\r\n                  Hi {{record.contact_first_name}},\r\n                  \r\n                  {% endif %}\r\n                  \r\n                  #signature\r\n    outcome/contact:\r\n      if@bool: {{inputs.record_type is record type (\'contact\')}}\r\n      then:\r\n        record.create:\r\n          output: draft_record\r\n          inputs:\r\n            record_type: draft\r\n            # See: https://cerb.ai/docs/records/types/draft/\r\n            fields:\r\n              name: Draft for {{record.email__label}}\r\n              type: mail.compose\r\n              worker_id@key,int: worker_id\r\n              params:\r\n                to: {{record.email__label}}\r\n                org_name: {{record.org__label}}\r\n                content@text:\r\n                  {% if record.first_name %}\r\n                  Hi {{record.first_name}},\r\n                  \r\n                  {% endif %}\r\n                  \r\n                  #signature\r\n    outcome/org:\r\n      if@bool: {{inputs.record_type is record type (\'org\')}}\r\n      then:\r\n        record.create:\r\n          output: draft_record\r\n          inputs:\r\n            record_type: draft\r\n            # See: https://cerb.ai/docs/records/types/draft/\r\n            fields:\r\n              name: Draft for {{record.name}}\r\n              type: mail.compose\r\n              worker_id@key,int: worker_id\r\n              params:\r\n                to: {{record.email__label}}\r\n                org_name: {{record.name}}\r\n                content@text:\r\n                  Hi {{record.name}},\r\n                  \r\n                  #signature\r\n    outcome/else:\r\n      then:\r\n        record.create:\r\n          output: draft_record\r\n          inputs:\r\n            record_type: draft\r\n            # See: https://cerb.ai/docs/records/types/draft/\r\n            fields:\r\n              name: Draft by {{worker__label}}\r\n              type: mail.compose\r\n              worker_id@key,int: worker_id\r\n              params:\r\n                to@text:\r\n                content@text:\r\n                  \r\n                  \r\n                  #signature\r\n\r\n  await/draft:\r\n    draft:\r\n      uri: cerb:draft:{{draft_record.id}}\r\n      output: results_draft\r\n  \r\n  decision/draft_status:\r\n    outcome/sent:\r\n      if@bool: {{results_draft.status ends with \'.sent\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            elements:\r\n              sheet/draft:\r\n                data:\r\n                  0:\r\n                    id: {{results_draft.record.id}}\r\n                    _context: {{results_draft.record._context}}\r\n                    _label: {{results_draft.record._label}}\r\n                schema:\r\n                  columns:\r\n                    card/_label:\r\n                      label: Message sent!\r\n    outcome/draft:\r\n      if@bool: {{results_draft.status ends with \'.draft\'}}\r\n      then:\r\n        await:\r\n          form:\r\n            elements:\r\n              sheet/draft:\r\n                data:\r\n                  0:\r\n                    id: {{results_draft.record.id}}\r\n                    _context: {{results_draft.record._context}}\r\n                    _label: {{results_draft.record._label}}\r\n                schema:\r\n                  columns:\r\n                    card/_label:\r\n                      label: Draft saved!\r\n    outcome/discard:\r\n      if@bool: {{results_draft.status ends with \'.discard\'}}','commands:\r\n  record.get:\r\n    deny@bool: {{inputs.record_type is not record type (\'address\', \'contact\', \'org\')}}\r\n    allow@bool: yes\r\n  record.create:\r\n    deny@bool: {{inputs.record_type is not record type (\'draft\')}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (42,'cerb.mailFilterBlacklist','Rejects delivery of an incoming message','cerb.trigger.mail.filter',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  return:\r\n    reject@bool: true','');
INSERT INTO `automation` VALUES (43,'cerb.mailRouting.moveToGroup','Move a matching ticket to a group inbox','cerb.trigger.mail.route',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\n  text/group_name:\n    type: freeform\n    required@bool: yes\n    snippet:\n      group_name: Support\n  text/bucket_name:\n    type: freeform\n    default@text:\n    snippet:\n      bucket_name: Inbox\n\nstart:\n  return:\n    group_name: {{inputs.group_name}}\n    bucket_name@optional: {{inputs.bucket_name}}','');
INSERT INTO `automation` VALUES (44,'cerb.mailRouting.recipientRules','Route email to a group based on recipient email patterns','cerb.trigger.mail.route',NULL,1565401032,UNIX_TIMESTAMP(),'inputs:\r\n  text/group_name:\r\n    type: freeform\r\n    required@bool: yes\r\n    snippet:\r\n      group_name: Support\r\n  text/bucket_name:\r\n    type: freeform\r\n    required@bool: no\r\n    snippet:\r\n      bucket_name: Inbox\r\n  array/email_patterns:\r\n    required@bool: yes\r\n    snippet:\r\n      email_patterns@list:\r\n        billing@cerb.example\r\n        support@*\r\n\r\nstart:\r\n  decision:\r\n    outcome:\r\n      if@bool:\r\n        {{array_matches(email_recipients, inputs.email_patterns) ? \'yes\'}}\r\n      then:\r\n        return:\r\n          group_name: {{inputs.group_name}}\r\n          bucket_name@optional: {{inputs.bucket_name}}\r\n','');
INSERT INTO `automation` VALUES (45,'cerb.map.clicked.sheet','Display a sheet based on properties of the selected GeoJSON feature','cerb.trigger.map.clicked',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  array/sheet:\r\n    required@bool: yes\r\n\r\nstart:\r\n  return:\r\n    sheet@key: inputs:sheet','');
INSERT INTO `automation` VALUES (46,'cerb.projectBoard.action.task.close','Close task cards when they enter this project board column','cerb.trigger.projectBoard.cardAction',NULL,1595204694,UNIX_TIMESTAMP(),'start:\r\n  decision:\r\n    outcome/task:\r\n      if@bool:\r\n        {{card__context is record type (\'task\')}}\r\n      then:\r\n        record.update:\r\n          output: record_task\r\n          inputs:\r\n            record_type: task\r\n            record_id: {{card_id}}\r\n            fields:\r\n              status: closed\r\n        return:','commands:\r\n  record.update:\r\n    allow@bool:\r\n      {{inputs.record_type|context_alias == \'task\' ? \'yes\'}}');
INSERT INTO `automation` VALUES (47,'cerb.projectBoard.card.done','Render a card with a completed style','cerb.trigger.projectBoard.renderCard',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  return:\r\n    sheet:\r\n      columns:\r\n        card/card__label:\r\n          params:\r\n            icon:\r\n              image: circle-ok\r\n','');
INSERT INTO `automation` VALUES (48,'cerb.projectBoard.card.sheet','Render an arbitrary sheet for a project board card','cerb.trigger.projectBoard.renderCard',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  array/sheet:\r\n    required@bool: yes\r\n    # [TODO] Schema definition\r\n\r\nstart:\r\n  return:\r\n    sheet@key: inputs:sheet','');
INSERT INTO `automation` VALUES (49,'cerb.projectBoard.record.create','Create a record and add it to a project board','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/record_type:\r\n    type: record_type\r\n    required@bool: yes\r\n  record/column:\r\n    record_type: project_board_column\r\n    required@bool: yes\r\n\r\nstart:\r\n  await:\r\n    record:\r\n      uri: cerb:{{inputs.record_type}}\r\n      output: result\r\n  outcome:\r\n    if@bool: {{result.record._context and result.record.id}}\r\n    then:\r\n      record.update:\r\n        output: new_record\r\n        inputs:\r\n          record_type: {{result.record._context}}\r\n          record_id: {{result.record.id}}\r\n          fields:\r\n            links@list:\r\n              project_board_column:{{inputs.column.id}}\r\n  ','commands:\r\n  record.update:\r\n    deny/fields@bool:\r\n      {{inputs.fields|keys is not same as [\'links\']}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (50,'cerb.projectBoard.toolbar.task.find','Find tasks','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/column:\r\n    record_type: project_board_column\r\n    required@bool: yes\r\n\r\nstart:\r\n  await:\r\n    form:\r\n      elements:\r\n        say/respond_jgnssn:\r\n          content@text:\r\n            ## Link tasks\r\n        sheet/prompt_tasks:\r\n          #label: Link tasks:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: task\r\n                query@text:\r\n                  status:!c\r\n                  links.project_board_column:!(\r\n                    board.id:${board_id}\r\n                  )\r\n                  sort:-id\r\n                query_params:\r\n                  board_id: {{inputs.column.board_id}}\r\n          limit: 15\r\n          #default: option1\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n              title_column: _label\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: multiple\r\n              card/_label:\r\n                params:\r\n                  bold@bool: yes\r\n              date/created:\r\n              slider/importance:\r\n              card/owner__label:\r\n                params:\r\n                  image@bool: yes\r\n              #text/description:\r\n  \r\n  repeat:\r\n    each@key: prompt_tasks\r\n    as: task_id\r\n    do:\r\n      var.push:\r\n        inputs:\r\n          key: task_links\r\n          value: task:{{task_id}}\r\n  \r\n  record.update:\r\n    output: record_updated\r\n    inputs:\r\n      record_type: project_board_column\r\n      record_id: {{inputs.column.id}}\r\n      fields:\r\n        links@key: task_links\r\n          \r\n','callers:\r\n  cerb.toolbar.projectBoardColumn:\r\n    allow@bool:\r\n      {{\r\n        cerb_record_writeable(\'project_board\', board_id, \'worker\', worker_id) \r\n        ? \'yes\'\r\n      }}\r\n\r\ncommands:\r\n  record.update:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (51,'cerb.reminder.remind.notification','Remind by notification','cerb.trigger.reminder.remind',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  record.create:\r\n    output: new_notification\r\n    inputs:\r\n      # See: https://cerb.ai/docs/records/types/notification/#records-api\r\n      record_type: notification\r\n      fields:\r\n        worker_id: {{reminder_worker_id}}\r\n        target__context: reminder\r\n        target_id: {{reminder_id}}\r\n        activity_point: custom.other\r\n        params:\r\n          message@raw: Reminder: {{reminder}}\r\n          variables:\r\n            reminder: {{reminder__label}}\r\n          urls:\r\n            reminder: ctx://{{reminder__context}}:{{reminder_id}}','commands:\r\n  record.create:\r\n    allow@bool:\r\n      {{\r\n        inputs.record_type|context_alias == \'notification\' \r\n      }}');
INSERT INTO `automation` VALUES (52,'cerb.ticket.move','An interaction for quickly moving tickets','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    record_type: ticket\r\n    required@bool: yes\r\n\r\nstart:\r\n  await/group:\r\n    form:\r\n      title: Move ticket\r\n      elements:\r\n        sheet/prompt_group_id:\r\n          label: To which group:\r\n          required@bool: yes\r\n          limit: 50\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: group\r\n                query: sort:name\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              filtering@bool: yes\r\n              headings@bool: no\r\n              paging@bool: yes\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n              text/_label:\r\n                label: Group\r\n                params:\r\n                  bold@bool: yes\r\n                  underline@bool: no\r\n                  icon:\r\n                    record_uri@raw: cerb:group:{{id}}\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  set/group:\r\n    group__context: group\r\n    group_id: {{prompt_group_id|round}}\r\n  \r\n  await/bucket:\r\n    form:\r\n      elements:\r\n        sheet/prompt_bucket_id:\r\n          label: To which bucket in {{group__label}}:\r\n          required@bool: yes\r\n          limit: 50\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: bucket\r\n                query@text,trim:\r\n                  group.id:${group_id} sort:name\r\n                query_params:\r\n                  group_id@int: {{prompt_group_id}}\r\n          schema:\r\n            layout:\r\n              style: grid\r\n              filtering@bool: yes\r\n              headings@bool: no\r\n              paging@bool: yes\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n              text/_label:\r\n                label: Bucket\r\n                params:\r\n                  bold@bool: yes\r\n                  underline@bool: no\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  set/bucket:\r\n    bucket__context: bucket\r\n    bucket_id: {{prompt_bucket_id|round}}\r\n  \r\n  record.update/ticket:\r\n    output: updated_ticket\r\n    inputs:\r\n      # See: https://cerb.ai/docs/records/types/ticket/#records-api\r\n      record_type: ticket\r\n      record_id: {{inputs.ticket.id}}\r\n      fields:\r\n        group_id: {{bucket_group_id}}\r\n        bucket_id: {{bucket_id}}\r\n  \r\n  ','commands:\r\n  record.update:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'ticket\')}}\r\n    deny/fields@bool: {{inputs.fields|keys is not same as [\'group_id\',\'bucket_id\']}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (53,'cerb.ticket.participants.add','Add participants to a ticket','cerb.trigger.interaction.worker',NULL,1597443747,UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    record_type: ticket\r\n    required@bool: yes\r\n\r\nstart:\r\n  await:\r\n    form:\r\n      elements:\r\n        sheet/prompt_participants:\r\n          label: Add participants:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: address\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              filtering@bool: yes\r\n              paging@bool: yes\r\n              title_column: _label\r\n            columns:\r\n              selection/id:\r\n              card/_label:\r\n                params:\r\n                  image: yes\r\n                  bold: yes\r\n              card/contact__label:\r\n              card/org__label:\r\n\r\n  record.update:\r\n    output: updated_record\r\n    inputs:\r\n      record_type: ticket\r\n      record_id: {{inputs.ticket.id}}\r\n      fields:\r\n        # See: https://cerb.ai/docs/records/types/ticket/\r\n        participant_ids: {{prompt_participants|join(\',\')}}\r\n    on_success:\r\n      return:\r\n    on_error:\r\n      error:\r\n','commands:\r\n  record.update:\r\n    allow@bool:\r\n      {{inputs.record_type|context_alias == \'ticket\' ? \'yes\'}}');
INSERT INTO `automation` VALUES (54,'cerb.ticket.participants.manage','Display ticket participants with add and remove actions','cerb.trigger.interaction.worker',NULL,1599700704,UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    record_type: ticket\r\n    required@bool: yes\r\n\r\nstart:\r\n  await:\r\n    form:\r\n      title: Edit Participants\r\n      elements:\r\n        sheet/prompt_participants:\r\n          label: Participants:\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: address\r\n                query@text:\r\n                  ticket.id:${ticket_id}\r\n                query_params:\r\n                  ticket_id@int: {{inputs.ticket.id}}\r\n          limit: 10\r\n          schema:\r\n            layout:\r\n              style: table\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              title_column: _label\r\n            columns:\r\n              selection/id:\r\n              card/_label:\r\n                params:\r\n                  image@bool: yes\r\n                  bold@bool: yes\r\n          toolbar:\r\n            interaction/add:\r\n              label: Add participants\r\n              uri: cerb:automation:cerb.ticket.participants.add\r\n              icon: circle-plus\r\n              inputs:\r\n                ticket: {{inputs.ticket.id}}\r\n            interaction/remove:\r\n              label@raw: Remove {{row_selections|length}} selected\r\n              uri: cerb:automation:cerb.ticket.participants.remove\r\n              icon: circle-remove\r\n              hidden@raw,bool:\r\n                {{row_selections is empty ? \'yes\'}}\r\n              inputs:\r\n                ticket: {{inputs.ticket.id}}\r\n                participants@raw,key: row_selections\r\n              event/done:\r\n                clear_selections@bool: yes\r\n','');
INSERT INTO `automation` VALUES (55,'cerb.ticket.participants.remove','Remove participants from a ticket','cerb.trigger.interaction.worker',NULL,1565231398,UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    record_type: ticket\r\n    required@bool: yes\r\n  records/participants:\r\n    record_type: address\r\n    required@bool: yes\r\n\r\n# [TODO] Check permissions on worker\r\nstart:\r\n  record.update:\r\n    output: record_result\r\n    inputs:\r\n      record_type: ticket\r\n      record_id: {{inputs.ticket.id}}\r\n      fields:\r\n        participant_ids: -{{array_column(inputs.participants,\'id\')|join(\',-\')}}\r\n    on_success:\r\n      return:\r\n        success: true\r\n    on_error:\r\n      error:\r\n        message: {{record_result.error}}\r\n','commands:\r\n  record.update:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (56,'ai.cerb.automation.create','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    record:\r\n      uri: cerb:automation\r\n      output: new_automation','');
INSERT INTO `automation` VALUES (57,'ai.cerb.eventHandler.automation.mail.received','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Generate an automation\r\n      elements:\r\n        sheet/prompt_type:\r\n          data:\r\n            0:\r\n              key: autoreply\r\n              label: Auto-reply\r\n              description: Send an auto-reply to new messages\r\n          schema:\r\n            layout:\r\n              filtering@bool: no\r\n              headings@bool: no\r\n              paging@bool: no\r\n              title_column: label\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n              text/label:\r\n              text/description:\r\n      \r\n  await/prompt:\r\n    form:\r\n      title: Prompts\r\n      elements:\r\n        text/prompt_name:\r\n          label: Name:\r\n          type: text\r\n          required@bool: yes\r\n          default: {{random_string(6)|lower}}.mail.received.autoReply\r\n          validation@text:\r\n            {% if prompt_name|alphanum(\'.-_\') != prompt_name %}\r\n            The name can only contain letters, numbers, dots, and dashes.\r\n            {% endif %}\r\n  \r\n  record.create/automation:\r\n    output: new_automation\r\n    inputs:\r\n      record_type: automation\r\n      fields:\r\n        name@key: prompt_name\r\n        description: Send an auto-reply for new inbound mail\r\n        extension_id: cerb.trigger.mail.received\r\n        script@raw:\r\n          start:\r\n            # Don\'t send auto-replies to automated senders\r\n            outcome/isAutoSender:\r\n              if@bool:\r\n                {{\r\n                  message_sender_email is prefixed (\'postmaster@\',\'mailer-daemon@\')\r\n                  or message_headers[\'auto-submitted\'] is prefixed (\'auto-\')\r\n                  or message_headers[\'precedence\'] == \'bulk\'\r\n                  or message_headers[\'preference\'] == \'auto_reply\'\r\n                  or message_headers[\'x-precedence\']\r\n                  or message_headers[\'x-autorespond\']\r\n                  or message_headers[\'x-autogenerated\']\r\n                  or message_headers[\'x-autoreply-from\']\r\n                  or \'autoreply\' in message_headers[\'x-auto-response-suppress\']|lower\r\n                  or \'out of office\' in message_headers[\'subject\']|lower\r\n                  or \'out of the office\' in message_headers[\'subject\']|lower\r\n                }}    \r\n              then:\r\n                return:\r\n            \r\n            # See: https://cerb.ai/docs/automations/commands/record.create/\r\n            record.create/draft:\r\n              output: new_draft\r\n              inputs:\r\n                record_type: draft\r\n                # See: https://cerb.ai/docs/records/types/draft/#records-api\r\n                fields:\r\n                  type: mail.transactional\r\n                  name: Auto-reply to {{message_sender_email}}\r\n                  to: {{message_sender_email}}\r\n                  is_queued: 1\r\n                  queue_delivery_date@date: now\r\n                  params:\r\n                    to: {{message_sender_email}}\r\n                    from: support@cerb.example\r\n                    subject: Auto-Reply: {{message_ticket_subject}}\r\n                    headers:\r\n                      Auto-Submitted: auto-replied\r\n                      Precedence: bulk\r\n                    content@text:\r\n                      Thanks for writing!\r\n                      \r\n                      Your reference number is #{{message_ticket_mask}}.\r\n        policy_kata@raw:\r\n          commands:\r\n            record.create:\r\n              deny/type@bool: {{inputs.record_type is not record type (\'draft\')}}\r\n              allow@bool: yes        \r\n  set:\r\n    snippet:\r\n      automation/autoReply:\r\n        uri: cerb:automation:{{prompt_name}}\r\n        disabled@raw,bool: {{not is_new_ticket}}\r\n  \r\n  return:\r\n    snippet: {{snippet|kata_encode}}','commands:\r\n  record.create:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'automation\')}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (58,'ai.cerb.timerEditor.schedule.add','Examples for the automation timer editor','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Add schedule by example\r\n      elements:\r\n        sheet/prompt_schedule:\r\n          data:\r\n            5min:\r\n              label: Every 5 mins\r\n              pattern@text:\r\n                # Every 5 mins\r\n                */5 * * * *\r\n                \r\n            1hr:\r\n              label: Every hour\r\n              pattern@text:\r\n                # Every hour\r\n                0 * * * *\r\n                \r\n            8am:\r\n              label: At 8am every day\r\n              pattern@text:\r\n                # At 8am every day\r\n                0 8 * * *\r\n                \r\n            5pm:\r\n              label: At 5:30pm every weekday\r\n              pattern@text:\r\n                # At 5:30pm every weekday\r\n                30 17 * * 1-5\r\n                \r\n            weekdays:\r\n              label: Once every weekday\r\n              pattern@text:\r\n                # Once every weekday\r\n                0 0 * * 1-5\r\n                \r\n            weekends:\r\n              label: Once every weekend\r\n              pattern@text:\r\n                # Once every weekend day\r\n                0 0 * * 6-7\r\n                \r\n            mon:\r\n              label: Monday\r\n              pattern@text:\r\n                # Once every Monday\r\n                0 0 * * 1\r\n                \r\n            tue:\r\n              label: Tuesday\r\n              pattern@text:\r\n                # Once every Tuesday\r\n                0 0 * * 2\r\n                \r\n            wed:\r\n              label: Wednesday\r\n              pattern@text:\r\n                # Once every Wednesday\r\n                0 0 * * 3\r\n                \r\n            thu:\r\n              label: Thursday\r\n              pattern@text:\r\n                # Once every Thursday\r\n                0 0 * * 4\r\n                \r\n            fri:\r\n              label: Friday\r\n              pattern@text:\r\n                # Once every Friday\r\n                0 0 * * 5\r\n                \r\n            sat:\r\n              label: Saturday\r\n              pattern@text:\r\n                # Once every Saturday\r\n                0 0 * * 6\r\n                \r\n            sun:\r\n              label: Sunday\r\n              pattern@text:\r\n                # Once every Sunday\r\n                0 0 * * 7\r\n                \r\n            1st:\r\n              label: First day of every month\r\n              pattern@text:\r\n                # First day of every month\r\n                0 0 1 * *\r\n                \r\n            ldon:\r\n              label: Last day of every month\r\n              pattern@text:\r\n                # Last day of every month\r\n                0 0 L * *\r\n            \r\n            jan1:\r\n              label: Every year on Jan 1\r\n              pattern@text:\r\n                # Every year on Jan 1\r\n                0 0 1 1 *\r\n                \r\n            thanksgiving:\r\n              label: Last Thursday of November\r\n              pattern@text:\r\n                # Last Thursday of November\r\n                0 0 22-28 11 4\r\n                \r\n          schema:\r\n            layout:\r\n              filtering@bool: yes\r\n              paging@bool: yes\r\n              headings@bool: no\r\n              title_column: label\r\n            columns:\r\n              selection/pattern:\r\n                params:\r\n                  mode: single\r\n              text/label:\r\n                label: Examples\r\n  \r\n  return:\r\n    snippet@key: prompt_schedule','');
INSERT INTO `automation` VALUES (59,'cerb.compose.validation.to','Warns if sending a compose draft without any recipients','cerb.trigger.mail.draft.validate',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/draft:\r\n    record_type: draft\r\n    required@bool: yes\r\n    default: {{caller_params.draft_id}}\r\n\r\nstart:\r\n  outcome/notEmptyTo:\r\n    if@bool: {{inputs.draft.params.to}}\r\n    then:\r\n      return:\r\n  \r\n  await:\r\n    form:\r\n      title: Before you send that...\r\n      elements:\r\n        say:\r\n          content@text:\r\n            # You haven\'t specified any recipients\r\n            A new ticket will be created without sending any email. This is normal if you\'re working on an issue and you plan to add an email address later (e.g. phone call).\r\n            \r\n        submit/prompt_next:\r\n          buttons:\r\n            continue/yes:\r\n              label: Send without recipients\r\n              icon: send\r\n              icon_at: start\r\n            continue/no:\r\n              label: Whoops! I\'ll fix it\r\n              style: secondary\r\n              value: nope\r\n  \r\n  outcome/reject:\r\n    if@bool: {{\'nope\' == prompt_next}}\r\n    then:\r\n      return:\r\n        reject@bool: yes        \r\n            ','');
INSERT INTO `automation` VALUES (60,'ai.cerb.automationBuilder','','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  data.query:\r\n    inputs:\r\n      query@text:\r\n        type:autocomplete.completions\r\n        schema:automation\r\n        params:(\r\n          trigger:${trigger}\r\n          path:${path}\r\n        )\r\n        format:dictionaries\r\n      query_params:\r\n        trigger: {{caller_params.trigger}}\r\n        path: {{caller_params.token_path}}\r\n    output: results\r\n    on_success:\r\n      decision:\r\n        outcome/results:\r\n          if@bool:\r\n            {{\r\n              results.data is iterable\r\n              and results.data is not empty\r\n            }}\r\n          then:\r\n            await/suggestions:\r\n              form:\r\n                title: Automation Builder\r\n                elements:\r\n                  sheet/prompt_sheet:\r\n                    data@key: results:data\r\n                    required@bool: yes\r\n                    limit: 100\r\n                    schema:\r\n                      layout:\r\n                        style: columns\r\n                        headings@bool: no\r\n                        filtering@bool: yes\r\n                        paging@bool: yes\r\n                      columns:\r\n                        selection/__index:\r\n                          params:\r\n                            label_key: caption\r\n                            mode: single\r\n                        text/description:\r\n                  submit:\r\n                    continue@bool: no\r\n                    reset@bool: no\r\n            \r\n            decision/type:\r\n              outcome/hasInteraction:\r\n                if@bool: {{results.data[prompt_sheet].interaction}}\r\n                then:\r\n                  await:\r\n                    interaction:\r\n                      uri: {{results.data[prompt_sheet].interaction}}\r\n                      output: result\r\n                  return:\r\n                    snippet@key: result:snippet\r\n                      \r\n              outcome/else:\r\n                then:\r\n                  return:\r\n                    snippet: {{results.data[prompt_sheet].snippet}}\r\n        outcome/noResults:\r\n          then:\r\n            await:\r\n              form:\r\n                title: Automation Builder\r\n                elements:\r\n                  say:\r\n                    message@text:\r\n                      No suggestions are available at the current location.\r\n                  submit:\r\n                    buttons:\r\n                      continue/done:\r\n                        label: Cancel\r\n                        icon: circle-remove\r\n                        icon_at: start\r\n                      ','commands:\r\n  data.query:\r\n    deny/type@bool: {{query.type != \'autocomplete.completions\'}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (61,'ai.cerb.automationBuilder.action.metricIncrement','Helper for the `metric.increment:` command in the automation editor','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/metric:\r\n    form:\r\n      title: metric.increment:\r\n      elements:\r\n        sheet/prompt_metric:\r\n          label: Metric:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: metric\r\n                query@text:\r\n          limit: 20\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: yes\r\n              filtering@bool: yes\r\n              title_column: _label\r\n              style: columns\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n                  label_key: _label\r\n              text/description:\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n  \r\n  set:\r\n    metric__context: metric\r\n    metric_id@key: prompt_metric\r\n    snippet:\r\n      metric.increment:\r\n        inputs:\r\n          metric_name: {{metric_name}}\r\n        output: results\r\n        on_error:\r\n        on_success:\r\n  \r\n  outcome/hasDimensions:\r\n    if@bool: {{metric_dimensions}}\r\n    then:\r\n      repeat:\r\n        each@csv: {{metric_dimensions|keys|join(\',\')}}\r\n        as: dimension\r\n        do:\r\n          decision/type:\r\n            outcome/record:\r\n              if@bool: {{\'record\' == metric_dimensions[dimension].type}}\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:metric.increment:inputs:dimensions:{{dimension}}@int\r\n                    value@raw: {{record_id}}\r\n            outcome/number:\r\n              if@bool: {{\'number\' == metric_dimensions[dimension].type}}\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:metric.increment:inputs:dimensions:{{dimension}}@int\r\n                    value: 123\r\n            outcome/else:\r\n              then:\r\n                var.set:\r\n                  inputs:\r\n                    key: snippet:metric.increment:inputs:dimensions:{{dimension}}\r\n                    value: text\r\n  \r\n  return:\r\n    snippet: {{snippet|kata_encode}}','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (62,'ai.cerb.interaction.search','Global search menu','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/record_type:\r\n    type: freeform\r\n\r\nstart:\r\n  decision/hasRecordType:\r\n    outcome/yes:\r\n      if@bool: {{inputs.record_type}}\r\n      then:\r\n        return:\r\n          record_type@key: inputs:record_type\r\n    outcome/no:\r\n      then:\r\n        data.query/recordTypes:\r\n          output: results\r\n          inputs:\r\n            query@text:\r\n              type: record.types\r\n              options:[search]\r\n              format: dictionaries\r\n          on_success:\r\n            await:\r\n              form:\r\n                title: Search which record type?\r\n                elements:\r\n                  sheet/prompt_record_type:\r\n                    required@bool: yes\r\n                    data@key: results:data\r\n                    limit: 150\r\n                    schema:\r\n                      layout:\r\n                        headings@bool: no\r\n                        filtering@bool: yes\r\n                        paging@bool: yes\r\n                        style: columns\r\n                      columns:\r\n                        selection/id:\r\n                          params:\r\n                            mode: single\r\n                            label_key: label_plural\r\n                  submit:\r\n                    continue@bool: no\r\n                    reset@bool: no\r\n      \r\n            return:\r\n              record_type@key: prompt_record_type\r\n  ','commands:\r\n  data.query:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (63,'ai.cerb.metricBuilder.dimension','Helper for adding dimensions to a metric','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await/type:\r\n    form:\r\n      title: Add Dimension\r\n      elements:\r\n        text/prompt_name:\r\n          label: Name:\r\n          required@bool: yes\r\n          type: text\r\n          placeholder: (letters, numbers, underscores)\r\n          max_length: 64\r\n          validation@raw:\r\n            {% if prompt_name|alphanum(\'_\') != prompt_name %}\r\n            \'Name:\' may only contain letters, numbers, and underscores.\r\n            {% endif %}\r\n          \r\n        sheet/prompt_type:\r\n          label: Type:\r\n          required@bool: yes\r\n          data:\r\n            text:\r\n              key: text\r\n              name: Text\r\n              description: A single line of descriptive text (e.g. labels)\r\n            number:\r\n              key: number\r\n              name: Number\r\n              description: A positive whole number\r\n            record:\r\n              key: record\r\n              name: Record Link\r\n              description: A link to a related record\r\n            extension:\r\n              key: extension\r\n              name: Extension\r\n              description: A platform extension point (e.g. cerb.trigger)\r\n          limit: 5\r\n          default: text\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              style: columns\r\n            columns:\r\n              selection/key:\r\n                params:\r\n                  mode: single\r\n                  label_key: name\r\n              text/description:\r\n  \r\n  decision/type:\r\n    outcome/record:\r\n      if@bool: {{prompt_type == \'record\'}}\r\n      then:\r\n        await/recordType:\r\n          form:\r\n            title: Add record type dimension\r\n            elements:\r\n              sheet/prompt_record_type:\r\n                label: Type:\r\n                required@bool: yes\r\n                data:\r\n                  automation:\r\n                    uri: cerb:automation:cerb.data.record.types\r\n                limit: 100\r\n                schema:\r\n                  layout:\r\n                    headings@bool: no\r\n                    paging@bool: no\r\n                    filtering@bool: yes\r\n                    title_column: label_singular\r\n                    style: grid\r\n                  columns:\r\n                    selection/uri:\r\n                      params:\r\n                        mode: single\r\n                    text/label_singular:\r\n                      params:\r\n                        bold@bool: yes\r\n                        #image@bool: yes\r\n        return:\r\n          snippet@text:\r\n            record/{{prompt_name}}:\r\n              record_type: {{prompt_record_type}}\r\n            \r\n    \r\n    outcome/extension:\r\n      if@bool: {{prompt_type == \'extension\'}}\r\n      then:\r\n        return:\r\n          snippet@text:\r\n            extension/{{prompt_name}}:\r\n            \r\n\r\n    outcome/number:\r\n      if@bool: {{prompt_type == \'number\'}}\r\n      then:\r\n        return:\r\n          snippet@text:\r\n            number/{{prompt_name}}:\r\n            \r\n          \r\n    outcome/text:\r\n      then:\r\n        return:\r\n          snippet@text:\r\n            text/{{prompt_name}}:\r\n            ','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (64,'ai.cerb.metricBuilder.help','Help interaction for the metric editor','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Help\r\n      elements:\r\n        say/prompt_say:\r\n          content@text:\r\n            ## Metric Dimensions\r\n            \r\n            Each metric collects samples for a numeric value over time. This value could be a counter (+1 for each sample) or a gauge (a discrete reading at a specific time).\r\n            \r\n            Metrics may be further partitioned by including optional key/value pairs called \"dimensions\" with samples.\r\n            \r\n            For instance, if you add dimensions for group, bucket, and worker, then statistics may be calculated for any combination of those dimensions.\r\n            \r\n            Dimensions are defined using [KATA](https://cerb.ai/docs/kata/) syntax. Each dimension has a type that describes its value: text, record, or extension.\r\n            \r\n            Currently you may define up to three dimensions per metric.\r\n            ','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (65,'cerb.data.platform.extension.points','A filterable, pageable list of platform extension points','cerb.trigger.ui.sheet.data',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  data.query:\r\n    output: results\r\n    inputs:\r\n      query@text:\r\n        type: platform.extension.points\r\n        {% if sheet_filter -%}\r\n        filter: {{sheet_filter}}\r\n        {% endif -%}\r\n        {% if sheet_limit -%}\r\n        limit: {{sheet_limit}}\r\n        {% endif -%}\r\n        {% if sheet_page -%}\r\n        page: {{sheet_page}}\r\n        {% endif -%}\r\n        format: dictionaries\r\n    on_success:\r\n      return:\r\n        data@key: results:data\r\n        total@key: results:_:paging:page:rows:of\r\n    on_error:\r\n      error:','commands:\r\n  data.query:\r\n    deny/type@bool: {{query.type != \'platform.extension.points\'}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (66,'cerb.reminder.remind.email','Remind by email','cerb.trigger.reminder.remind',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  record.create:\r\n    output: new_draft\r\n    inputs:\r\n      record_type: draft\r\n      # See: https://cerb.ai/docs/records/types/draft/\r\n      fields:\r\n        type: mail.transactional\r\n        to: {{reminder_worker_address_email}}\r\n        name: Reminder: {{reminder__label}}\r\n        is_queued: 1\r\n        queue_delivery_date@date: now\r\n        params:\r\n          to: {{reminder_worker_address_email}}\r\n          subject: Reminder: {{reminder__label}}\r\n          headers:\r\n            Auto-Submitted: auto-generated\r\n          format: parsedown\r\n          content@text:\r\n            Reminder: {{reminder__label}}\r\n            When: {{reminder_remind_at|date(\'F d, Y h:ia\')}}\r\n            URL: {{reminder_record_url}}','commands:\r\n  record.create:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'draft\')}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (67,'cerb.reply.recentActivity','Check for recent activity before starting a reply','cerb.trigger.mail.reply.validate',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/message:\r\n    record_type: message\r\n    required@bool: yes\r\n    default: {{caller_params.message_id}}\r\n\r\nstart:\r\n  # Load active drafts on this ticket by other workers\r\n  record.search/drafts:\r\n    inputs:\r\n      record_type: draft\r\n      record_query@text:\r\n        ticket.id:${ticket_id} \r\n        worker.id:!${worker_id} \r\n        is.queued:no \r\n        updated:\"-15 mins to now\"\r\n      record_query_params:\r\n        ticket_id: {{inputs.message.ticket_id}}\r\n        worker_id: {{worker_id}}\r\n    output: drafts\r\n    on_success:\r\n      # If there are drafts\r\n      outcome/notEmpty:\r\n        if@bool: {{drafts is not empty and drafts is iterable}}\r\n        then:\r\n          await:\r\n            form:\r\n              title: Duplication of effort?\r\n              elements:\r\n                sheet/others:\r\n                  data@key: drafts\r\n                  label: Other workers are currently responding to this ticket:\r\n                  schema:\r\n                    columns:\r\n                      date/updated:\r\n                        label: When\r\n                      card/worker_id:\r\n                        label: Who\r\n                      card/id:\r\n                        label: Draft\r\n                submit/prompt_continue:\r\n                  buttons:\r\n                    continue/yes:\r\n                      label: Reply anyway\r\n                      icon: circle-ok\r\n                      icon_at: start\r\n                      value: yes\r\n                    continue/no:\r\n                      label: Abort\r\n                      style: secondary\r\n                      value: no\r\n          outcome/abort:\r\n            if@bool: {{\'yes\' != prompt_continue}}\r\n            then:\r\n              return:\r\n                reject@bool: true\r\n  \r\n  # Load recent activity log entries this ticket\r\n  record.search/logs:\r\n    inputs:\r\n      record_type: activity_log\r\n      record_query@text:\r\n        target.ticket:(id:${ticket_id})\r\n        created:\"-15 minutes\"\r\n        activity:[ticket.status.closed,ticket.status.waiting,ticket.status.deleted,ticket.message.outbound]\r\n        actor:worker\r\n        actor.worker:!(id:${worker_id})\r\n      record_query_params:\r\n        ticket_id: {{inputs.message.ticket_id}}\r\n        worker_id: {{worker_id}}\r\n    output: logs\r\n    on_success:\r\n      outcome/notEmpty:\r\n        if@bool: {{logs is not empty and logs is iterable}}\r\n        then:\r\n          await:\r\n            form:\r\n              title: Recent activity\r\n              elements:\r\n                sheet/recent:\r\n                  label: There is recent activity on this ticket:\r\n                  data@key: logs\r\n                  schema:\r\n                    layout:\r\n                      headings@bool: no\r\n                      filtering@bool: no\r\n                    columns:\r\n                      date/created:\r\n                      text/_label:\r\n                submit/prompt_continue:\r\n                  buttons:\r\n                    continue/yes:\r\n                      label: Reply anyway\r\n                      icon: circle-ok\r\n                      icon_at: start\r\n                      value: yes\r\n                    continue/no:\r\n                      label: Abort\r\n                      style: secondary\r\n                      value: no\r\n          outcome/abort:\r\n            if@bool: {{\'yes\' != prompt_continue}}\r\n            then:\r\n              return:\r\n                reject@bool: true\r\n','commands:\r\n  record.search:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'draft\',\'activity_log\')}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (68,'ai.cerb.automationBuilder.autocomplete.d3Format','Build a d3.format string','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Number Format\r\n      elements:\r\n        sheet/prompt_number_format:\r\n          label: Choose:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              format: ,\r\n              output: 1,234,567\r\n            1:\r\n              format: $,\r\n              output: $1,234,567\r\n            2:\r\n              format: .2f\r\n              output: 12345.67\r\n            3:\r\n              format: ,.2f\r\n              output: 12,345.67\r\n            4:\r\n              format: .2s\r\n              output: 1.2M\r\n            5:\r\n              format: .1%\r\n              output: 12.3%\r\n          limit: 30\r\n          default: ,.2f\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              style: grid\r\n            columns:\r\n              selection/format:\r\n                params:\r\n                  mode: single\r\n              text/output:\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  return:\r\n    snippet@key: prompt_number_format','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (69,'ai.cerb.automationBuilder.autocomplete.d3TimeFormat','Build a d3.timeFormat string','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  \r\n  await:\r\n    form:\r\n      title: Date Format\r\n      elements:\r\n        sheet/prompt_date_format:\r\n          label: Choose:\r\n          required@bool: yes\r\n          data:\r\n            0:\r\n              format: %Y\r\n              output: {{\'now\'|date(\'Y\')}}\r\n            1:\r\n              format: %Y-%m\r\n              output: {{\'now\'|date(\'Y-m\')}}\r\n            2:\r\n              format: %Y-%m-%d\r\n              output: {{\'now\'|date(\'Y-m-d\')}}\r\n            3:\r\n              format: %Y-%m-%d %H:%M\r\n              output: {{\'now\'|date(\'Y-m-d H:i\')}}\r\n            4:\r\n              format: %Y-%m-%d %H:%M:%S\r\n              output: {{\'now\'|date(\'Y-m-d H:i:s\')}}\r\n            5:\r\n              format: %B \'%y\r\n              output: {{\'now\'|date(\"F \'y\")}}\r\n            6:\r\n              format: %b \'%y\r\n              output: {{\'now\'|date(\"M \'y\")}}\r\n          limit: 30\r\n          default: %Y-%m-%d\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              style: grid\r\n            columns:\r\n              selection/format:\r\n                params:\r\n                  mode: single\r\n              text/output:\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n\r\n  return:\r\n    snippet@key: prompt_date_format','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (70,'ai.cerb.chooser.automationEvent','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'#\r\nstart:\r\n  await:\r\n    form:\r\n      elements:\r\n        sheet/prompt_event_id:\r\n          label: Trigger:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: automation_event\r\n                query: sort:name\r\n          limit: 50\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n              title_column: name\r\n              style: columns\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n                  label_key: name\r\n              text/description:\r\n                #params:\r\n                #  value_template@raw: {{params.description}}\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n  \r\n  set:\r\n    prompt_event__context: automation_event\r\n    prompt_event_id@key: prompt_event_id\r\n  \r\n  return:\r\n    event:\r\n      id: {{prompt_event_id}}\r\n      name: {{prompt_event_name}}','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (71,'ai.cerb.record.profileImageEditor.fetchUrl','Create a profile image from a URL','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Fetch image by URL\r\n      elements:\r\n        text/prompt_url:\r\n          label: URL:\r\n          required@bool: yes\r\n          type: url\r\n          placeholder: https://example.com/image.png\r\n          max_length: 1024\r\n  \r\n  return:\r\n    image:\r\n      url@key: prompt_url','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (72,'ai.cerb.record.profileImageEditor.text','Create a profile image from text','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Create image with text\r\n      elements:\r\n        text/prompt_text:\r\n          label: Text:\r\n          required@bool: yes\r\n          type: freeform\r\n          placeholder: Text or emoji\r\n          max_length: 32\r\n  \r\n  return:\r\n    image:\r\n      text@key: prompt_text','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (73,'ai.cerb.record.profileImageEditor.upload','Create a profile image from an uploaded file','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'start:\r\n  await:\r\n    form:\r\n      title: Upload Image\r\n      elements:\r\n        fileUpload/prompt_file:\r\n          label: Select an image file from your computer:\r\n          required@bool: yes\r\n          as: automation_resource\r\n  \r\n  return:\r\n    image:\r\n      url: {{cerb_url(\'c=ui&a=image&token=\' ~ prompt_file)}}','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (74,'cerb.explore.worklist','A custom explore mode that tracks real-time changes in a worklist and returns the top sorted unseen record. It maintains a circular ignore list of visited records.','cerb.trigger.interaction.worker.explore',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/worklist_id:\r\n    type: freeform\r\n    required@bool: yes\r\n\r\nstart:\r\n  set:\r\n    ignore_list@csv:\r\n  \r\n  while:\r\n    if@bool: {{true}}\r\n    do:\r\n      api.command:\r\n        output: currentWorklist\r\n        inputs:\r\n          name: cerb.commands.worklist.search\r\n          params:\r\n            worker_id: {{worker_id}}\r\n            worklist_id: {{inputs.worklist_id}}\r\n            worklist_query@text:\r\n              {% if ignore_list is not empty %}\r\n              id:![{{ignore_list|join(\',\')}}]\r\n              {% endif %}\r\n              page:0\r\n              limit:1\r\n        on_success:\r\n          set/next:\r\n            nextTicket@key: currentWorklist:data\r\n          # If no next record, end\r\n          decision/result:\r\n            outcome/empty:\r\n              if@bool: {{not nextTicket.record_url}}\r\n              then:\r\n                await:\r\n                  explore:\r\n                    title: {{currentWorklist.worklist.name}}\r\n                    label@text: \r\n                    toolbar:\r\n                      interaction/next:\r\n                        label: Refresh\r\n                        icon: refresh\r\n                        keyboard: ]\r\n            outcome/next:\r\n              then:\r\n                # Limit the ignore list to 50 items\r\n                set:\r\n                  ignore_list@json: {{ignore_list|slice(-49)|merge([nextTicket.id|round])|json_encode}}\r\n                await:\r\n                  explore:\r\n                    title: {{currentWorklist.worklist.name}}\r\n                    label: {{nextTicket._label}}\r\n                    url: {{nextTicket.record_url}}\r\n                    toolbar:\r\n                      interaction/next:\r\n                        label: Next\r\n                        icon: chevron-right\r\n                        icon_at: end\r\n                        keyboard: ]','commands:\r\n  api.command:\r\n    deny/name@bool: {{inputs.name != \'cerb.commands.worklist.search\'}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (75,'cerb.interaction.echo','A default interaction that returns the same inputs as output.','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  array/outputs:\r\n    required@bool: yes\r\n\r\n# Simply return the inputs as outputs\r\nstart:\r\n  return@key: inputs:outputs','commands:\r\n  ');
INSERT INTO `automation` VALUES (76,'cerb.ticket.assign','An interaction for quickly assigning tickets','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    record_type: ticket\r\n    required@bool: yes\r\n  record/worker:\r\n    record_type: worker\r\n    required@bool: no\r\n  text/unassign:\r\n    type: bool\r\n\r\nstart:\r\n  decision/action:\r\n    outcome/unassign:\r\n      if@bool: {{inputs.unassign}}\r\n      then:\r\n        set:\r\n          prompt_worker_id: 0\r\n    outcome/else:\r\n        then:\r\n          decision/hasWorker:\r\n            outcome/yes:\r\n              if: {{inputs.worker.id}}\r\n              then:\r\n                set:\r\n                  prompt_worker_id: {{inputs.worker.id}}\r\n            outcome/no:\r\n              then:\r\n                await/owner:\r\n                  form:\r\n                    title: Assign\r\n                    elements:\r\n                      sheet/prompt_worker_id:\r\n                        label: To which worker:\r\n                        required@bool: yes\r\n                        limit: 25\r\n                        data:\r\n                          automation:\r\n                            uri: cerb:automation:cerb.data.records\r\n                            inputs:\r\n                              record_type: worker\r\n                              query: group:(id:{{inputs.ticket.group_id}}) isDisabled:n sort:firstName\r\n                        schema:\r\n                          layout:\r\n                            style: grid\r\n                            filtering@bool: yes\r\n                            headings@bool: no\r\n                            paging@bool: yes\r\n                          columns:\r\n                            selection/id:\r\n                              params:\r\n                                mode: single\r\n                            icon/image:\r\n                              params:\r\n                                record_uri@raw: cerb:worker:{{id}}\r\n                                text_size@raw: 250%\r\n                            text/_label:\r\n                              params:\r\n                                bold@bool: yes\r\n                                underline@bool: no\r\n                                text_size@raw: 125%\r\n                            text/title:\r\n                      submit:\r\n                        continue@bool: no\r\n                        reset@bool: no\r\n\r\n  record.update/ticket:\r\n    output: updated_ticket\r\n    inputs:\r\n      # See: https://cerb.ai/docs/records/types/ticket/#records-api\r\n      record_type: ticket\r\n      record_id: {{inputs.ticket.id}}\r\n      fields:\r\n        owner_id: {{prompt_worker_id}}\r\n  ','commands:\r\n  record.update:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'ticket\')}}\r\n    deny/fields@bool: {{inputs.fields|keys is not same as [\'owner_id\']}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (77,'cerb.ticket.status','An interaction for quickly changing ticket status','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    required@bool: yes\r\n    record_type: ticket\r\n  text/status:\r\n    type: freeform\r\n    required@bool: yes\r\n  text/confirm:\r\n    type: bool\r\n    default: no\r\n\r\nstart:\r\n  decision/validate:\r\n    outcome/noPerm:\r\n      if@bool: {{not cerb_record_writeable(\'ticket\',inputs.ticket.id,\'worker\',worker_id)}}\r\n      then:\r\n        return:\r\n    outcome/invalidStatus:\r\n      if@bool: {{inputs.status not in [\'open\',\'closed\',\'waiting\',\'deleted\']}}\r\n      then:\r\n        log.error: `inputs.status` ({{inputs.status}}) must be one of: open, closed, waiting, deleted\r\n        return:\r\n\r\n  # Do we need a confirmation?\r\n  outcome/confirm:\r\n    if@bool: {{inputs.confirm}}\r\n    then:\r\n      await:\r\n        form:\r\n          title: Confirm\r\n          elements:\r\n            say/confirm:\r\n              content@text:\r\n                ### Are you sure you want to change this ticket status from **{{inputs.ticket.status}}** to **{{inputs.status}}**?\r\n            submit/prompt_confirm:\r\n              buttons:\r\n                continue/yes:\r\n                  label: Continue\r\n                  icon: circle-ok\r\n                  icon_at: start\r\n                  value: yes\r\n                continue/no:\r\n                  label: Cancel\r\n                  icon: circle-remove\r\n                  icon_at: start\r\n                  value:  no\r\n                  style: secondary\r\n      outcome/cancel:\r\n        if@bool: {{prompt_confirm != \'yes\'}}\r\n        then:\r\n          return:\r\n  \r\n  record.update/ticket:\r\n    output: updated_ticket\r\n    inputs:\r\n      record_type: ticket\r\n      record_id: {{inputs.ticket.id}}\r\n      fields:\r\n        status: {{inputs.status}}','commands:\r\n  record.update:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'ticket\')}}\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (78,'cerb.worklist.buttons.explore','Launch a custom explore mode that tracks real-time changes to a given worklist.','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  text/open_new_tab:\r\n    type: bool\r\n    default: 0\r\n\r\nstart:\r\n  api.command:\r\n    output: results\r\n    inputs:\r\n      name: cerb.commands.worklist.explorer.create\r\n      params:\r\n        title: Explore Mode\r\n        worker_id: {{worker_id}}\r\n        interaction: cerb:automation:cerb.explore.worklist\r\n        interaction_inputs:\r\n          worklist_id: {{caller_params.worklist_id}}\r\n          \r\n  outcome/failed:\r\n    if@bool: {{results.hash is empty}}\r\n    then:\r\n      return:\r\n  \r\n  decision/open:\r\n    outcome/newTab:\r\n      if@bool: {{inputs.open_new_tab}}\r\n      then:\r\n        return:\r\n          open_link: {{cerb_url(\'c=explore&id=\' ~ results.hash)}}\r\n    outcome/sameTab:\r\n      then:\r\n        return:\r\n          open_url: {{cerb_url(\'c=explore&id=\' ~ results.hash)}}','commands:\r\n  api.command:\r\n    allow@bool: yes');
INSERT INTO `automation` VALUES (79,'ai.cerb.chooser.toolbar','','cerb.trigger.interaction.internal',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'#\r\nstart:\r\n  await:\r\n    form:\r\n      elements:\r\n        sheet/prompt_toolbar_id:\r\n          label: Toolbar:\r\n          required@bool: yes\r\n          data:\r\n            automation:\r\n              uri: cerb:automation:cerb.data.records\r\n              inputs:\r\n                record_type: toolbar\r\n                query: sort:name\r\n          limit: 50\r\n          schema:\r\n            layout:\r\n              headings@bool: no\r\n              paging@bool: no\r\n              filtering@bool: yes\r\n              title_column: name\r\n              style: columns\r\n            columns:\r\n              selection/id:\r\n                params:\r\n                  mode: single\r\n                  label_key: name\r\n              text/description:\r\n                #params:\r\n                #  value_template@raw: {{params.description}}\r\n        submit:\r\n          continue@bool: no\r\n          reset@bool: no\r\n  \r\n  set:\r\n    prompt_toolbar__context: toolbar\r\n    prompt_toolbar_id@key: prompt_toolbar_id\r\n  \r\n  return:\r\n    toolbar:\r\n      id: {{prompt_toolbar_id}}\r\n      name: {{prompt_toolbar_name}}','commands:\r\n  # [TODO] Specify a command policy here (use Ctrl+Space for autocompletion)\r\n  ');
INSERT INTO `automation` VALUES (80,'cerb.reply.isBannedDefunct','Prompt for confirmation when replying to a banned or defunct recipient','cerb.trigger.mail.reply.validate',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/message:\r\n    required@bool: yes\r\n    record_type: message\r\n\r\nstart:\r\n  outcome/isBanned:\r\n    if@bool: {{inputs.message.sender_is_banned or inputs.message.sender_is_defunct}}\r\n    then:\r\n      await:\r\n        form:\r\n          title: Warning\r\n          elements:\r\n            say/respond:\r\n              content@text:\r\n                **{{inputs.message.sender__label}}** is {{inputs.message.sender_is_banned ? \'banned\' : \'defunct\'}}\r\n                ========\r\n                Are you sure you want to send this message?\r\n            submit/prompt_menu:\r\n              buttons:\r\n                continue/no:\r\n                  label: No\r\n                  value: no\r\n                continue/yes:\r\n                  label: Yes\r\n                  value: yes\r\n                  style: secondary\r\n      \r\n      outcome/reject:\r\n        if@bool: {{\'no\' == prompt_menu}}\r\n        then:\r\n          return:\r\n            reject@bool: yes','commands:\r\n  ');
INSERT INTO `automation` VALUES (81,'cerb.ticket.spam','An interaction for quickly reporting tickets as spam','cerb.trigger.interaction.worker',NULL,UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),'inputs:\r\n  record/ticket:\r\n    required@bool: yes\r\n    record_type: ticket\r\n  text/status:\r\n    type: freeform\r\n    required@bool: yes\r\n  text/confirm:\r\n    type: bool\r\n    default: no\r\n\r\nstart:\r\n  decision/validate:\r\n    outcome/noPerm:\r\n      if@bool:\r\n        {{\r\n          not cerb_record_writeable(\'ticket\',inputs.ticket.id,\'worker\',worker_id) \r\n          or not cerb_has_priv(\'core.ticket.actions.spam\',\'worker\',worker_id)\r\n        }}\r\n      then:\r\n        return:\r\n    outcome/invalidStatus:\r\n      if@bool: {{inputs.status not in [\'open\',\'closed\',\'waiting\',\'deleted\']}}\r\n      then:\r\n        log.error: `inputs.status` ({{inputs.status}}) must be one of: open, closed, waiting, deleted\r\n        return:\r\n\r\n  # Do we need a confirmation?\r\n  outcome/confirm:\r\n    if@bool: {{inputs.confirm}}\r\n    then:\r\n      await:\r\n        form:\r\n          title: Confirm\r\n          elements:\r\n            say/confirm:\r\n              content@text:\r\n                ### Are you sure you want to report this ticket as spam?\r\n            submit/prompt_confirm:\r\n              buttons:\r\n                continue/yes:\r\n                  label: Continue\r\n                  icon: circle-ok\r\n                  icon_at: start\r\n                  value: yes\r\n                continue/no:\r\n                  label: Cancel\r\n                  icon: circle-remove\r\n                  icon_at: start\r\n                  value:  no\r\n                  style: secondary\r\n      outcome/cancel:\r\n        if@bool: {{prompt_confirm != \'yes\'}}\r\n        then:\r\n          return:\r\n  \r\n  api.command:\r\n    inputs:\r\n      name: cerb.commands.email.spam.train\r\n      params:\r\n        ticket_id@int: {{inputs.ticket.id}}\r\n  \r\n  outcome/status:\r\n    if@bool: {{inputs.status}}\r\n    then:\r\n      record.update/ticket:\r\n        output: updated_ticket\r\n        inputs:\r\n          record_type: ticket\r\n          record_id: {{inputs.ticket.id}}\r\n          fields:\r\n            status: {{inputs.status}}','commands:\r\n  api.command:\r\n    deny/name@bool: {{inputs.name not in [\'cerb.commands.email.spam.train\']}}\r\n    allow@bool: yes\r\n  record.update:\r\n    deny/type@bool: {{inputs.record_type is not record type (\'ticket\')}}\r\n    allow@bool: yes');
