INSERT INTO `card_widget` VALUES (76,'Statistics','cerb.contexts.metric','cerb.card.widget.chart.timeseries','{\"data_query\":\"type:metrics.timeseries\\r\\nrange:\\\"-24 hours to now\\\"\\r\\nperiod:hour\\r\\nseries.samples:(\\r\\n  label:Samples\\r\\n  metric:{{record_name}}\\r\\n  function:count\\r\\n)\\r\\nseries.sum:(\\r\\n  label:Sum\\r\\n  metric:{{record_name}}\\r\\n  function:sum\\r\\n)\\r\\nseries.avg:(\\r\\n  label:Average\\r\\n  metric:{{record_name}}\\r\\n  function:avg\\r\\n)\\r\\nseries.min:(\\r\\n  label:Min\\r\\n  metric:{{record_name}}\\r\\n  function:min\\r\\n)\\r\\nseries.avg:(\\r\\n  label:Max\\r\\n  metric:{{record_name}}\\r\\n  function:max\\r\\n)\\r\\nformat:timeseries\",\"chart_as\":\"line\",\"xaxis_label\":\"\",\"yaxis_label\":\"\",\"yaxis_format\":\"number\",\"height\":\"\",\"options\":{\"show_legend\":\"1\",\"show_points\":\"1\"}}',UNIX_TIMESTAMP(),UNIX_TIMESTAMP(),1,4,'content',NULL);
