INSERT INTO `cerb_plugin` VALUES ('cerberusweb.translators',0,'Translation Editor','A GUI for translating the Cerb interface into other languages.  This adds a \'Translations\' tab to Configuration.','Webgroup Media, LLC.',100500,'features/cerberusweb.translators','http://wiki.cerbweb.com/Features:Translation_Editor','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"},\"php_extensions\":{\"mbstring\":{\"name\":\"mbstring\"}}},\"dependencies\":[\"cerberusweb.core\"],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
