INSERT INTO `cerb_plugin` VALUES ('wgm.jira',0,'JIRA Integration (Legacy)','This plugin provides integration with Atlassian JIRA via their REST API.  It is intended to be a bridge used by other plugins to communicate with JIRA services.','Webgroup Media, LLC.',100500,'plugins/wgm.jira','http://www.cerbweb.com/book/latest/plugins/wgm.jira','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"},\"php_extensions\":{\"curl\":{\"name\":\"curl\"}}},\"dependencies\":[\"cerberusweb.core\"],\"patches\":[{\"version\":\"6.0.0\",\"revision\":\"5\",\"file\":\"patches\\/6.0.0.php\"},{\"version\":\"7.2.0\",\"revision\":\"10\",\"file\":\"patches\\/7.2.0.php\"},{\"version\":\"7.3.0\",\"revision\":\"11\",\"file\":\"patches\\/7.3.0.php\"},{\"version\":\"9.0.0\",\"revision\":\"14\",\"file\":\"patches\\/9.0.0.php\"},{\"version\":\"9.1.0\",\"revision\":\"15\",\"file\":\"patches\\/9.1.0.php\"}],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
INSERT INTO `cerb_plugin` VALUES ('wgm.ldap',0,'LDAP Integration','Authenticate worker and customer logins via LDAP.','Webgroup Media, LLC.',100500,'plugins/wgm.ldap','http://www.cerbweb.com/book/latest/plugins/wgm.ldap.html','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"},\"php_extensions\":{\"ldap\":{\"name\":\"ldap\"}}},\"dependencies\":[\"cerberusweb.core\"],\"patches\":[{\"version\":\"8.0.0\",\"revision\":\"1\",\"file\":\"patches\\/8.0.0.php\"}],\"templates\":[{\"plugin_id\":\"wgm.ldap\",\"set\":\"cerberusweb.support_center\",\"path\":\"support_center\\/login\\/ldap.tpl\"}],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
INSERT INTO `cerb_plugin` VALUES ('wgm.notifications.emailer',0,'Notifications Emailer','This plugin automatically sends an email to workers if they have received new notifications.  It sends digests, so if you receive 100 new assignments you\'ll only receive a single email about them.','Webgroup Media, LLC.',100500,'plugins/wgm.notifications.emailer','http://www.cerbweb.com/book/latest/plugins/wgm.notifications.emailer.html','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"}},\"dependencies\":[\"cerberusweb.core\"],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
INSERT INTO `cerb_plugin` VALUES ('wgm.storage.s3.gatekeeper',0,'S3 Gatekeeper Storage Engine','This plugin adds a new storage engine for Amazon S3 that doesn\'t store or expose your AWS account credentials. Instead, it authenticates with a remote gatekeeper script and retrieves a secure, pre-signed URL that is used to perform requests.','Webgroup Media, LLC.',100500,'plugins/wgm.storage.s3.gatekeeper','http://www.cerbweb.com/book/latest/plugins/wgm.storage.s3.gatekeeper.html','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"},\"php_extensions\":{\"curl\":{\"name\":\"curl\"}}},\"dependencies\":[\"cerberusweb.core\"],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
INSERT INTO `cerb_plugin` VALUES ('wgm.twitter',0,'Twitter Integration (Legacy)','This plugin provides integration with Twitter via their API. This plugin is intended to be a bridge used by other plugins to communicate with Twitter services. The plugin introduces record types for Twitter Accounts and Messages.  It supports multiple accounts;  @mentions are automatically synchronized and messages can be replied to from within Cerb.  In addition, it adds a new bot action with the ability to post status updates to Twitter.','Webgroup Media, LLC.',100500,'plugins/wgm.twitter','http://www.cerbweb.com/book/latest/plugins/wgm.twitter.html','{\"requires\":{\"app_version\":{\"min\":\"10.5\",\"max\":\"10.5.99\"}},\"dependencies\":[\"cerberusweb.core\"],\"patches\":[{\"version\":\"6.0.0\",\"revision\":\"3\",\"file\":\"patches\\/6.0.0.php\"},{\"version\":\"7.3.0\",\"revision\":\"4\",\"file\":\"patches\\/7.3.0.php\"},{\"version\":\"8.2.0\",\"revision\":\"6\",\"file\":\"patches\\/8.2.0.php\"},{\"version\":\"9.0.0\",\"revision\":\"7\",\"file\":\"patches\\/9.0.0.php\"}],\"plugin_image\":\"plugin.png\",\"activity_points\":[],\"permissions\":[]}');
