INSERT INTO `package_library` VALUES (1,'cerb_bot_behavior_action__execute_http_request','Execute HTTP request','Make an HTTP request to an external API and process the response','','behavior_action',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Node: Execute HTTP Request\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Execute HTTP request\",\n      \"uri\": \"cerb_bot_behavior_action__execute_http_request\",\n      \"description\": \"Make an HTTP request to an external API and process the response\",\n      \"point\": \"behavior_action\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_http_request\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Execute HTTP request\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"core.va.action.http_request\",\n            \"http_verb\": \"get\",\n            \"http_url\": \"https://example.com/path/to/resource\",\n            \"http_headers\": \"\",\n            \"http_body\": \"\",\n            \"auth\": \"\",\n            \"auth_placeholder\": \"\",\n            \"run_in_simulator\": \"1\",\n            \"response_placeholder\": \"_http_response\"\n          },\n          {\n            \"action\": \"_set_custom_var\",\n            \"value\": \"{{_http_response.body}}\",\n            \"format\": \"json\",\n            \"is_simulator_only\": \"0\",\n            \"var\": \"http_response_body\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (2,'cerb_bot_behavior_action__exit','Exit','Exit the behavior','','behavior_action',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Node: Exit\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Exit\",\n      \"uri\": \"cerb_bot_behavior_action__exit\",\n      \"description\": \"Exit the behavior\",\n      \"point\": \"behavior_action\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_exit\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Exit\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"_exit\",\n            \"mode\": \"\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (3,'cerb_bot_behavior_action__records_search','Search records','Search any record type with a query','','behavior_action',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Action: Search Records\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Search records\",\n      \"uri\": \"cerb_bot_behavior_action__records_search\",\n      \"description\": \"Search any record type with a query\",\n      \"point\": \"behavior_action\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_search_records\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Search records\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"core.bot.action.record.search\",\n            \"context\": \"ticket\",\n            \"query\": \"status:o limit:25\",\n            \"expand\": \"custom_\",\n            \"object_placeholder\": \"_records\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (4,'cerb_bot_behavior_action__set_placeholder','Set placeholder','Set the value of a custom placeholder','','behavior_action',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Action: Set Placeholder\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Set placeholder\",\n      \"uri\": \"cerb_bot_behavior_action__set_placeholder\",\n      \"description\": \"Set the value of a custom placeholder\",\n      \"point\": \"behavior_action\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Placeholder Name:\",\n          \"key\": \"prompt_placeholder_name\",\n          \"params\": {\n            \"default\": \"placeholder_name\"\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_set_placeholder\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Set placeholder\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"_set_custom_var\",\n            \"value\": \"This is the placeholder value\",\n            \"format\": \"\",\n            \"is_simulator_only\": \"0\",\n            \"var\": \"{{{prompt_placeholder_name}}}\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (5,'cerb_bot_behavior_action_interaction_close_chat','Close chat window','Close the chat window','','behavior_action:event.message.chat.worker',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Action: Close Chat Window\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Close chat window\",\n      \"uri\": \"cerb_bot_behavior_action_interaction_close_chat\",\n      \"description\": \"Close the chat window\",\n      \"point\": \"behavior_action:event.message.chat.worker\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_close_chat\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Close chat window\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"window_close\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (6,'cerb_bot_behavior_action_interaction_prompt','Prompt for input','Prompt for user input','# Input Type:\r\n\r\n* **Buttons:** Select from a list of pre-defined responses\r\n* **Chooser:** Select one or more records with a helper popup or autocomplete text box\r\n* **Date:** Enter an absolute or relative date, or select a date from a calendar\r\n* **File Upload:** Upload a file\r\n* **Images:** Select from a list of pre-defined responses represented by images\r\n* **Text:** Enter single line of free-form text\r\n* **Wait:** Pause before a long-running action\r\n\r\nSee: [Prompting for user input](https://cerb.ai/guides/bots/prompts/)','behavior_action:event.message.chat.worker',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Action: Prompt For Input\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Prompt for input\",\n      \"uri\": \"cerb_bot_behavior_action_interaction_prompt\",\n      \"description\": \"Prompt for user input\",\n      \"instructions\": \"# Input Type:\\r\\n\\r\\n* **Buttons:** Select from a list of pre-defined responses\\r\\n* **Chooser:** Select one or more records with a helper popup or autocomplete text box\\r\\n* **Date:** Enter an absolute or relative date, or select a date from a calendar\\r\\n* **File Upload:** Upload a file\\r\\n* **Images:** Select from a list of pre-defined responses represented by images\\r\\n* **Text:** Enter single line of free-form text\\r\\n* **Wait:** Pause before a long-running action\\r\\n\\r\\nSee: [Prompting for user input](https://cerb.ai/guides/bots/prompts/)\",\n      \"point\": \"behavior_action:event.message.chat.worker\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Input type:\",\n          \"key\": \"prompt_input_type\",\n          \"params\": {\n            \"default\": \"text\",\n            \"options\": {\n              \"Buttons\": \"buttons\",\n              \"Chooser\": \"chooser\",\n              \"Date\": \"date\",\n              \"File Upload\": \"file\",\n              \"Images\": \"images\",\n              \"Text\": \"text\",\n              \"Wait\": \"wait\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_prompt_buttons\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'buttons\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt with buttons\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"Who is your favorite digital assistant?\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_buttons\",\n            \"options\": \"Alexa\\r\\nSiri\\r\\nCerb\",\n            \"color_from\": \"#4795f7\",\n            \"color_mid\": \"#4795f7\",\n            \"color_to\": \"#4795f7\",\n            \"style\": \"\",\n            \"var\": \"prompt_answer\",\n            \"var_format\": \"{{message}}\",\n            \"var_validate\": \"\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_text\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'text\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt for text\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"What is your name?\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_text\",\n            \"placeholder\": \"\",\n            \"default\": \"\",\n            \"mode\": \"\",\n            \"var\": \"prompt_answer\",\n            \"var_format\": \"{{message}}\",\n            \"var_validate\": \"{% if prompt_answer is empty %}\\r\\nYou must type something!\\r\\n{% endif %}\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_date\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'date\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt for date\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"When?\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_date\",\n            \"placeholder\": \"(enter any future date; e.g. \\\"tomorrow 8am\\\")\",\n            \"default\": \"\",\n            \"mode\": \"\",\n            \"var\": \"prompt_answer\",\n            \"var_format\": \"{{message|date(\'U\')}}\",\n            \"var_validate\": \"{% if 0 == prompt_answer %}\\r\\nPlease enter a valid date. For instance, \\\"Friday noon\\\".\\r\\n{% elseif prompt_answer < \'now\'|date(\'U\') %}\\r\\nPlease enter a date in the future\\r\\n{% endif %}\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_chooser\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'chooser\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt with chooser\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"Pick someone:\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_chooser\",\n            \"context\": \"cerberusweb.contexts.worker\",\n            \"query\": \"isDisabled:n\",\n            \"selection\": \"single\",\n            \"autocomplete\": \"0\",\n            \"var\": \"prompt_answer\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_file\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'file\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt for file upload\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"Please upload an image file smaller than 250KB.\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_file\",\n            \"var\": \"prompt_file_id\",\n            \"var_format\": \"{{message|round}}\",\n            \"var_validate\": \"{% if prompt_file_size > 250000 %}\\r\\nThe file must be smaller than 250KB.\\r\\n{% elseif not (prompt_file_mime_type starts with \'image/\') %}\\r\\nPlease upload an image: PNG, JPEG, or GIF.\\r\\n{% endif %}\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_wait\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'wait\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Wait\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"One moment...\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_wait\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_prompt_images\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"_exclude\": \"{{% if prompt_input_type != \'images\' %}}true{{% endif %}}\",\n      \"type\": \"action\",\n      \"title\": \"Prompt with images\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"How are you feeling?\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          },\n          {\n            \"action\": \"prompt_images\",\n            \"images\": [\n              \"data:image/png;base64,\",\n              \"data:image/png;base64,\",\n              \"data:image/png;base64,\"\n            ],\n            \"labels\": [\n              \"happy\",\n              \"neutral\",\n              \"unhappy\"\n            ],\n            \"var\": \"prompt_mood\",\n            \"var_format\": \"{{message}}\",\n            \"var_validate\": \"\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (7,'cerb_bot_behavior_action_interaction_respond','Respond with text','Respond to the worker with a text-based chat message','','behavior_action:event.message.chat.worker',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Action: Respond With Text\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Respond with text\",\n      \"uri\": \"cerb_bot_behavior_action_interaction_respond\",\n      \"description\": \"Respond to the worker with a text-based chat message\",\n      \"point\": \"behavior_action:event.message.chat.worker\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_prompt\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Respond\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"send_message\",\n            \"message\": \"Hello, {{worker_first_name}}!\",\n            \"format\": \"\",\n            \"delay_ms\": \"1000\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (8,'cerb_bot_behavior_action_webhook_set_http_body','Respond with HTTP body','Set an arbitrary HTTP response body','','behavior_action:event.webhook.received',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Action: Set HTTP Body\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Respond with HTTP body\",\n      \"uri\": \"cerb_bot_behavior_action_webhook_set_http_body\",\n      \"description\": \"Set an arbitrary HTTP response body\",\n      \"point\": \"behavior_action:event.webhook.received\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_jquery_script\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Set HTTP response body\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n           \"action\": \"set_http_body\",\n           \"value\": \"{% set json = {\\r\\n\\t\\\"status\\\": true,\\r\\n} %}\\r\\n{{json|json_encode|json_pretty}}\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (9,'cerb_bot_behavior_action_webhook_set_http_header','Respond with HTTP header','Set an arbitrary HTTP response header','','behavior_action:event.webhook.received',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Action: Set HTTP header\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Respond with HTTP header\",\n      \"uri\": \"cerb_bot_behavior_action_webhook_set_http_header\",\n      \"description\": \"Set an arbitrary HTTP response header\",\n      \"point\": \"behavior_action:event.webhook.received\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_jquery_script\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Set HTTP response headers\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n           \"action\": \"set_http_header\",\n           \"name\": \"Content-Type\",\n           \"value\": \"application/json\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (10,'cerb_bot_behavior_action_webhook_set_http_status','Respond with HTTP status','Set an arbitrary HTTP response status code','','behavior_action:event.webhook.received',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Action: Set HTTP Status\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Respond with HTTP status\",\n      \"uri\": \"cerb_bot_behavior_action_webhook_set_http_status\",\n      \"description\": \"Set an arbitrary HTTP response status code\",\n      \"point\": \"behavior_action:event.webhook.received\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_jquery_script\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Set HTTP response status code\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n           \"action\": \"set_http_status\",\n           \"value\": \"200\"\n          }\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (11,'cerb_bot_behavior_auto_reply','Global Auto-Reply','A behavior that automatically replies to new messages in all groups','','behavior',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior: Auto-Reply Template\",\n    \"revision\": 2,\n    \"requires\": {\n      \"cerb_version\": \"9.5.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Global Auto-Reply\",\n      \"uri\": \"cerb_bot_behavior_auto_reply\",\n      \"description\": \"A behavior that automatically replies to new messages in all groups\",\n      \"point\": \"behavior\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Bot\",\n          \"key\": \"bot_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.bot\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"behaviors\": [\n    {\n      \"uid\": \"behavior_autoreply\",\n      \"bot_id\": \"{{{bot_id}}}\",\n      \"title\": \"Automatically respond to new conversations\",\n      \"is_disabled\": false,\n      \"is_private\": false,\n      \"priority\": 50,\n      \"event\": {\n        \"key\": \"event.mail.received\",\n        \"label\": \"New message added to ticket\"\n      },\n      \"nodes\": [\n        {\n          \"type\": \"switch\",\n          \"title\": \"Is this a new conversation?\",\n          \"status\": \"live\",\n          \"nodes\": [\n            {\n              \"type\": \"outcome\",\n              \"title\": \"Yes\",\n              \"status\": \"live\",\n              \"params\": {\n                \"groups\": [\n                  {\n                    \"any\": 0,\n                    \"conditions\": [\n                      {\n                        \"condition\": \"is_first\",\n                        \"bool\": \"1\"\n                      },\n                      {\n                        \"condition\": \"is_outgoing\",\n                        \"bool\": \"0\"\n                      }\n                    ]\n                  }\n                ]\n              },\n              \"nodes\": [\n                {\n                  \"type\": \"switch\",\n                  \"title\": \"Does the message have auto-reply characteristics?\",\n                  \"status\": \"live\",\n                  \"nodes\": [\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it\'s from mailer-daemon or postmaster\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 1,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"sender_address\",\n                                \"oper\": \"like\",\n                                \"value\": \"mailer-daemon@*\"\n                              },\n                              {\n                                \"condition\": \"sender_address\",\n                                \"oper\": \"like\",\n                                \"value\": \"postmaster@*\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it has an Auto-Submitted header\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 0,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Auto-Submitted\",\n                                \"oper\": \"!is\",\n                                \"value\": \"\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Auto-Submitted\",\n                                \"oper\": \"!is\",\n                                \"value\": \"no\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it has Preference/Precedence headers\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 1,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Preference\",\n                                \"oper\": \"is\",\n                                \"value\": \"auto_reply\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Precedence\",\n                                \"oper\": \"is\",\n                                \"value\": \"bulk\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it has X-Precedence, X-Autorespond, X-Autogenerated, or X-AutoReply-From headers\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 1,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"X-Autogenerated\",\n                                \"oper\": \"!is\",\n                                \"value\": \"\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"X-AutoReply\",\n                                \"oper\": \"!is\",\n                                \"value\": \"\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"X-AutoReply-From\",\n                                \"oper\": \"!is\",\n                                \"value\": \"\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"X-Autorespond\",\n                                \"oper\": \"!is\",\n                                \"value\": \"\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"X-Precedence\",\n                                \"oper\": \"is\",\n                                \"value\": \"auto_reply\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it has an Out of Office subject\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 1,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Subject\",\n                                \"oper\": \"contains\",\n                                \"value\": \"Out of Office\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Subject\",\n                                \"oper\": \"contains\",\n                                \"value\": \"is out of the office\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"Yes, it has an Auto Response subject\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 1,\n                            \"conditions\": [\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Subject\",\n                                \"oper\": \"contains\",\n                                \"value\": \"Auto Response\"\n                              },\n                              {\n                                \"condition\": \"headers\",\n                                \"header\": \"Subject\",\n                                \"oper\": \"contains\",\n                                \"value\": \"AutoReply\"\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    },\n                    {\n                      \"type\": \"outcome\",\n                      \"title\": \"No\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"groups\": [\n                          {\n                            \"any\": 0,\n                            \"conditions\": [\n\n                            ]\n                          }\n                        ]\n                      },\n                      \"nodes\": [\n                        {\n                          \"type\": \"action\",\n                          \"title\": \"Send auto-reply message\",\n                          \"status\": \"live\",\n                          \"params\": {\n                            \"actions\": [\n                              {\n                                \"action\": \"send_email\",\n                                \"from_address_id\": \"0\",\n                                \"send_as\": \"\",\n                                \"to\": \"{{sender_address}}\",\n                                \"cc\": \"\",\n                                \"bcc\": \"\",\n                                \"subject\": \"Received: {{ticket_subject}} [#{{ticket_mask}}]\",\n                                \"headers\": \"Auto-Submitted: auto-replied\",\n                                \"format\": \"\",\n                                \"content\": \"***** THIS IS AN AUTOMATED MESSAGE *****\\r\\n\\r\\n{% if sender_contact_first_name %}\\r\\nHi {{sender_contact_first_name}},\\r\\n\\r\\n{% endif %}\\r\\nThis is a confirmation that we have received your message.\\r\\n\\r\\nReference #: {{ticket_mask}}\\r\\nSubject: {{ticket_subject}}\\r\\n\\r\\nWe\'ll respond as soon as possible.\\r\\n\\r\\nThanks for contacting us!\\r\\n\\r\\n-- \\r\\nSupport\",\n                                \"run_in_simulator\": \"0\"\n                              }\n                            ]\n                          }\n                        }\n                      ]\n                    }\n                  ]\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (12,'cerb_bot_behavior_loop__break','Loop with break','A loop that stops early if a certain condition is true','','behavior_loop',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Loop: Break\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Loop with break\",\n      \"uri\": \"cerb_bot_behavior_loop__break\",\n      \"description\": \"A loop that stops early if a certain condition is true\",\n      \"point\": \"behavior_loop\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_loop_break\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"loop\",\n      \"title\": \"Loop:\",\n      \"status\": \"live\",\n      \"params\": {\n        \"foreach_json\": \"[1,2,3,4,5]\",\n        \"as_placeholder\": \"_item\"\n      },\n      \"nodes\": [\n        {\n          \"type\": \"action\",\n          \"title\": \"Do something\",\n          \"status\": \"live\",\n          \"params\": {\n            \"actions\": [\n\n            ]\n          }\n        },\n        {\n          \"type\": \"switch\",\n          \"title\": \"Break?\",\n          \"status\": \"live\",\n          \"nodes\": [\n            {\n              \"type\": \"outcome\",\n              \"title\": \"Yes\",\n              \"status\": \"live\",\n              \"params\": {\n                \"groups\": [\n                  {\n                    \"any\": 0,\n                    \"conditions\": [\n                      {\n                        \"condition\": \"_custom_script\",\n                        \"tpl\": \"{# The loop will break when this condition is true. This example stops early on the third item. #}\\r\\n{{_item}}\",\n                        \"oper\": \"is\",\n                        \"value\": \"3\"\n                      }\n                    ]\n                  }\n                ]\n              },\n              \"nodes\": [\n                {\n                  \"type\": \"action\",\n                  \"title\": \"Break\",\n                  \"status\": \"live\",\n                  \"params\": {\n                    \"actions\": [\n                      {\n                        \"action\": \"_set_custom_var\",\n                        \"value\": \"{# We clear the loop\'s remaining stack to exit #}\\r\\n[]\",\n                        \"format\": \"json\",\n                        \"is_simulator_only\": \"0\",\n                        \"var\": \"_item__stack\"\n                      }\n                    ]\n                  }\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (13,'cerb_bot_behavior_loop__records','Loop record search results','Loop through results from a record search query','','behavior_loop',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Loop: Records\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Loop record search results\",\n      \"uri\": \"cerb_bot_behavior_loop__records\",\n      \"description\": \"Loop through results from a record search query\",\n      \"point\": \"behavior_loop\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_search_records\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"action\",\n      \"title\": \"Search records\",\n      \"status\": \"live\",\n      \"params\": {\n        \"actions\": [\n          {\n            \"action\": \"core.bot.action.record.search\",\n            \"context\": \"ticket\",\n            \"query\": \"status:o sort:-updated limit:25\",\n            \"expand\": \"custom_, owner_, group_, bucket_, initial_message_sender_, latest_message_sender_\",\n            \"object_placeholder\": \"_records\"\n          }\n        ]\n      }\n    },\n    {\n      \"uid\": \"node_loop_records\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"loop\",\n      \"title\": \"Loop record search results\",\n      \"status\": \"live\",\n      \"params\": {\n        \"foreach_json\": \"{{_records|keys|json_encode}}\",\n        \"as_placeholder\": \"_record_id\"\n      },\n      \"nodes\": [\n        {\n          \"type\": \"action\",\n          \"title\": \"Do something\",\n          \"status\": \"live\",\n          \"params\": {\n            \"actions\": [\n              {\n                \"action\": \"_set_custom_var\",\n                \"value\": \"{# See: https://cerb.ai/docs/records/types/ #}\\r\\n{% set record = _records[_record_id] %}\\r\\nSubject: {{record._label}}\\r\\nGroup: {{record.group__label}}\\r\\nBucket: {{record.bucket__label}}\\r\\nStatus: {{record.status}}\\r\\nOwner: {{record.owner__label}}\\r\\nFirst Wrote: {{record.initial_message_sender__label}}\\r\\nLast Wrote: {{record.latest_message_sender__label}}\\r\\nCreated: {{record.created|date_pretty}}\\r\\n\",\n                \"format\": \"\",\n                \"is_simulator_only\": \"0\",\n                \"var\": \"_placeholder\"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (14,'cerb_bot_behavior_switch__cases','Multiple outcomes','A decision with multiple outcomes','','behavior_switch',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Decision: Cases\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Multiple outcomes\",\n      \"uri\": \"cerb_bot_behavior_switch__cases\",\n      \"description\": \"A decision with multiple outcomes\",\n      \"point\": \"behavior_switch\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_cases\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"switch\",\n      \"title\": \"Outcome:\",\n      \"status\": \"live\",\n      \"nodes\": [\n        {\n          \"type\": \"outcome\",\n          \"title\": \"One\",\n          \"status\": \"live\",\n          \"params\": {\n            \"groups\": [\n              {\n                \"any\": 0,\n                \"conditions\": [\n                  {\n                    \"condition\": \"_custom_script\",\n                    \"tpl\": \"{# The first outcome conditions go here #}\\r\\n{% if true == true %}true{% endif %}\",\n                    \"oper\": \"is\",\n                    \"value\": \"true\"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          \"type\": \"outcome\",\n          \"title\": \"Two\",\n          \"status\": \"live\",\n          \"params\": {\n            \"groups\": [\n              {\n                \"any\": 0,\n                \"conditions\": [\n                  {\n                    \"condition\": \"_custom_script\",\n                    \"tpl\": \"{# The second outcome conditions go here #}\\r\\n{% if true == true %}true{% endif %}\",\n                    \"oper\": \"is\",\n                    \"value\": \"true\"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          \"type\": \"outcome\",\n          \"title\": \"(Default)\",\n          \"status\": \"live\",\n          \"params\": {\n            \"groups\": [\n              {\n                \"any\": 0,\n                \"conditions\": []\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (15,'cerb_bot_behavior_switch__yes_no','Yes/No','A binary decision with \'yes\' and \'no\' outcomes','','behavior_switch',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Bot Behavior Decision: Yes/No\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Yes/No\",\n      \"uri\": \"cerb_bot_behavior_switch__yes_no\",\n      \"description\": \"A binary decision with \'yes\' and \'no\' outcomes\",\n      \"point\": \"behavior_switch\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Behavior\",\n          \"key\": \"behavior_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.behavior\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Parent ID\",\n          \"key\": \"parent_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"behavior_nodes\": [\n    {\n      \"uid\": \"node_yes_no\",\n      \"behavior_id\": \"{{{behavior_id}}}\",\n      \"parent_id\": \"{{{parent_id}}}\",\n      \"type\": \"switch\",\n      \"title\": \"Yes?\",\n      \"status\": \"live\",\n      \"nodes\": [\n        {\n          \"type\": \"outcome\",\n          \"title\": \"Yes\",\n          \"status\": \"live\",\n          \"params\": {\n            \"groups\": [\n              {\n                \"any\": 0,\n                \"conditions\": [\n                  {\n                    \"condition\": \"_custom_script\",\n                    \"tpl\": \"{# Your conditions go here #}\\r\\n{% if true == true %}true{% endif %}\",\n                    \"oper\": \"is\",\n                    \"value\": \"true\"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          \"type\": \"outcome\",\n          \"title\": \"No\",\n          \"status\": \"live\",\n          \"params\": {\n            \"groups\": [\n              {\n                \"any\": 0,\n                \"conditions\": []\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (16,'cerb_bot_twilio','Twilio Bot','A bot demonstrating integration between Cerb and Twilio','# Instructions\r\n\r\n* See [**Twilio Bot**](https://cerb.ai/packages/twilio-bot/)\r\n','bot',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"library\": {\n      \"name\": \"Twilio Bot\",\n      \"uri\": \"cerb_bot_twilio\",\n      \"description\": \"A bot demonstrating integration between Cerb and Twilio\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* See [**Twilio Bot**](https://cerb.ai/packages/twilio-bot/)\\r\\n\",\n      \"point\": \"bot\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n      {\n        \"type\": \"text\",\n        \"label\": \"Owner context\",\n        \"key\": \"prompt_owner_context\",\n        \"hidden\": true,\n        \"params\": {}\n      },\n      {\n        \"type\": \"text\",\n        \"label\": \"Owner context ID\",\n        \"key\": \"prompt_owner_context_id\",\n        \"hidden\": true,\n        \"params\": {}\n      },\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Twilio account:\",\n          \"key\": \"twilio_account_id\",\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.connected_account\",\n            \"single\": true,\n            \"query\": \"name:twilio\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Account SID:\",\n          \"key\": \"account_sid\",\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Default responder phone number:\",\n          \"key\": \"default_from\",\n          \"params\": {\n          }\n        }\n      ],\n      \"placeholders\": [\n        {\n          \"type\": \"random\",\n          \"key\": \"webhook_guid\",\n          \"params\": {\n            \"length\": 40\n          }\n        }\n      ]\n    }\n  },\n  \"bots\": [\n    {\n      \"uid\": \"bot_twilio\",\n      \"name\": \"Twilio Bot\",\n      \"owner\": {\n        \"context\": \"{{{prompt_owner_context}}}\",\n        \"id\": \"{{{prompt_owner_context_id}}}\"\n      },\n      \"is_disabled\": false,\n      \"params\": {\n        \"config\": {\n          \"account_sid\": \"{{{account_sid}}}\",\n          \"default_from\": \"{{{default_from}}}\"\n        },\n        \"events\": {\n          \"mode\": \"all\",\n          \"items\": [\n\n          ]\n        },\n        \"actions\": {\n          \"mode\": \"all\",\n          \"items\": [\n\n          ]\n        }\n      },\n      \"image\": \"data:image/png;base64,\",\n      \"behaviors\": [\n        {\n          \"uid\": \"behavior_lookup_number\",\n          \"title\": \"Look up a number\",\n          \"is_disabled\": false,\n          \"is_private\": true,\n          \"priority\": 50,\n          \"event\": {\n            \"key\": \"event.macro.bot\",\n            \"label\": \"Custom behavior on bot\"\n          },\n          \"variables\": {\n            \"var_phone_number\": {\n              \"key\": \"var_phone_number\",\n              \"label\": \"Phone Number\",\n              \"type\": \"S\",\n              \"is_private\": \"0\",\n              \"params\": {\n                \"widget\": \"single\"\n              }\n            }\n          },\n          \"nodes\": [\n            {\n              \"type\": \"action\",\n              \"title\": \"Look up number via API\",\n              \"status\": \"live\",\n              \"params\": {\n                \"actions\": [\n                  {\n                    \"action\": \"core.va.action.http_request\",\n                    \"http_verb\": \"get\",\n                    \"http_url\": \"https://lookups.twilio.com/v1/PhoneNumbers/{{var_phone_number|url_encode}}?Type=carrier&Type=caller-name\",\n                    \"http_headers\": \"\",\n                    \"http_body\": \"\",\n                    \"auth\": \"connected_account\",\n                    \"auth_connected_account_id\": \"{{{twilio_account_id}}}\",\n                    \"options\": {\n                      \"raw_response_body\": \"1\"\n                    },\n                    \"run_in_simulator\": \"1\",\n                    \"response_placeholder\": \"_http_response\"\n                  },\n                  {\n                    \"action\": \"_set_custom_var\",\n                    \"value\": \"{{_http_response.body|json_pretty}}\",\n                    \"format\": \"json\",\n                    \"is_simulator_only\": \"0\",\n                    \"var\": \"response\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"uid\": \"behavior_webhook_received\",\n          \"title\": \"Respond to Twilio SMS webhook\",\n          \"is_disabled\": false,\n          \"is_private\": false,\n          \"priority\": 50,\n          \"event\": {\n            \"key\": \"event.webhook.received\",\n            \"label\": \"Webhook received\"\n          },\n          \"nodes\": [\n            {\n              \"type\": \"switch\",\n              \"title\": \"Command:\",\n              \"status\": \"live\",\n              \"nodes\": [\n                {\n                  \"type\": \"outcome\",\n                  \"title\": \"HELP\",\n                  \"status\": \"live\",\n                  \"params\": {\n                    \"groups\": [\n                      {\n                        \"any\": 0,\n                        \"conditions\": [\n                          {\n                            \"condition\": \"http_param\",\n                            \"name\": \"body\",\n                            \"oper\": \"is\",\n                            \"value\": \"help\"\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  \"nodes\": [\n                    {\n                      \"type\": \"action\",\n                      \"title\": \"Respond\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"actions\": [\n                          {\n                            \"action\": \"set_http_body\",\n                            \"value\": \"{% set msg = \\\"You can say:\\\\n* HELP\\\\n* LOGO\\\\n* LINK\\\\n\\\" %}\\r\\n<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\r\\n<Response>\\r\\n    <Message>{{msg|escape}}</Message>\\r\\n</Response>\"\n                          }\n                        ]\n                      }\n                    }\n                  ]\n                },\n                {\n                  \"type\": \"outcome\",\n                  \"title\": \"LOGO\",\n                  \"status\": \"live\",\n                  \"params\": {\n                    \"groups\": [\n                      {\n                        \"any\": 0,\n                        \"conditions\": [\n                          {\n                            \"condition\": \"http_param\",\n                            \"name\": \"body\",\n                            \"oper\": \"is\",\n                            \"value\": \"logo\"\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  \"nodes\": [\n                    {\n                      \"type\": \"action\",\n                      \"title\": \"Respond\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"actions\": [\n                          {\n                            \"action\": \"set_http_body\",\n                            \"value\": \"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\r\\n<Response>\\r\\n    <Message>\\r\\n    \\tHere\'s the Cerb logo:\\r\\n    </Message>\\r\\n    <Message>\\r\\n    \\t<Media>https://cerb.ai/assets/images/home/cerby.png</Media>\\r\\n    </Message>\\r\\n</Response>\"\n                          }\n                        ]\n                      }\n                    }\n                  ]\n                },\n                {\n                  \"type\": \"outcome\",\n                  \"title\": \"LINK\",\n                  \"status\": \"live\",\n                  \"params\": {\n                    \"groups\": [\n                      {\n                        \"any\": 0,\n                        \"conditions\": [\n                          {\n                            \"condition\": \"http_param\",\n                            \"name\": \"body\",\n                            \"oper\": \"is\",\n                            \"value\": \"link\"\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  \"nodes\": [\n                    {\n                      \"type\": \"action\",\n                      \"title\": \"Respond\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"actions\": [\n                          {\n                            \"action\": \"set_http_body\",\n                            \"value\": \"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\r\\n<Response>\\r\\n    <Message>\\r\\n    \\tVisit https://cerb.ai/ for more info.\\r\\n    </Message>\\r\\n</Response>\"\n                          }\n                        ]\n                      }\n                    }\n                  ]\n                },\n                {\n                  \"type\": \"outcome\",\n                  \"title\": \"(default)\",\n                  \"status\": \"live\",\n                  \"params\": {\n                    \"groups\": [\n                      {\n                        \"any\": 0,\n                        \"conditions\": [\n\n                        ]\n                      }\n                    ]\n                  },\n                  \"nodes\": [\n                    {\n                      \"type\": \"action\",\n                      \"title\": \"Respond\",\n                      \"status\": \"live\",\n                      \"params\": {\n                        \"actions\": [\n                          {\n                            \"action\": \"set_http_body\",\n                            \"value\": \"{% set msg = \\\"Hi \\\" ~ http_params.from ~ \\\"! You said: \\\" ~ http_params.body %}\\r\\n<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\r\\n<Response>\\r\\n    <Message>{{msg|escape}}</Message>\\r\\n</Response>\"\n                          }\n                        ]\n                      }\n                    }\n                  ]\n                }\n              ]\n            }\n          ]\n        },\n        {\n          \"uid\": \"behavior_send_sms\",\n          \"title\": \"Send SMS message\",\n          \"is_disabled\": false,\n          \"is_private\": true,\n          \"priority\": 50,\n          \"event\": {\n            \"key\": \"event.macro.bot\",\n            \"label\": \"Custom behavior on bot\"\n          },\n          \"variables\": {\n            \"var_to\": {\n              \"key\": \"var_to\",\n              \"label\": \"To\",\n              \"type\": \"S\",\n              \"is_private\": \"0\",\n              \"params\": {\n                \"widget\": \"single\"\n              }\n            },\n            \"var_body\": {\n              \"key\": \"var_body\",\n              \"label\": \"Body\",\n              \"type\": \"S\",\n              \"is_private\": \"0\",\n              \"params\": {\n                \"widget\": \"multiple\"\n              }\n            }\n          },\n          \"nodes\": [\n            {\n              \"type\": \"action\",\n              \"title\": \"Send message via API\",\n              \"status\": \"live\",\n              \"params\": {\n                \"actions\": [\n                  {\n                    \"action\": \"core.va.action.http_request\",\n                    \"http_verb\": \"post\",\n                    \"http_url\": \"https://api.twilio.com/2010-04-01/Accounts/{{behavior_bot_config.account_sid}}/Messages\",\n                    \"http_headers\": \"\",\n                    \"http_body\": \"{% set params = {\\r\\n\\t\\\"To\\\": var_to,\\r\\n\\t\\\"From\\\": behavior_bot_config.default_from,\\r\\n\\t\\\"Body\\\": var_body\\r\\n} %}\\r\\n{{params|url_encode}}\",\n                    \"auth\": \"connected_account\",\n                    \"auth_connected_account_id\": \"{{{twilio_account_id}}}\",\n                    \"options\": {\n                      \"raw_response_body\": \"1\"\n                    },\n                    \"run_in_simulator\": \"1\",\n                    \"response_placeholder\": \"_http_response\"\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    }\n  ],\n  \"records\": [\n    {\n      \"uid\": \"webhook_twilio_bot\",\n      \"_context\": \"webhook_listener\",\n      \"name\": \"Twilio SMS Received\",\n      \"guid\": \"{{{webhook_guid|lower}}}\",\n      \"extension_id\": \"cerb.webhooks.listener.engine.va\",\n      \"extension_params\": {\n        \"behavior_id\": \"{{{uid.behavior_webhook_received}}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (17,'cerb_calendar_us_holidays','U.S. Holidays','A calendar with recurring U.S. holidays','','calendar',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Calendar: U.S. Holidays\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"U.S. Holidays\",\n      \"uri\": \"cerb_calendar_us_holidays\",\n      \"description\": \"A calendar with recurring U.S. holidays\",\n      \"point\": \"calendar\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context:\",\n          \"key\": \"owner_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context ID:\",\n          \"key\": \"owner_context_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"calendar_usholidays\",\n      \"_context\": \"calendar\",\n      \"name\": \"U.S. Holidays\",\n      \"owner__context\": \"{{{owner_context}}}\",\n      \"owner_id\": \"{{{owner_context_id}}}\",\n      \"params\": {\n        \"manual_disabled\": \"0\",\n        \"sync_enabled\": \"0\",\n        \"start_on_mon\": \"1\",\n        \"hide_start_time\": \"1\",\n        \"color_available\": \"#C5DCFA\",\n        \"color_busy\": \"#C5DCFA\"\n      }\n    },\n    {\n      \"uid\": \"calendar_event_newyears\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"New Year\'s Day\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"Jan 1\"\n    },\n    {\n      \"uid\": \"calendar_event_independence\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"Independence Day\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"July 4\"\n    },\n    {\n      \"uid\": \"calendar_event_labor\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"Labor Day\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"first Monday of September\"\n    },\n    {\n      \"uid\": \"calendar_event_christmas\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"Christmas\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"Dec 25\"\n    },\n    {\n      \"uid\": \"calendar_event_thanksgiving\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"Thanksgiving\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"fourth Thursday of November\"\n    },\n    {\n      \"uid\": \"calendar_event_newyears_eve\",\n      \"_context\": \"calendar_recurring_event\",\n      \"calendar_id\": \"{{{uid.calendar_usholidays}}}\",\n      \"name\": \"New Year\'s Eve\",\n      \"is_available\": 0,\n      \"tz\": \"America/Los_Angeles\",\n      \"event_start\": \"00:00:00\",\n      \"event_end\": \"23:59:59\",\n      \"recur_start\": 0,\n      \"recur_end\": 0,\n      \"patterns\": \"Dec 31\"\n    }\n  ]\n}');
