INSERT INTO `package_library` VALUES (19,'cerb_connected_service_aws','Amazon Web Services','Integration with Amazon Web Services','# Instructions\r\n\r\n* See [**Cerb + Amazon Web Services**](https://cerb.ai/guides/integrations/aws/)\r\n* Enter the access key and secret key below','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: Amazon Web Services\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Amazon Web Services\",\n      \"uri\": \"cerb_connected_service_aws\",\n      \"description\": \"Integration with Amazon Web Services\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* See [**Cerb + Amazon Web Services**](https://cerb.ai/guides/integrations/aws/)\\r\\n* Enter the access key and secret key below\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Access Key\",\n          \"key\": \"prompt_access_key\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your Access Key)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Secret Key\",\n          \"key\": \"prompt_secret_key\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your Secret Key)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_aws\",\n      \"_context\": \"connected_service\",\n      \"name\": \"Amazon Web Services\",\n      \"extension_id\": \"cerb.service.provider.aws\",\n      \"params\": {}\n    },\n    {\n      \"uid\": \"account_aws\",\n      \"_context\": \"connected_account\",\n      \"name\": \"Amazon Web Services\",\n      \"service_id\": \"{{{uid.service_aws}}}\",\n      \"owner__context\": \"cerberusweb.contexts.app\",\n      \"owner_id\": \"0\",\n      \"params\": {\n        \"access_key\": \"{{{prompt_access_key}}}\",\n        \"secret_key\": \"{{{prompt_secret_key}}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (20,'cerb_connected_service_dropbox','Dropbox','Integration with Dropbox','# Instructions\r\n\r\n* See [**Cerb + Dropbox**](https://cerb.ai/guides/integrations/dropbox/)\r\n* Enter the App Key and App Secret below','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: Dropbox\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Dropbox\",\n      \"uri\": \"cerb_connected_service_dropbox\",\n      \"description\": \"Integration with Dropbox\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* See [**Cerb + Dropbox**](https://cerb.ai/guides/integrations/dropbox/)\\r\\n* Enter the App Key and App Secret below\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"App Key\",\n          \"key\": \"prompt_client_id\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your App Key)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"App Secret\",\n          \"key\": \"prompt_client_secret\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your App Secret)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_dropbox\",\n      \"_context\": \"connected_service\",\n      \"name\": \"Dropbox\",\n      \"extension_id\": \"cerb.service.provider.oauth2\",\n      \"params\": {\n        \"grant_type\": \"authorization_code\",\n        \"client_id\": \"{{{prompt_client_id}}}\",\n        \"client_secret\": \"{{{prompt_client_secret}}}\",\n        \"authorization_url\": \"https://www.dropbox.com/oauth2/authorize\",\n        \"access_token_url\": \"https://api.dropboxapi.com/oauth2/token\",\n        \"resource_owner_url\": \"\",\n        \"scope\": \"\",\n        \"approval_prompt\": \"\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (21,'cerb_connected_service_facebook','Facebook','Integration with Facebook','# Instructions\r\n\r\n* See [**Cerb + Facebook**](https://cerb.ai/guides/integrations/facebook/)\r\n* Enter the App ID and App Secret below','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: Facebook\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Facebook\",\n      \"uri\": \"cerb_connected_service_facebook\",\n      \"description\": \"Integration with Facebook\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* See [**Cerb + Facebook**](https://cerb.ai/guides/integrations/facebook/)\\r\\n* Enter the App ID and App Secret below\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"App ID\",\n          \"key\": \"prompt_client_id\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your App ID)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"App Secret\",\n          \"key\": \"prompt_client_secret\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your App Secret)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_facebook\",\n      \"_context\": \"connected_service\",\n      \"name\": \"Facebook\",\n      \"extension_id\": \"cerb.service.provider.oauth2\",\n      \"params\": {\n        \"grant_type\": \"authorization_code\",\n        \"client_id\": \"{{{prompt_client_id}}}\",\n        \"client_secret\": \"{{{prompt_client_secret}}}\",\n        \"authorization_url\": \"https://graph.facebook.com/oauth/authorize\",\n        \"access_token_url\": \"https://graph.facebook.com/oauth/access_token\",\n        \"resource_owner_url\": \"\",\n        \"scope\": \"public_profile,read_page_mailboxes,manage_pages,publish_pages\",\n        \"approval_prompt\": \"auto\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (22,'cerb_connected_service_freshbooks_classic','Freshbooks Classic','Integration with Freshbooks Classic','# Instructions\r\n\r\n* See [**Cerb + Freshbooks Classic**](https://cerb.ai/guides/integrations/freshbooks-classic/)\r\n* Enter the subdomain and client secret below','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: Freshbooks Classic\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Freshbooks Classic\",\n      \"uri\": \"cerb_connected_service_freshbooks_classic\",\n      \"description\": \"Integration with Freshbooks Classic\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* See [**Cerb + Freshbooks Classic**](https://cerb.ai/guides/integrations/freshbooks-classic/)\\r\\n* Enter the subdomain and client secret below\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Subdomain\",\n          \"key\": \"prompt_subdomain\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(e.g. SUBDOMAIN.freshbooks.com)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Client Secret\",\n          \"key\": \"prompt_client_secret\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your Client Secret)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_freshbooks_classic\",\n      \"_context\": \"connected_service\",\n      \"name\": \"Freshbooks Classic\",\n      \"extension_id\": \"cerb.service.provider.oauth1\",\n      \"params\": {\n        \"grant_type\": \"authorization_code\",\n        \"client_id\": \"{{{prompt_subdomain}}}\",\n        \"client_secret\": \"{{{prompt_client_secret}}}\",\n        \"request_token_url\": \"https://{{{prompt_subdomain}}}.freshbooks.com/oauth/oauth_request.php\",\n        \"authentication_url\": \"https://{{{prompt_subdomain}}}.freshbooks.com/oauth/oauth_authorize.php\",\n        \"access_token_url\": \"https://{{{prompt_subdomain}}}.freshbooks.com/oauth/oauth_access.php\",\n        \"signature_method\": \"PLAINTEXT\"\n      }\n    }\n  ]\n}');
