service_id\": \"{{{uid.service_twilio}}}\",\n      \"owner__context\": \"cerberusweb.contexts.app\",\n      \"owner_id\": \"0\",\n      \"params\": {\n        \"username\": \"{{{prompt_account_sid}}}\",\n        \"password\": \"{{{prompt_auth_token}}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (33,'cerb_profile_tab__log','Activity Log','A log of activity on this record','','profile_tab',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile Tab: Activity Log\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Activity Log\",\n      \"uri\": \"cerb_profile_tab__log\",\n      \"description\": \"A log of activity on this record\",\n      \"point\": \"profile_tab\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Profile Context\",\n          \"key\": \"profile_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n        \"uid\": \"profile_tab_log\",\n        \"_context\": \"profile_tab\",\n        \"name\": \"Log\",\n        \"context\": \"{{{profile_context}}}\",\n        \"extension_id\": \"cerb.profile.tab.dashboard\",\n        \"extension_params\": {\n        }\n    },\n    {\n        \"uid\": \"widget_worklist_log\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Activity Log\",\n        \"extension_id\": \"cerb.profile.tab.widget.worklist\",\n        \"profile_tab_id\": \"{{{uid.profile_tab_log}}}\",\n        \"pos\": 1,\n        \"width_units\": 1,\n        \"zone\": \"\",\n        \"extension_params\": {\n            \"context\": \"cerberusweb.contexts.activity_log\",\n            \"query_required\": \"target.{{{profile_context}}}:(\\r\\n\\tid:{{record_id}}\\r\\n)\",\n            \"query\": \"created:\\\"-30 days to now\\\" \\r\\nsort:-created \\r\\nsubtotal:activity\",\n            \"render_limit\": \"15\",\n            \"header_color\": \"#6a87db\",\n            \"columns\": [\n                \"c_created\"\n            ]\n        }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (34,'cerb_profile_tab_package_overview','Overview','The default overview for package records','','profile_tab:package',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile Tab: Package Overview\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Overview\",\n      \"uri\": \"cerb_profile_tab_package_overview\",\n      \"description\": \"The default overview for package records\",\n      \"point\": \"profile_tab:package\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"profile_tab_overview\",\n      \"_context\": \"profile_tab\",\n      \"name\": \"Overview\",\n      \"context\": \"package\",\n      \"extension_id\": \"cerb.profile.tab.dashboard\",\n      \"extension_params\": {\n        \"layout\": \"sidebar_left\"\n      }\n    },\n    {\n      \"uid\": \"profile_widget_package_fields\",\n      \"_context\": \"profile_widget\",\n      \"name\": \"Package\",\n      \"extension_id\": \"cerb.profile.tab.widget.fields\",\n      \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"sidebar\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.package.library\",\n        \"context_id\": \"{{record_id}}\",\n        \"properties\": [\n          [\n            \"name\",\n            \"uri\",\n            \"description\",\n            \"point\",\n            \"updated\"\n          ]\n        ],\n        \"links\": {\n          \"show\": \"1\"\n        },\n        \"search\": {\n          \"context\": [\n\n          ],\n          \"label_singular\": [\n\n          ],\n          \"label_plural\": [\n\n          ],\n          \"query\": [\n\n          ]\n        }\n      }\n    },\n    {\n      \"uid\": \"profile_widget_comments\",\n      \"_context\": \"cerberusweb.contexts.profile.widget\",\n      \"name\": \"Discussion\",\n      \"extension_id\": \"cerb.profile.tab.widget.comments\",\n      \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.package.library\",\n        \"context_id\": \"{{record_id}}\",\n        \"height\": \"\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (35,'cerb_profile_tab_ticket_overview','Overview','The default overview for ticket records','','profile_tab:ticket',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile Tab: Ticket Overview\",\n    \"revision\": 2,\n    \"requires\": {\n      \"cerb_version\": \"10.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Overview\",\n      \"uri\": \"cerb_profile_tab_ticket_overview\",\n      \"description\": \"The default overview for ticket records\",\n      \"point\": \"profile_tab:ticket\",\n      \"image\": \"\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n        \"uid\": \"profile_tab_overview\",\n        \"_context\": \"profile_tab\",\n        \"name\": \"Overview\",\n        \"context\": \"ticket\",\n        \"extension_id\": \"cerb.profile.tab.dashboard\",\n        \"extension_params\": {\n        	\"layout\": \"sidebar_right\"\n        }\n    },\n    {\n        \"uid\": \"profile_widget_convo\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Conversation\",\n        \"extension_id\": \"cerb.profile.tab.widget.ticket.convo\",\n        \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n        \"pos\": 1,\n        \"width_units\": 4,\n        \"zone\": \"content\",\n        \"extension_params\": []\n    },\n    {\n      \"uid\": \"widget_ticket_status\",\n      \"_context\": \"profile_widget\",\n      \"name\": \"Status\",\n      \"profile_tab_id\": \"{{{profile_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"sidebar\",\n      \"extension_id\": \"cerb.profile.tab.widget.sheet\",\n      \"extension_params\": {\n        \"data_query\": \"type:worklist.records\\r\\nof:ticket\\r\\nquery:(\\r\\n  id:{{record_id}}\\r\\n  limit:1\\r\\n  sort:[id]\\r\\n)\\r\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\r\\n  style: fieldsets\\r\\n  headings@bool: no\\r\\n  paging@bool: no\\r\\n  title_column: image\\r\\n  colors:\\r\\n    labels@csv: #898989, #646464\\r\\n    labels_dark@csv: #898989, #cccccc\\r\\n    statuses@csv: #66aa57, #5585cc, #636363, #d3352a\\r\\n\\r\\ncolumns:\\r\\n  icon/image:\\r\\n    params:\\r\\n      record_uri@raw: cerb:group:{{group_id}}\\r\\n      text_size@raw: 400%\\r\\n  \\r\\n  card/group__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_size: 135%\\r\\n      text_color@raw: labels:0\\r\\n  \\r\\n  card/bucket__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_color@raw: labels:1\\r\\n      text_size: 200%\\r\\n  \\r\\n  text/status:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      text_size: 145%\\r\\n      value_template@raw:\\r\\n        {{status|capitalize}}\\r\\n        {% if reopen_date and status in [\'waiting\',\'closed\'] %}\\r\\n        (<abbr title=\\\"{{reopen_date|date(\'r\')}}\\\">{{reopen_date|date_pretty}}</abbr>)\\r\\n        {% endif %}        \\r\\n      text_color@raw: statuses:{{status_id}}\\r\\n  \\r\\n  toolbar/actions:\\r\\n    label: Actions\\r\\n    params:\\r\\n      kata:\\r\\n        interaction/reopen:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id) or \'open\' == status}}\\r\\n          label: Re-open\\r\\n          icon: upload\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            #confirm@bool: yes\\r\\n            status: open\\r\\n        interaction/move:\\r\\n          uri: cerb:automation:cerb.ticket.move\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id)}}\\r\\n          label: Move\\r\\n          icon: send\\r\\n          keyboard: M\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n        interaction/close:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or status in [\'closed\',\'deleted\']\\r\\n            }}\\r\\n          label: Close\\r\\n          icon: circle-ok\\r\\n          keyboard: C\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: closed\\r\\n        interaction/delete:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or \'deleted\' == status \\r\\n              or not cerb_has_priv(\'contexts.cerberusweb.contexts.ticket.delete\')\\r\\n            }}\\r\\n          label: Delete\\r\\n          icon: circle-remove\\r\\n          keyboard: X\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: deleted\",\n        \"toolbar_kata\": \"\"\n      }\n    },\n    {\n        \"uid\": \"profile_widget_owner\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Owner\",\n        \"extension_id\": \"cerb.profile.tab.widget.html\",\n        \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n        \"pos\": 2,\n        \"width_units\": 4,\n        \"zone\": \"sidebar\",\n        \"extension_params\": {\n          \"template\": \"{% set is_writeable = cerb_record_writeable(record__context,record_id,current_worker__context,current_worker_id) %}\\r\\n<div id=\\\"widget{{widget_id}}\\\">\\r\\n\\t<div style=\\\"float:left;padding:0 10px 5px 5px;\\\">\\r\\n\\t\\t<img src=\\\"{{cerb_avatar_url(record_owner__context,record_owner_id,record_owner_updated)}}\\\" width=\\\"50\\\" style=\\\"border-radius:50px;\\\">\\r\\n\\t</div>\\r\\n\\t<div style=\\\"position:relative;\\\">\\r\\n\\t\\t<div>\\r\\n\\t\\t\\t{% if record_owner_id == 0 %}\\r\\n\\t\\t\\t\\t<span style=\\\"font-size:2em;color:var(--cerb-color-background-contrast-100);font-weight:bold;\\\">\\r\\n\\t\\t\\t\\t\\t({{\'common.nobody\'|cerb_translate|lower}})\\r\\n\\t\\t\\t\\t</span>\\r\\n\\t\\t\\t{% else %}\\r\\n\\t\\t\\t\\t\\t<a href=\\\"javascript:;\\\" class=\\\"cerb-peek-trigger no-underline\\\" style=\\\"font-size:2em;var(--cerb-color-background-contrast-100);font-weight:bold;\\\" data-context=\\\"cerberusweb.contexts.worker\\\" data-context-id=\\\"{{record_owner_id}}\\\">{{record_owner__label}}</a>\\r\\n\\t\\t\\t\\t\\t<div>\\r\\n\\t\\t\\t\\t\\t\\t{{record_owner_title}}\\r\\n\\t\\t\\t\\t\\t</div>\\r\\n\\t\\t\\t{% endif %}\\r\\n\\r\\n\\t\\t\\t{% if is_writeable %}\\r\\n\\t\\t\\t<div class=\\\"cerb-buttons-toolbar\\\" style=\\\"display:none;position:absolute;top:0;right:0;\\\">\\r\\n\\t\\t\\t\\t<button type=\\\"button\\\" title=\\\"{{\'common.assign\'|cerb_translate|capitalize}} (Shift+T)\\\" class=\\\"cerb-button-assign cerb-chooser-trigger\\\" data-context=\\\"cerberusweb.contexts.worker\\\" data-single=\\\"true\\\" data-query=\\\"group:(id:{{record_group_id}}) isDisabled:n\\\">\\r\\n\\t\\t\\t\\t\\t<span class=\\\"glyphicons glyphicons-send\\\"></span>\\r\\n\\t\\t\\t\\t</button>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t{% if record_owner_id %}\\r\\n\\t\\t\\t\\t<button type=\\\"button\\\" title=\\\"{{\'common.unassign\'|cerb_translate|capitalize}} (U)\\\" class=\\\"cerb-button-unassign\\\">\\r\\n\\t\\t\\t\\t\\t<span class=\\\"glyphicons glyphicons-circle-remove\\\"></span>\\r\\n\\t\\t\\t\\t</button>\\r\\n\\t\\t\\t\\t{% endif %}\\r\\n\\t\\t\\t</div>\\r\\n\\t\\t\\t{% endif %}\\r\\n\\t\\t</div>\\r\\n\\t</div>\\r\\n</div>\\r\\n\\r\\n<script type=\\\"text/javascript\\\">\\r\\n$(function() {\\r\\n\\tvar $widget = $(\'#widget{{widget_id}}\');\\r\\n\\tvar $parent = $widget.closest(\'.cerb-profile-widget\')\\r\\n\\t\\t.off(\'.widget{{widget_id}}\')\\r\\n\\t\\t;\\r\\n\\tvar $toolbar = $widget.find(\'div.cerb-buttons-toolbar\');\\r\\n\\tvar $tab = $parent.closest(\'.cerb-profile-layout\');\\r\\n\\t\\r\\n\\tvar $button_take = $widget.find(\'button.cerb-button-take\');\\r\\n\\tvar $button_assign = $widget.find(\'.cerb-chooser-trigger\');\\r\\n\\tvar $button_unassign = $widget.find(\'button.cerb-button-unassign\');\\r\\n\\r\\n\\t$widget.find(\'.cerb-peek-trigger\')\\r\\n\\t\\t.cerbPeekTrigger()\\r\\n\\t\\t;\\r\\n\\t\\t\\r\\n\\t{% if is_writeable %}\\r\\n\\t$widget\\r\\n\\t\\t.on(\'mouseover\', function() {\\r\\n\\t\\t\\t$toolbar.show();\\r\\n\\t\\t})\\r\\n\\t\\t.on(\'mouseout\', function() {\\r\\n\\t\\t\\t$toolbar.hide();\\r\\n\\t\\t})\\r\\n\\t\\t;\\r\\n\\t{% endif %}\\r\\n\\t\\r\\n\\t{% if is_writeable %}\\r\\n\\t$button_assign\\r\\n\\t\\t.cerbChooserTrigger()\\r\\n\\t\\t.on(\'cerb-chooser-selected\', function(e) {\\r\\n\\t\\t\\tif(!e.values || !Array.isArray(e.values))\\r\\n\\t\\t\\t\\treturn;\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\tif(e.values.length != 1)\\r\\n\\t\\t\\t\\treturn;\\r\\n\\r\\n\\t\\t\\tvar owner_id = e.values[0];\\r\\n\\t\\t\\t\\r\\n\\t\\t\\tvar formData = new FormData();\\r\\n\\t\\t\\tformData.set(\'c\', \'profiles\');\\r\\n\\t\\t\\tformData.set(\'a\', \'invoke\');\\r\\n\\t\\t\\tformData.set(\'module\', \'ticket\');\\r\\n\\t\\t\\tformData.set(\'action\', \'quickAssign\');\\r\\n\\t\\t\\tformData.set(\'ticket_id\', \'{{record_id}}\');\\r\\n\\t\\t\\tformData.set(\'owner_id\', owner_id);\\r\\n\\t\\t\\t\\r\\n\\t\\t\\tgenericAjaxPost(formData, null, null, function(response) {\\r\\n\\t\\t\\t\\t// Refresh the entire page\\r\\n\\t\\t\\t\\tdocument.location.reload();\\r\\n\\t\\t\\t});\\r\\n\\t\\t})\\r\\n\\t\\t;\\r\\n\\t\\t\\r\\n\\t$button_unassign\\r\\n\\t\\t.on(\'click\', function(e) {\\r\\n\\t\\t\\tvar formData = new FormData();\\r\\n\\t\\t\\tformData.set(\'c\', \'profiles\');\\r\\n\\t\\t\\tformData.set(\'a\', \'invoke\');\\r\\n\\t\\t\\tformData.set(\'module\', \'ticket\');\\r\\n\\t\\t\\tformData.set(\'action\', \'quickAssign\');\\r\\n\\t\\t\\tformData.set(\'ticket_id\', \'{{record_id}}\');\\r\\n\\t\\t\\tformData.set(\'owner_id\', \'0\');\\r\\n\\t\\t\\t\\r\\n\\t\\t\\tgenericAjaxPost(formData, null, null, function(response) {\\r\\n\\t\\t\\t\\t// Refresh the entire page\\r\\n\\t\\t\\t\\tdocument.location.reload();\\r\\n\\t\\t\\t});\\r\\n\\t\\t})\\r\\n\\t\\t;\\r\\n\\t\\t\\r\\n\\t\\t{# Allow the (t)ake shortcut for \'assign to me\' if unassigned #}\\r\\n\\t\\t{% if record_owner_id == 0%}\\r\\n\\t\\t$parent.on(\'keydown.widget{{widget_id}}\', null, \'T\', function(e) {\\r\\n\\t\\t\\te.stopPropagation();\\r\\n\\t\\t\\te.preventDefault();\\r\\n\\t\\t\\t\\r\\n\\t\\t\\tvar formData = new FormData();\\r\\n\\t\\t\\tformData.set(\'c\', \'profiles\');\\r\\n\\t\\t\\tformData.set(\'a\', \'invoke\');\\r\\n\\t\\t\\tformData.set(\'module\', \'ticket\');\\r\\n\\t\\t\\tformData.set(\'action\', \'quickAssign\');\\r\\n\\t\\t\\tformData.set(\'ticket_id\', \'{{record_id}}\');\\r\\n\\t\\t\\tformData.set(\'owner_id\', \'{{current_worker_id}}\');\\r\\n\\r\\n\\t\\t\\tgenericAjaxPost(formData, null, null, function(response) {\\r\\n\\t\\t\\t\\t// Refresh the entire page\\r\\n\\t\\t\\t\\tdocument.location.reload();\\r\\n\\t\\t\\t});\\r\\n\\t\\t});\\r\\n\\t\\t{% endif %}\\r\\n\\t\\t\\r\\n\\t\\t$parent.on(\'keydown.widget{{widget_id}}\', null, \'Shift+T\', function(e) {\\r\\n\\t\\t\\te.stopPropagation();\\r\\n\\t\\t\\te.preventDefault();\\r\\n\\t\\t\\t$button_assign.click();\\r\\n\\t\\t});\\r\\n\\r\\n\\t\\t$parent.on(\'keydown.widget{{widget_id}}\', null, \'U\', function(e) {\\r\\n\\t\\t\\te.stopPropagation();\\r\\n\\t\\t\\te.preventDefault();\\r\\n\\t\\t\\t$button_unassign.click();\\r\\n\\t\\t});\\r\\n\\r\\n\\t{% endif %}\\r\\n});\\r\\n</script>\"\n        }\n    },\n    {\n        \"uid\": \"profile_widget_ticket_fields\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Ticket\",\n        \"extension_id\": \"cerb.profile.tab.widget.fields\",\n        \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n        \"pos\": 3,\n        \"width_units\": 4,\n        \"zone\": \"sidebar\",\n        \"extension_params\": {\n            \"context\": \"cerberusweb.contexts.ticket\",\n            \"context_id\": \"{{record_id}}\",\n            \"properties\": [\n                [\n                    \"importance\",\n                    \"created\",\n                    \"updated\",\n                    \"closed\",\n                    \"elapsed_response_first\",\n                    \"elapsed_resolution_first\",\n                    \"spam_score\",\n                    \"id\"\n                ]\n            ],\n            \"links\": {\n                \"show\": \"1\"\n            },\n            \"search\": {\n                \"context\": [\n                    \"cerberusweb.contexts.message\",\n                    \"cerberusweb.contexts.address\",\n                    \"cerberusweb.contexts.ticket\",\n                    \"cerberusweb.contexts.attachment\"\n                ],\n                \"label_singular\": [\n                    \"Message\",\n                    \"Participant\",\n                    \"Participant History\",\n                    \"Attachment\"\n                ],\n                \"label_plural\": [\n                    \"Messages\",\n                    \"Participants\",\n                    \"Participant History\",\n                    \"Attachments\"\n                ],\n                \"query\": [\n                    \"ticket.id:{{record_id}}\",\n                    \"ticket.id:{{record_id}}\",\n                    \"participant.id:[{{record_requesters|keys|join(\',\')}}] subtotal:status\",\n                    \"on.ticket:(id:{{record_id}}) OR on.message:(ticket.id:{{record_id}}) OR on.comment:(on.ticket:(id:{{record_id}}) OR on.message:(ticket.id:{{record_id}}))\"\n                ]\n            }\n        }\n    },\n    {\n        \"uid\": \"profile_widget_org_fields\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Organization\",\n        \"extension_id\": \"cerb.profile.tab.widget.fields\",\n        \"profile_tab_id\": \"{{{uid.profile_tab_overview}}}\",\n        \"pos\": 4,\n        \"width_units\": 4,\n        \"zone\": \"sidebar\",\n        \"extension_params\": {\n            \"context\": \"cerberusweb.contexts.org\",\n            \"context_id\": \"{{record_org_id}}\",\n            \"properties\": {\n                \"0\": [\n                    \"_label\",\n                    \"country\",\n                    \"phone\"\n                ]\n            },\n            \"links\": {\n                \"show\": \"1\"\n            },\n            \"search\": {\n                \"context\": [\n                    \"cerberusweb.contexts.ticket\"\n                ],\n                \"label_singular\": [\n                    \"Ticket\"\n                ],\n                \"label_plural\": [\n                    \"Tickets\"\n                ],\n                \"query\": [\n                    \"org.id:{{record_org_id}}\"\n                ]\n            }\n        }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (36,'cerb_profile_widget_ticket_owner','Owner','A widget that display the current ticket owner and allows quick assignment','','profile_widget:ticket',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile: Ticket Owner\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Owner\",\n      \"uri\": \"cerb_profile_widget_ticket_owner\",\n      \"description\": \"A widget that display the current ticket owner and allows quick assignment\",\n      \"point\": \"profile_widget:ticket\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Profile Dashboard\",\n          \"key\": \"profile_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.profile.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n        \"uid\": \"widget_ticket_owner\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Owner\",\n        \"extension_id\": \"cerb.profile.tab.widget.sheet\",\n        \"profile_tab_id\": \"{{{profile_tab_id}}}\",\n        \"pos\": 0,\n        \"width_units\": 2,\n        \"zone\": \"sidebar\",\n        \"extension_params\": {\n          \"data_query\": \"type:worklist.records\\r\\nof:ticket\\r\\nexpand:[owner_]\\r\\nquery:(\\r\\n  id:{{record_id}}\\r\\n  limit:1\\r\\n  sort:[id]\\r\\n)\\r\\nformat:dictionaries\",\n          \"cache_secs\": \"\",\n          \"placeholder_simulator_kata\": \"record_id: 2\",\n          \"sheet_kata\": \"layout:\\r\\n  style: fieldsets\\r\\n  headings@bool: no\\r\\n  paging@bool: no\\r\\n  title_column: image\\r\\n  colors:\\r\\n    labels@csv: #646464\\r\\n    labels_dark@csv: #cccccc\\r\\n\\r\\ncolumns:\\r\\n  icon/image:\\r\\n    params:\\r\\n      record_uri@raw: cerb:worker:{{owner_id}}\\r\\n      text_size: 400%\\r\\n      text_color: labels\\r\\n\\r\\n  card/owner__label:\\r\\n    params:\\r\\n      image@bool: no\\r\\n      underline@bool: no\\r\\n      bold@bool: yes\\r\\n      text_size: 200%\\r\\n      text_color: labels\\r\\n      label_template@raw: {{owner__label|default(\'(nobody)\')}}\\r\\n  \\r\\n  text/owner_title:\\r\\n    params:\\r\\n      text_color: labels\\r\\n      \\r\\n  toolbar/actions:\\r\\n    params:\\r\\n      kata:\\r\\n        interaction/assign:\\r\\n          uri: cerb:automation:cerb.ticket.assign\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\',id) or owner_id}}\\r\\n          label@raw: Assign\\r\\n          icon: tag\\r\\n          keyboard: Shift+T\\r\\n          inputs:\\r\\n            ticket: {{id}}\\r\\n        interaction/unassign:\\r\\n          uri: cerb:automation:cerb.ticket.assign\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\',id) or not owner_id}}\\r\\n          label@raw: Unassign\\r\\n          icon: remove\\r\\n          keyboard: Shift+U\\r\\n          inputs:\\r\\n            ticket: {{id}}\\r\\n            unassign: yes\",\n          \"toolbar_kata\": \"\"\n        }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (37,'cerb_profile_widget_ticket_participants','Participants','Manage participants on this ticket','','profile_widget:ticket',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile: Ticket Participants\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Participants\",\n      \"uri\": \"cerb_profile_widget_ticket_participants\",\n      \"description\": \"Manage participants on this ticket\",\n      \"point\": \"profile_widget:ticket\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Profile Dashboard\",\n          \"key\": \"profile_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.profile.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n        \"uid\": \"widget_ticket_participiants\",\n        \"_context\": \"profile_widget\",\n        \"name\": \"Participants\",\n        \"profile_tab_id\": \"{{{profile_tab_id}}}\",\n        \"extension_id\": \"cerb.profile.tab.widget.sheet\",\n        \"pos\": 0,\n        \"width_units\": 4,\n        \"zone\": \"sidebar\",\n        \"extension_params\": {\n          \"data_query\": \"type:worklist.records\\r\\nof:addresses\\r\\nexpand:[contact__label]\\r\\nquery:(\\r\\n  ticket.id:[{{record_id}}]\\r\\n  sort:email\\r\\n  limit: 5\\r\\n)\\r\\nformat:dictionaries\",\n          \"cache_secs\": \"0\",\n          \"placeholder_simulator_kata\": \"record_id: 1\",\n          \"sheet_kata\": \"layout:\\r\\n  style: table\\r\\n  headings@bool: no\\r\\n  paging@bool: yes\\r\\n  filtering@bool: yes\\r\\n\\r\\ncolumns:\\r\\n  selection/id:\\r\\n  card/email:\\r\\n    label: Email\\r\\n    params:\\r\\n      image@bool: yes\\r\\n      bold@bool: yes\\r\\n      context_key: _context\\r\\n      label_key: _label\\r\\n      id_key: id\",\n          \"toolbar_kata\": \"interaction/add:\\r\\n  label: Add participants\\r\\n  uri: cerb:automation:cerb.ticket.participants.add\\r\\n  inputs:\\r\\n    ticket@key: record_id\\r\\n  icon: circle-plus\\r\\n  hidden@bool: \\r\\n    {% if row_selections is not empty %}yes{% endif %}\\r\\n  after:\\r\\n    refresh_widgets@list:\\r\\n      Participants\\r\\n\\r\\ninteraction/remove:\\r\\n  label: Remove {{row_selections|length}} selections\\r\\n  uri: cerb:automation:cerb.ticket.participants.remove\\r\\n  inputs:\\r\\n    ticket@key: record_id \\r\\n    participants@key: row_selections \\r\\n  icon: circle-remove\\r\\n  hidden@bool: \\r\\n    {% if row_selections is empty %}yes{% endif %}\\r\\n  after:\\r\\n    refresh_widgets@list:\\r\\n      Participants\\r\\n\"\n        }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (38,'cerb_project_board_kanban','Kanban','A three column task management board','','project_board',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Project Board: Kanban Template\",\n    \"revision\": 2020100501,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Kanban\",\n      \"uri\": \"cerb_project_board_kanban\",\n      \"description\": \"A three column task management board\",\n      \"point\": \"project_board\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Project Name:\",\n          \"key\": \"prompt_project_name\",\n          \"params\": {\n            \"default\": \"Kanban Project Board\",\n            \"placeholder\": \"(the name of your project board)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"project_board_kanban\",\n      \"_context\": \"cerberusweb.contexts.project.board\",\n      \"name\": \"{{{prompt_project_name}}}\",\n      \"owner__context\": \"app\",\n      \"owner_id\": \"0\",\n      \"columns\": [\n        \"{{{uid.project_board_kanban_todo}}}\",\n        \"{{{uid.project_board_kanban_in_progress}}}\",\n        \"{{{uid.project_board_kanban_completed}}}\"\n      ],\n      \"cards_kata\": \"automation/task_sheet:\\n  uri: cerb:automation:cerb.projectBoard.card.sheet\\n  disabled@bool:\\n    {{card__context is not record type (\'task\')}}\\n  inputs:\\n    sheet:\\n      columns:\\n        card/card__label:\\n          label: Record\\n        text/card_status:\\n          label: Status\\n        slider/card_importance:\\n          label: Importance\\n        card/card_owner__label:\\n          label: Owner\\n          params:\\n            image@bool: yes\"\n    },\n    {\n      \"uid\": \"project_board_kanban_todo\",\n      \"_context\": \"cerberusweb.contexts.project.board.column\",\n      \"name\": \"TODO\",\n      \"board_id\": \"{{{uid.project_board_kanban}}}\",\n      \"cards\": [\n      ],\n      \"cards_kata\": \"\",\n      \"functions_kata\": \"\",\n      \"toolbar_kata\": \"interaction/add:\\n  uri: cerb:automation:cerb.projectBoard.record.create\\n  icon: circle-plus\\n  inputs:\\n    record_type: task\\n    column: {{column_id}}\\n\\ninteraction/find:\\n  uri: cerb:automation:cerb.projectBoard.toolbar.task.find\\n  icon: search\\n  inputs:\\n    column: {{column_id}}\"\n    },\n    {\n      \"uid\": \"project_board_kanban_in_progress\",\n      \"_context\": \"cerberusweb.contexts.project.board.column\",\n      \"name\": \"In Progress\",\n      \"board_id\": \"{{{uid.project_board_kanban}}}\",\n      \"cards\": [\n      ],\n      \"cards_kata\": \"\",\n      \"functions_kata\": \"\",\n      \"toolbar_kata\": \"\"\n    },\n    {\n      \"uid\": \"project_board_kanban_completed\",\n      \"_context\": \"cerberusweb.contexts.project.board.column\",\n      \"name\": \"Completed!\",\n      \"board_id\": \"{{{uid.project_board_kanban}}}\",\n      \"cards\": [\n      ],\n      \"cards_kata\": \"automation/completed:\\n  uri: cerb:automation:cerb.projectBoard.card.done\\n\",\n      \"functions_kata\": \"automation/close:\\n  uri: cerb:automation:cerb.projectBoard.action.task.close\\n\",\n      \"toolbar_kata\": \"\"\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (39,'cerb_task_for_me','New task for me','A new task assigned to you','','task',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Task for me\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"New task for me\",\n      \"uri\": \"cerb_task_for_me\",\n      \"description\": \"A new task assigned to you\",\n      \"point\": \"task\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Current worker\",\n          \"key\": \"current_worker_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.worker\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Task name\",\n          \"key\": \"prompt_task_name\",\n          \"params\": {\n            \"default\": \"New task\",\n            \"placeholder\": \"(e.g. Prepare quarterly report)\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Importance\",\n          \"key\": \"prompt_importance\",\n          \"params\": {\n            \"options\": {\"Low\":25,\"Normal\":50,\"High\":75,\"Urgent\":100},\n            \"default\": \"50\"\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"task_new\",\n      \"_context\": \"task\",\n      \"title\": \"{{{prompt_task_name}}}\",\n      \"owner_id\": \"{{{current_worker_id}}}\",\n      \"importance\": \"{{{prompt_importance}}}\",\n      \"status\": \"o\"\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (40,'cerb_workspace_page_empty','Empty Workspace','A blank canvas constrained only by your imagination','','workspace_page',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Page Wizard: Empty Workspace\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Empty Workspace\",\n      \"uri\": \"cerb_workspace_page_empty\",\n      \"description\": \"A blank canvas constrained only by your imagination\",\n      \"point\": \"workspace_page\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context:\",\n          \"key\": \"owner_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context ID:\",\n          \"key\": \"owner_context_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Workspace Name:\",\n          \"key\": \"prompt_workspace_name\",\n          \"params\": {\n            \"default\": \"Workspace\",\n            \"placeholder\": \"(the name of your workspace)\"\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_empty\",\n      \"_context\": \"workspace_page\",\n      \"name\": \"{{{prompt_workspace_name}}}\",\n      \"owner__context\": \"{{{owner_context}}}\",\n      \"owner_id\": \"{{{owner_context_id}}}\",\n      \"extension_id\": \"core.workspace.page.workspace\"\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (41,'cerb_workspace_page_home','Home','A home page showing the current worker\'s tickets, tasks, reminders, and calendar','','workspace_page',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Page Wizard: Home Overview\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Home\",\n      \"uri\": \"cerb_workspace_page_home\",\n      \"description\": \"A home page showing the current worker\'s tickets, tasks, reminders, and calendar\",\n      \"point\": \"workspace_page\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context:\",\n          \"key\": \"owner_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context ID:\",\n          \"key\": \"owner_context_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_home\",\n      \"_context\": \"workspace_page\",\n      \"name\": \"Home\",\n      \"owner__context\": \"{{{owner_context}}}\",\n      \"owner_id\": \"{{{owner_context_id}}}\",\n      \"extension_id\": \"core.workspace.page.workspace\"\n    },\n    {\n      \"uid\": \"workspace_tab_overview\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"Overview\",\n      \"page_id\": \"{{{uid.workspace_home}}}\",\n      \"pos\": 0,\n      \"extension_id\": \"core.workspace.tab.dashboard\",\n      \"params\": {\n        \"layout\": \"\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_my_tickets\",\n      \"_context\": \"workspace_widget\",\n      \"tab_id\": \"{{{uid.workspace_tab_overview}}}\",\n      \"label\": \"My Tickets\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.ticket\",\n        \"query_required\": \"owner.id:me status:o sort:-updated\",\n        \"query\": \"\",\n        \"render_limit\": \"5\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_last_wrote_address_id\",\n          \"t_updated_date\",\n          \"t_group_id\",\n          \"t_bucket_id\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_my_drafts\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"tab_id\": \"{{{uid.workspace_tab_overview}}}\",\n      \"label\": \"My Drafts\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 2,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.mail.draft\",\n        \"query_required\": \"worker.id:{{current_worker_id}}\",\n        \"query\": \"\",\n        \"render_limit\": \"5\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"m_hint_to\",\n          \"m_type\",\n          \"m_worker_id\",\n          \"m_is_queued\",\n          \"m_queue_delivery_date\",\n          \"m_queue_fails\",\n          \"m_updated\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_my_tasks\",\n      \"_context\": \"workspace_widget\",\n      \"tab_id\": \"{{{uid.workspace_tab_overview}}}\",\n      \"label\": \"My Tasks\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 3,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.task\",\n        \"query_required\": \"status:o owner.id:me sort:due\",\n        \"query\": \"\",\n        \"render_limit\": \"5\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_due_date\",\n          \"t_importance\",\n          \"t_updated_date\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_my_reminders\",\n      \"_context\": \"workspace_widget\",\n      \"tab_id\": \"{{{uid.workspace_tab_overview}}}\",\n      \"label\": \"My Reminders\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 4,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.reminder\",\n        \"query_required\": \"worker.id:me closed:n sort:remindAt\",\n        \"query\": \"\",\n        \"render_limit\": \"5\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"r_name\",\n          \"r_remind_at\",\n          \"r_updated_at\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_my_calendar\",\n      \"_context\": \"workspace_widget\",\n      \"tab_id\": \"{{{uid.workspace_tab_overview}}}\",\n      \"label\": \"My Calendar\",\n      \"extension_id\": \"core.workspace.widget.calendar\",\n      \"pos\": 5,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"calendar_id\": \"{{current_worker_calendar_id}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (42,'cerb_workspace_page_mail','Mail','A page for mail processing with open tickets, sent messages, and drafts','','workspace_page',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Page Wizard: Mail\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Mail\",\n      \"uri\": \"cerb_workspace_page_mail\",\n      \"description\": \"A page for mail processing with open tickets, sent messages, and drafts\",\n      \"point\": \"workspace_page\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context:\",\n          \"key\": \"owner_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context ID:\",\n          \"key\": \"owner_context_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_mail\",\n      \"_context\": \"workspace_page\",\n      \"name\": \"Mail\",\n      \"owner__context\": \"{{{owner_context}}}\",\n      \"owner_id\": \"{{{owner_context_id}}}\",\n      \"extension_id\": \"core.workspace.page.workspace\"\n    },\n    {\n      \"uid\": \"workspace_tab_inbox\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"Inbox\",\n      \"page_id\": \"{{{uid.workspace_mail}}}\",\n      \"pos\": 0,\n      \"extension_id\": \"core.workspace.tab.worklists\",\n      \"params\": [\n\n      ]\n    },\n    {\n      \"uid\": \"workspace_tab_sent\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"Sent\",\n      \"page_id\": \"{{{uid.workspace_mail}}}\",\n      \"pos\": 1,\n      \"extension_id\": \"core.workspace.tab.worklists\",\n      \"params\": [\n\n      ]\n    },\n    {\n      \"uid\": \"workspace_tab_drafts\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"Drafts\",\n      \"page_id\": \"{{{uid.workspace_mail}}}\",\n      \"pos\": 2,\n      \"extension_id\": \"core.workspace.tab.worklists\",\n      \"params\": [\n\n      ]\n    },\n    {\n      \"uid\": \"workspace_list_mail\",\n      \"_context\": \"workspace_list\",\n      \"context\": \"ticket\",\n      \"tab_id\": \"{{{uid.workspace_tab_inbox}}}\",\n      \"pos\": 0,\n      \"view\": {\n        \"title\": \"Needs Attention\",\n        \"model\": {\n          \"options\": {\n            \"header_color\": \"#6a87db\"\n          },\n          \"columns\": [\n            \"t_last_wrote_address_id\",\n            \"t_importance\",\n            \"t_group_id\",\n            \"t_bucket_id\",\n            \"t_org_id\",\n            \"t_owner_id\",\n            \"t_updated_date\"\n          ],\n          \"params\": [\n\n          ],\n          \"params_required_query\": \"status:[o] inGroupsOf:me\",\n          \"limit\": 15,\n          \"sort_by\": \"t_updated_date\",\n          \"sort_asc\": false,\n          \"subtotals\": \"t_group_id\",\n          \"context\": \"cerberusweb.contexts.ticket\"\n        }\n      }\n    },\n    {\n      \"uid\": \"workspace_list_mail_sent\",\n      \"_context\": \"workspace_list\",\n      \"context\": \"message\",\n      \"tab_id\": \"{{{uid.workspace_tab_sent}}}\",\n      \"pos\": 1,\n      \"view\": {\n        \"title\": \"Sent messages\",\n        \"model\": {\n          \"options\": {\n            \"header_color\": \"#6a87db\"\n          },\n          \"columns\": [\n            \"a_email\",\n            \"t_group_id\",\n            \"m_created_date\",\n            \"m_worker_id\"\n          ],\n          \"params\": [\n\n          ],\n          \"params_required_query\": \"worker.id:!0 isOutgoing:y\",\n          \"limit\": 15,\n          \"sort_by\": \"m_created_date\",\n          \"sort_asc\": false,\n          \"subtotals\": \"m_worker_id\",\n          \"context\": \"cerberusweb.contexts.message\"\n        }\n      }\n    },\n    {\n      \"uid\": \"workspace_list_mail_drafts\",\n      \"_context\": \"workspace_list\",\n      \"context\": \"draft\",\n      \"tab_id\": \"{{{uid.workspace_tab_drafts}}}\",\n      \"pos\": 2,\n      \"view\": {\n        \"title\": \"My drafts\",\n        \"model\": {\n          \"options\": {\n            \"header_color\": \"#6a87db\"\n          },\n          \"columns\": [\n            \"m_hint_to\",\n            \"m_worker_id\",\n            \"m_type\",\n            \"m_updated\"\n          ],\n          \"params\": [\n\n          ],\n          \"params_required_query\": \"worker.id:{{current_worker_id}}\",\n          \"limit\": 15,\n          \"sort_by\": \"m_updated\",\n          \"sort_asc\": false,\n          \"subtotals\": \"\",\n          \"context\": \"cerberusweb.contexts.mail.draft\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (43,'cerb_workspace_page_reports','Reports','A page with customizable reporting dashboards','','workspace_page',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Page Wizard: Reports\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Reports\",\n      \"uri\": \"cerb_workspace_page_reports\",\n      \"description\": \"A page with customizable reporting dashboards\",\n      \"point\": \"workspace_page\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context:\",\n          \"key\": \"owner_context\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Owner Context ID:\",\n          \"key\": \"owner_context_id\",\n          \"hidden\": true,\n          \"params\": {\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_reports\",\n      \"_context\": \"workspace_page\",\n      \"name\": \"Reports\",\n      \"owner__context\": \"{{{owner_context}}}\",\n      \"owner_id\": \"{{{owner_context_id}}}\",\n      \"extension_id\": \"core.workspace.page.workspace\"\n    },\n    {\n      \"uid\": \"workspace_tab_191\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"Created Tickets by Group\",\n      \"extension_id\": \"core.workspace.tab.dashboard\",\n      \"page_id\": \"{{{uid.workspace_reports}}}\",\n      \"params\": {\n        \"layout\": \"\",\n        \"prompts_kata\": \"date_range/input_date_range:\\n  label: Date range:\\n  default: today -1 week\\n\\npicklist/input_date_subtotal_by:\\n  label: By:\\n  default: day\\n  params:\\n    options@csv: day, week, month, year\\n\\nchooser/input_groups:\\n  label: Groups:\\n  default:\\n  params:\\n    context: group\\n    single@bool: false\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_359\",\n      \"_context\": \"workspace_widget\",\n      \"label\": \"Created Tickets by Group Over Time\",\n      \"extension_id\": \"cerb.workspace.widget.chart.timeseries\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:tickets\\r\\nby:[created@{{input_date_subtotal_by}},group~10]\\r\\nquery:(\\r\\n\\tcreated:\\\"{{input_date_range}}\\\"\\r\\n\\t{% if input_groups %}\\r\\n\\tgroup.id:[{{input_groups}}]\\r\\n\\t{% endif %}\\r\\n)\\r\\nformat:timeseries\",\n        \"cache_secs\": \"300\",\n        \"chart_as\": \"bar_stacked\",\n        \"xaxis_label\": \"\",\n        \"yaxis_label\": \"\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\",\n          \"show_points\": \"1\"\n        }\n      },\n      \"tab_id\": \"{{{uid.workspace_tab_191}}}\"\n    },\n    {\n      \"uid\": \"workspace_widget_360\",\n      \"_context\": \"workspace_widget\",\n      \"label\": \"Created Tickets by Group\",\n      \"extension_id\": \"cerb.workspace.widget.chart.table\",\n      \"pos\": 2,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:tickets\\r\\nby:[group~10]\\r\\nquery:(\\r\\n\\tcreated:\\\"{{input_date_range}}\\\"\\r\\n\\t{% if input_groups %}\\r\\n\\tgroup.id:[{{input_groups}}]\\r\\n\\t{% endif %}\\r\\n)\\r\\nformat:table\",\n        \"cache_secs\": \"300\"\n      },\n      \"tab_id\": \"{{{uid.workspace_tab_191}}}\"\n    },\n    {\n      \"uid\": \"workspace_widget_361\",\n      \"_context\": \"workspace_widget\",\n      \"label\": \"Created Tickets\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 3,\n      \"width_units\": 4,\n      \"zone\": \"