INSERT INTO `package_library` VALUES (44,'cerb_workspace_tab_dashboard','Dashboard','A dashboard with customizable widgets','','workspace_tab',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"library\": {\n      \"name\": \"Dashboard\",\n      \"uri\": \"cerb_workspace_tab_dashboard\",\n      \"description\": \"A dashboard with customizable widgets\",\n      \"point\": \"workspace_tab\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Page\",\n          \"key\": \"workspace_page_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.page\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Name:\",\n          \"key\": \"prompt_dashboard_name\",\n          \"params\": {\n            \"placeholder\": \"(e.g. Dashboard)\",\n            \"default\": \"Dashboard\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Layout:\",\n          \"key\": \"prompt_layout\",\n          \"params\": {\n            \"options\": {\"Open\":\"\",\"Left Sidebar\":\"sidebar_left\",\"Right Sidebar\":\"sidebar_right\",\"3-Column\":\"thirds\"},\n            \"default\": \"\"\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_tab_dashboard\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"{{{prompt_dashboard_name}}}\",\n      \"page_id\": \"{{{workspace_page_id}}}\",\n      \"pos\": 0,\n      \"extension_id\": \"core.workspace.tab.dashboard\",\n      \"params\": {\n        \"layout\": \"{{{prompt_layout}}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (45,'cerb_workspace_tab_dashboard_with_filters','Dashboard with filters','A dashboard with customizable widgets that update from user-editable filters','','workspace_tab',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\"\n    },\n    \"library\": {\n      \"name\": \"Dashboard with filters\",\n      \"uri\": \"cerb_workspace_tab_dashboard_with_filters\",\n      \"description\": \"A dashboard with customizable widgets that update from user-editable filters\",\n      \"point\": \"workspace_tab\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Page\",\n          \"key\": \"workspace_page_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.page\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Name:\",\n          \"key\": \"prompt_dashboard_name\",\n          \"params\": {\n            \"placeholder\": \"(e.g. Dashboard)\",\n            \"default\": \"Dashboard\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Layout:\",\n          \"key\": \"prompt_layout\",\n          \"params\": {\n            \"options\": {\n              \"Open\": \"\",\n              \"Left Sidebar\": \"sidebar_left\",\n              \"Right Sidebar\": \"sidebar_right\",\n              \"3-Column\": \"thirds\"\n            },\n            \"default\": \"\"\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_tab_dashboard\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"{{{prompt_dashboard_name}}}\",\n      \"page_id\": \"{{{workspace_page_id}}}\",\n      \"extension_id\": \"core.workspace.tab.dashboard\",\n      \"params\": {\n        \"layout\": \"{{{prompt_layout}}}\",\n        \"prompts_kata\": \"date_range/input_date_range:\\n  label: Date range:\\n  default: jan 1 to now\\n  params:\\n    # presets:\\n    #  today:\\n    #    query: today to now\\n    #  30d:\\n    #    label: 30 days\\n    #    query: -30 days to now\\n    #  ytd:\\n    #    query: jan 1 to now\\n    #  all:\\n    #    query: big bang to now\\n\\rpicklist/input_date_subtotal_by:\\n  label: By:\\n  default: month\\n  params:\\n    options@csv: day, week, month, year\\n\\npicklist/input_statuses:\\n  label: Statuses:\\n  default@json: []\\n  params:\\n    multiple: true\\n    options@csv: open, waiting, closed, deleted\\n\\nchooser/input_groups:\\n  label: Groups:\\n  default:\\n  params:\\n    context: group\\n    single@bool: false\"\n      }\n    },\n    {\n      \"uid\": \"widget_example\",\n      \"_context\": \"workspace_widget\",\n      \"label\": \"Filtered Chart\",\n      \"extension_id\": \"cerb.workspace.widget.chart.timeseries\",\n      \"tab_id\": \"{{{uid.workspace_tab_dashboard}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"{# These placeholders are automatically set by the dashboard filters #}\\n{# See: https://cerb.ai/docs/dashboards/#prompts #}\\ntype:worklist.subtotals\\nof:ticket\\nby.count:[created@{{input_date_subtotal_by}},group~10]\\nquery:(\\n  created:\\\"{{input_date_range}}\\\"\\n  {% if input_groups %}\\n  group.id:[{{input_groups}}]\\n  {% endif %}\\n  {% if input_statuses %}\\n  status:[{{input_statuses|join(\',\')}}]\\n  {% endif %}\\n)\\nformat:timeseries\",\n        \"cache_secs\": \"\",\n        \"chart_as\": \"bar_stacked\",\n        \"xaxis_label\": \"\",\n        \"yaxis_label\": \"\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (46,'cerb_workspace_tab_world_clocks','World Clocks','A dashboard with world clocks across major timezones','','workspace_tab',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"library\": {\n      \"name\": \"World Clocks\",\n      \"uri\": \"cerb_workspace_tab_world_clocks\",\n      \"description\": \"A dashboard with world clocks across major timezones\",\n      \"point\": \"workspace_tab\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Page\",\n          \"key\": \"workspace_page_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.page\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ],\n      \"placeholders\": [\n\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_tab_clocks\",\n      \"_context\": \"workspace_tab\",\n      \"name\": \"World Clocks\",\n      \"page_id\": \"{{{workspace_page_id}}}\",\n      \"extension_id\": \"core.workspace.tab.dashboard\",\n      \"params\": {\n        \"layout\": \"\"\n      }\n    },\n    {\n      \"uid\": \"clock_los_angeles\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Los Angeles\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 1,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"America/Los_Angeles\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_denver\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Denver\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 2,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"America/Denver\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_winnipeg\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Winnipeg\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 3,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"America/Winnipeg\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_new_york\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"New York\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 4,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"America/New_York\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_london\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"London\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 5,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"Europe/London\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_berlin\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Berlin\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 6,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"Europe/Berlin\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_johannesburg\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Johannesburg\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 7,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"Africa/Johannesburg\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_moscow\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Moscow\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 8,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"Europe/Moscow\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"clock_sydney\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Sydney\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"tab_id\": \"{{{uid.workspace_tab_clocks}}}\",\n      \"pos\": 9,\n      \"width_units\": 1,\n      \"zone\": \"content\",\n      \"params\": {\n        \"timezone\": \"Australia/Sydney\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (47,'cerb_workspace_widget_chart_categories','Chart: Categories','A data query driven categories visualization','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Chart: Categories\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Chart: Categories\",\n      \"uri\": \"cerb_workspace_widget_chart_categories\",\n      \"description\": \"A data query driven categories visualization\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"Messages sent per worker by group\": \"messages_per_worker_by_group\",\n              \"Tickets per group by status\": \"tickets_per_group_by_status\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_messages_per_worker_by_group\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'messages_per_worker_by_group\' %}}true{{% endif %}}\",\n      \"label\": \"Messages Sent Per Worker By Group\",\n      \"extension_id\": \"cerb.workspace.widget.chart.categories\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"left\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:message\\r\\nby:[worker~10,group~10]\\r\\nquery:(\\r\\n\\tcreated:\\\"-1 year to now\\\"\\r\\n\\tworker:(isDisabled:n id:>0)\\r\\n\\tisOutgoing:y\\r\\n\\tisBroadcast:n\\r\\n)\\r\\nformat:categories\",\n        \"cache_secs\": \"\",\n        \"xaxis_format\": \"text\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\"\n      }\n    },\n    {\n      \"uid\": \"widget_tickets_per_group_by_status\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_per_group_by_status\' %}}true{{% endif %}}\",\n      \"label\": \"Tickets Per Group By Status\",\n      \"extension_id\": \"cerb.workspace.widget.chart.categories\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"left\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:ticket\\r\\nby:[group~10,status]\\r\\nquery:()\\r\\nformat:categories\",\n        \"cache_secs\": \"\",\n        \"xaxis_format\": \"text\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (48,'cerb_workspace_widget_chart_time_series','Chart: Time Series','A data query driven time series visualization','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Chart: Time Series\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Chart: Time Series\",\n      \"uri\": \"cerb_workspace_widget_chart_time_series\",\n      \"description\": \"A data query driven time series visualization\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"Tickets created per month by group\": \"tickets_per_month_by_group\",\n              \"Tickets created per week by group\": \"tickets_per_week_by_group\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_tickets_per_month_by_group\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_per_month_by_group\' %}}true{{% endif %}}\",\n      \"label\": \"Tickets Created Per Month By Group\",\n      \"extension_id\": \"cerb.workspace.widget.chart.timeseries\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:ticket\\r\\nby.count:[created@month,group~10]\\r\\nquery:(\\r\\n  created:\\\"first day of this month -1 year to now\\\"\\r\\n)\\r\\nformat:timeseries\",\n        \"cache_secs\": \"\",\n        \"chart_as\": \"bar_stacked\",\n        \"xaxis_label\": \"\",\n        \"yaxis_label\": \"\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\"\n        }\n      }\n    },\n    {\n      \"uid\": \"widget_tickets_per_week_by_group\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_per_week_by_group\' %}}true{{% endif %}}\",\n      \"label\": \"Tickets Created Per Week By Group\",\n      \"extension_id\": \"cerb.workspace.widget.chart.timeseries\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 4,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:ticket\\r\\nby.count:[created@week,group~10]\\r\\nquery:(\\r\\n  created:\\\"first day of this month -1 month to now\\\"\\r\\n)\\r\\nformat:timeseries\",\n        \"cache_secs\": \"\",\n        \"chart_as\": \"bar_stacked\",\n        \"xaxis_label\": \"\",\n        \"yaxis_label\": \"\",\n        \"yaxis_format\": \"number\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (49,'cerb_workspace_widget_clock','Clock','A clock widget with a configurable timezone','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Clock\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Clock\",\n      \"uri\": \"cerb_workspace_widget_clock\",\n      \"description\": \"A clock widget with a configurable timezone\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Timezone:\",\n          \"key\": \"prompt_timezone\",\n          \"params\": {\n            \"default\": \"los_angeles\",\n            \"options\": {\n              \"Berlin\": \"berlin\",\n              \"Denver\": \"denver\",\n              \"Johannesburg\": \"johannesburg\",\n              \"Kolkata\": \"kolkata\",\n              \"London\": \"london\",\n              \"Los Angeles\": \"los_angeles\",\n              \"Moscow\": \"moscow\",\n              \"New York\": \"new_york\",\n              \"Sao Paulo\": \"sao_paulo\",\n              \"Shanghai\": \"shanghai\",\n              \"Sydney\": \"sydney\",\n              \"Tokyo\": \"tokyo\",\n              \"Winnipeg\": \"winnipeg\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_clock_berlin\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'berlin\' %}}true{{% endif %}}\",\n      \"label\": \"Berlin\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Europe/Berlin\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_denver\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'denver\' %}}true{{% endif %}}\",\n      \"label\": \"Denver\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"America/Denver\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_kolkata\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'kolkata\' %}}true{{% endif %}}\",\n      \"label\": \"Kolkata\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Asia/Kolkata\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_johannesburg\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'johannesburg\' %}}true{{% endif %}}\",\n      \"label\": \"Johannesburg\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Africa/Johannesburg\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_london\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'london\' %}}true{{% endif %}}\",\n      \"label\": \"London\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Europe/London\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_los_angeles\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'los_angeles\' %}}true{{% endif %}}\",\n      \"label\": \"Los Angeles\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"America/Los_Angeles\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_moscow\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'moscow\' %}}true{{% endif %}}\",\n      \"label\": \"Moscow\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Europe/Moscow\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_new_york\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'new_york\' %}}true{{% endif %}}\",\n      \"label\": \"New York\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"America/New_York\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_sao_paulo\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'sao_paulo\' %}}true{{% endif %}}\",\n      \"label\": \"Sao Paulo\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"America/Sao_Paulo\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_shanghai\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'shanghai\' %}}true{{% endif %}}\",\n      \"label\": \"Shanghai\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Asia/Shanghai\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_sydney\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'sydney\' %}}true{{% endif %}}\",\n      \"label\": \"Sydney\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Australia/Sydney\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_tokyo\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'tokyo\' %}}true{{% endif %}}\",\n      \"label\": \"Tokyo\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"Asia/Tokyo\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    },\n    {\n      \"uid\": \"widget_clock_winnipeg\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_timezone != \'winnipeg\' %}}true{{% endif %}}\",\n      \"label\": \"Winnipeg\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.clock\",\n      \"pos\": 0,\n      \"width_units\": 1,\n      \"params\": {\n        \"timezone\": \"America/Winnipeg\",\n        \"format\": \"0\",\n        \"color\": \"#007cbd\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (50,'cerb_workspace_widget_counter','Counter','A widget displaying a single metric value (e.g. count, average)','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Counter\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Counter\",\n      \"uri\": \"cerb_workspace_widget_counter\",\n      \"description\": \"A widget displaying a single metric value (e.g. count, average)\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"# Open Tickets\": \"count_open_tickets\",\n              \"Avg. Response Time (30d)\": \"avg_response_time_30d\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_counter_open_tickets\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'count_open_tickets\' %}}true{{% endif %}}\",\n      \"label\": \"# Open Tickets\",\n      \"extension_id\": \"core.workspace.widget.counter\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 1,\n      \"zone\": \"left\",\n      \"params\": {\n        \"datasource\": \"cerb.workspace.widget.datasource.data_query\",\n        \"data_query\": \"type:worklist.metrics\\r\\nvalues.total:(\\r\\n  of:ticket\\r\\n  field:id\\r\\n  function:count\\r\\n  query:(\\r\\n    status:o\\r\\n  )\\r\\n)\\r\\nformat:table\",\n        \"metric_type\": \"number\",\n        \"metric_prefix\": \"\",\n        \"metric_suffix\": \"\",\n        \"color\": \"#34434e\"\n      }\n    },\n    {\n      \"uid\": \"widget_counter_avg_response_time_30d\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'avg_response_time_30d\' %}}true{{% endif %}}\",\n      \"label\": \"Average Response Time (past 30 days)\",\n      \"extension_id\": \"core.workspace.widget.counter\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 1,\n      \"zone\": \"left\",\n      \"params\": {\n        \"datasource\": \"cerb.workspace.widget.datasource.data_query\",\n        \"data_query\": \"type:worklist.metrics\\r\\nvalues.total:(\\r\\n  of:message\\r\\n  field:responseTime\\r\\n  function:average\\r\\n  query:(\\r\\n    isOutgoing:y\\r\\n    created:\\\"today -30 days\\\"\\r\\n    responseTime:>0\\r\\n  )\\r\\n)\\r\\nformat:table\",\n        \"metric_type\": \"seconds\",\n        \"metric_prefix\": \"\",\n        \"metric_suffix\": \"\",\n        \"color\": \"#34434e\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (51,'cerb_workspace_widget_donut','Donut','A data query driven donut chart visualization','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Donut\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Donut\",\n      \"uri\": \"cerb_workspace_widget_donut\",\n      \"description\": \"A data query driven donut chart visualization\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"Orgs by Country\": \"orgs_by_country\",\n              \"Tickets by Status\": \"tickets_by_status\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_donut_tickets_by_status\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_by_status\' %}}true{{% endif %}}\",\n      \"label\": \"Tickets by Status\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"cerb.workspace.widget.chart.pie\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:ticket\\r\\nby:[status]\\r\\nquery:()\\r\\nformat:pie\",\n        \"cache_secs\": \"\",\n        \"chart_as\": \"donut\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\"\n        }\n      }\n    },\n    {\n      \"uid\": \"widget_donut_orgs_by_country\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'orgs_by_country\' %}}true{{% endif %}}\",\n      \"label\": \"Orgs by Country\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"cerb.workspace.widget.chart.pie\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\r\\nof:org\\r\\nby:[country~20]\\r\\nquery:(country:!\\\"\\\")\\r\\nformat:pie\",\n        \"cache_secs\": \"\",\n        \"chart_as\": \"donut\",\n        \"height\": \"\",\n        \"options\": {\n          \"show_legend\": \"1\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (52,'cerb_workspace_widget_map_usa','Map: U.S. States','A zoomable map of U.S. states with points of interest from a data query','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Map: U.S. States\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Map: U.S. States\",\n      \"uri\": \"cerb_workspace_widget_map_usa\",\n      \"description\": \"A zoomable map of U.S. states with points of interest from a data query\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"map_usa\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Map: U.S. States\",\n      \"extension_id\": \"cerb.workspace.widget.map.geopoints\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"left\",\n      \"params\": {\n        \"map_kata\": \"map:\\r\\n  resource:\\r\\n    uri: cerb:resource:map.country.usa.states\\r\\n  projection:\\r\\n    type: albersUsa\\r\\n    scale: 650\\r\\n  regions:\\r\\n    label:\\r\\n      title: name_en\\r\\n      properties:\\r\\n        region_sub:\\r\\n          label: Region\\r\\n        postal:\\r\\n        iso_3166_2:\\r\\n    fill:\\r\\n      color_map:\\r\\n        property: name\\r\\n        colors:\\r\\n          California: cornflowerblue\\r\\n          Texas: orangered\\r\\n  points:\\r\\n    resource:\\r\\n      uri: cerb:resource:mapPoints.usaStateCapitals\\r\\n    size:\\r\\n      default: 2\\r\\n    fill:\\r\\n      default: #646464\",\n        \"automation\": {\n          \"map_clicked\": \"\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (53,'cerb_workspace_widget_map_world','Map: World Countries','A zoomable map of world countries with points of interest from a data query','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Map: World Countries\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Map: World Countries\",\n      \"uri\": \"cerb_workspace_widget_map_world\",\n      \"description\": \"A zoomable map of world countries with points of interest from a data query\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"map_world\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"label\": \"Map: World Countries\",\n      \"extension_id\": \"cerb.workspace.widget.map.geopoints\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"map_kata\": \"map:\\r\\n  resource:\\r\\n    uri: cerb:resource:map.world.countries\\r\\n  projection:\\r\\n    type: mercator\\r\\n    scale: 90\\r\\n    center:\\r\\n      longitude: 0\\r\\n      latitude: 7.0\\r\\n  regions:\\r\\n    label:\\r\\n      title: name\\r\\n      properties:\\r\\n        name:\\r\\n          label: Country\\r\\n        pop_est:\\r\\n          label: Population\\r\\n          format: number\\r\\n        lastcensus:\\r\\n          label: Last Census\\r\\n    fill:\\r\\n      choropleth:\\r\\n        property: pop_est\\r\\n        classes: 8\\r\\n  points:\\r\\n    resource:\\r\\n      uri: cerb:resource:mapPoints.worldCapitalCities\\r\\n    label:\\r\\n      title: name\\r\\n      properties:\\r\\n        adm0name:\\r\\n          label: Country\\r\\n    size:\\r\\n      default: 2\\r\\n    fill:\\r\\n      default: #646464\",\n        \"automation\": {\n          \"map_clicked\": \"\"\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (54,'cerb_workspace_widget_worklist','Worklist','A filterable, pageable, and sortable worklist of records','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Worklist\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Worklist\",\n      \"uri\": \"cerb_workspace_widget_worklist\",\n      \"description\": \"A filterable, pageable, and sortable worklist of records\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"Active Workers\": \"workers_active\",\n              \"My Reminders\": \"reminders_my\",\n              \"My Tasks\": \"tasks_my\",\n              \"My Tickets\": \"tickets_my\",\n              \"Open Tickets\": \"tickets_open\",\n              \"Overdue Tasks\": \"tasks_overdue\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_worklist_my_reminders\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'reminders_my\' %}}true{{% endif %}}\",\n      \"label\": \"My Reminders\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.reminder\",\n        \"query_required\": \"worker:me closed:n\",\n        \"query\": \"\",\n        \"render_limit\": \"10\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"r_name\",\n          \"r_remind_at\",\n          \"r_updated_at\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"widget_worklist_my_tasks\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tasks_my\' %}}true{{% endif %}}\",\n      \"label\": \"My Tasks\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.task\",\n        \"query_required\": \"owner:me status:o\",\n        \"query\": \"\",\n        \"render_limit\": \"10\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_due_date\",\n          \"t_importance\",\n          \"t_updated_date\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"widget_worklist_overdue_tasks\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tasks_overdue\' %}}true{{% endif %}}\",\n      \"label\": \"Overdue Tasks\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.task\",\n        \"query_required\": \"status:o due:\\\"-10 years to now\\\"\",\n        \"query\": \"\",\n        \"render_limit\": \"10\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_due_date\",\n          \"t_importance\",\n          \"t_updated_date\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"widget_my_tickets\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_my\' %}}true{{% endif %}}\",\n      \"label\": \"My Tickets\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.ticket\",\n        \"query_required\": \"owner:me status:o\",\n        \"query\": \"\",\n        \"render_limit\": \"10\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_last_wrote_address_id\",\n          \"t_updated_date\",\n          \"t_group_id\",\n          \"t_bucket_id\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"widget_open_tickets\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_open\' %}}true{{% endif %}}\",\n      \"label\": \"Open Tickets\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 4,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.ticket\",\n        \"query_required\": \"status:o\",\n        \"query\": \"\",\n        \"render_limit\": \"10\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"t_last_wrote_address_id\",\n          \"t_group_id\",\n          \"t_bucket_id\",\n          \"t_owner_id\",\n          \"t_updated_date\"\n        ]\n      }\n    },\n    {\n      \"uid\": \"widget_currently_active\",\n      \"_context\": \"workspace_widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'workers_active\' %}}true{{% endif %}}\",\n      \"label\": \"Currently Active Workers\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.worklist\",\n      \"pos\": 0,\n      \"width_units\": 2,\n      \"params\": {\n        \"context\": \"cerberusweb.contexts.worker\",\n        \"query_required\": \"lastActivity:\\\"-30 mins\\\"\",\n        \"query\": \"\",\n        \"render_limit\": \"5\",\n        \"header_color\": \"#6a87db\",\n        \"columns\": [\n          \"w_title\",\n          \"a_address_email\",\n          \"w_is_superuser\",\n          \"w_at_mention_name\",\n          \"w_language\",\n          \"w_timezone\"\n        ]\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (55,'cerb_workspace_widget_chart_sheet','Sheet','Customizable tabular results from a data query','','workspace_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Sheet\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.3.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Sheet\",\n      \"uri\": \"cerb_workspace_widget_chart_sheet\",\n      \"description\": \"Customizable tabular results from a data query\",\n      \"point\": \"workspace_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Workspace Dashboard\",\n          \"key\": \"workspace_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.workspace.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        },\n        {\n          \"type\": \"picklist\",\n          \"label\": \"Dataset:\",\n          \"key\": \"prompt_dataset\",\n          \"params\": {\n            \"options\": {\n              \"Active Workers\": \"workers_active\",\n              \"Bot Behaviors by Event\": \"behaviors_by_event\",\n              \"Tickets by Status\": \"tickets_by_status\",\n              \"Worker Reply Leaderboard\": \"worker_reply_leaderboard\",\n              \"Workers By Group\": \"workers_by_group\"\n            }\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"workspace_widget_sheet_workers_active\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'workers_active\' %}}true{{% endif %}}\",\n      \"label\": \"Active Workers\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.sheet\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.records\\nof:worker\\nquery:(isDisabled:no lastActivity:\\\"-15 mins\\\")\\nformat:dictionaries\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: yes\\n  paging@bool: yes\\n  #title_column: _label\\n\\ncolumns:\\n  card/_label:\\n    label: Worker\\n    params:\\n      image@bool: yes\\n      bold@bool: yes\\n  text/title:\\n    label: Title\\n\\n  text/location:\\n    label: Location\\n\\n  text/local_time:\\n    label: Local time\\n    params:\\n      value_template@raw:\\n        {{\'now\'|date(\'h:ia\', timezone)}}\\n\\n  \",\n        \"cache_secs\": \"\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_behaviors_by_event\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'behaviors_by_event\' %}}true{{% endif %}}\",\n      \"label\": \"Bot Behaviors by Event\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.sheet\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\nof:behavior\\nby.count:[event~100]\\nquery:()\\nformat:dictionaries\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: tes\\n  paging@bool: tes\\n\\ncolumns:\\n  text/event_label:\\n    label: Event\\n    params:\\n      bold@bool: yes\\n\\n  search/count:\\n    label: # Behaviors\\n    params:\\n      label_key: count\\n      context_key: count_query_context\\n      query_key: count_query\\n\\n  \",\n        \"cache_secs\": \"\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_workers_by_group\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'workers_by_group\' %}}true{{% endif %}}\",\n      \"label\": \"Workers By Group\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.sheet\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\nof:worker\\nby.count:[group~100]\\nquery:()\\nformat:dictionaries\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: yes\\n  paging@bool: yes\\n\\ncolumns:\\n  card/group:\\n    label: Group\\n    params:\\n      image@bool: yes\\n      bold@bool: yes\\n      id_key: group\\n      label_key: group_label\\n      context: group\\n\\n  search/count:\\n    label: # Members\\n    params:\\n      label_key: count\\n      context_key: count_query_context\\n      query_key: count_query\\n\\n  \",\n        \"cache_secs\": \"\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_worker_leaderboard\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'worker_reply_leaderboard\' %}}true{{% endif %}}\",\n      \"label\": \"Reply Leaderboard (Top 10, Past Year)\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.sheet\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\nof:message\\nby:[worker~10]\\nquery:(\\n\\tcreated:\\\"-1 year to now\\\"\\n\\tworker.id:!0\\n\\tisOutgoing:y\\n\\tisBroadcast:n\\n)\\nformat:dictionaries\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: yes\\n  paging@bool: yes\\n\\ncolumns:\\n  card/worker_id:\\n    label: Worker\\n    params:\\n      image@bool: yes\\n      bold@bool: yes\\n\\n  search/count:\\n    label: # Replies\\n    params:\\n      label_key: count\\n      context_key: count_query_context\\n      query_key: count_query\\n\\n  \",\n        \"cache_secs\": \"\"\n      }\n    },\n    {\n      \"uid\": \"workspace_widget_tickets_by_status\",\n      \"_context\": \"cerberusweb.contexts.workspace.widget\",\n      \"_exclude\": \"{{% if prompt_dataset != \'tickets_by_status\' %}}true{{% endif %}}\",\n      \"label\": \"Tickets by Status\",\n      \"tab_id\": \"{{{workspace_tab_id}}}\",\n      \"extension_id\": \"core.workspace.widget.sheet\",\n      \"pos\": 1,\n      \"width_units\": 2,\n      \"zone\": \"content\",\n      \"params\": {\n        \"data_query\": \"type:worklist.subtotals\\nof:ticket\\nby:[status]\\nquery:()\\nformat:dictionaries\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: yes\\n  paging@bool: yes\\n\\ncolumns:\\n  text/status_label:\\n    label: Status\\n    params:\\n      bold@bool: yes\\n\\n  search/count:\\n    label: # Tickets\\n    params:\\n      label_key: count\\n      context_key: count_query_context\\n      query_key: count_query\\n\\n  \",\n        \"cache_secs\": \"\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (56,'cerb_card_widget_address_tickets','Tickets','Display the email\'s itemized ticket counts','','card_widget:address',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Address Tickets\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Tickets\",\n      \"uri\": \"cerb_card_widget_address_tickets\",\n      \"description\": \"Display the email\'s itemized ticket counts\",\n      \"point\": \"card_widget:address\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_tickets\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Tickets\",\n      \"record_type\": \"cerberusweb.contexts.address\",\n      \"extension_id\": \"cerb.card.widget.fields\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.address\",\n        \"context_id\": \"{{record_id}}\",\n        \"search\": {\n          \"context\": [\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\"\n          ],\n          \"label_singular\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"label_plural\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"query\": [\n            \"participant.id:{{record_id}} status:!d\",\n            \"participant.id:{{record_id}} status:o\",\n            \"participant.id:{{record_id}} status:w\",\n            \"participant.id:{{record_id}} status:c\"\n          ]\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (57,'cerb_card_widget_attachments_viewer','File Viewer','Display the attachment content','','card_widget:attachment',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Attachments Viewer\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"File Viewer\",\n      \"uri\": \"cerb_card_widget_attachments_viewer\",\n      \"description\": \"Display the attachment content\",\n      \"point\": \"card_widget:attachment\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_attachment_viewer\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"File\",\n      \"record_type\": \"cerberusweb.contexts.attachment\",\n      \"extension_id\": \"cerb.card.widget.attachment.viewer\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"attachment_id\": \"{{record_id}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (58,'cerb_card_widget_bucket_tickets','Tickets','Display the bucket\'s itemized ticket counts','','card_widget:bucket',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Bucket Tickets\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Tickets\",\n      \"uri\": \"cerb_card_widget_bucket_tickets\",\n      \"description\": \"Display the bucket\'s itemized ticket counts\",\n      \"point\": \"card_widget:bucket\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_848\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Tickets\",\n      \"record_type\": \"cerberusweb.contexts.bucket\",\n      \"extension_id\": \"cerb.card.widget.fields\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.bucket\",\n        \"context_id\": \"{{record_id}}\",\n        \"search\": {\n          \"context\": [\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\"\n          ],\n          \"label_singular\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"label_plural\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"query\": [\n            \"bucket.id:{{record_id}} status:!d\",\n            \"bucket.id:{{record_id}} status:o\",\n            \"bucket.id:{{record_id}} status:w\",\n            \"bucket.id:{{record_id}} status:c\"\n          ]\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (59,'cerb_card_widget_conversation','Conversation','Display the record\'s messages and comments','','card_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Conversation\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Conversation\",\n      \"uri\": \"cerb_card_widget_conversation\",\n      \"description\": \"Display the record\'s messages and comments\",\n      \"point\": \"card_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_conversation\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Conversation\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.conversation\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"{{{prompt_record_type}}}\",\n        \"context_id\": \"{{record_id}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (60,'cerb_card_widget_record_fields','Record Fields','Display the record\'s fields','','card_widget',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Record Fields\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Record Fields\",\n      \"uri\": \"cerb_card_widget_record_fields\",\n      \"description\": \"Display the record\'s fields\",\n      \"point\": \"card_widget\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_fields\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Properties\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.fields\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"{{{prompt_record_type}}}\",\n        \"context_id\": \"{{record_id}}\",\n        \"links\": {\n          \"show\": true\n        }\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (61,'cerb_card_widget_gpg_public_key_subkeys','Subkeys','Display the key\'s subkeys','','card_widget:gpg_public_key',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: GPG Public Key Subkeys\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Subkeys\",\n      \"uri\": \"cerb_card_widget_gpg_public_key_subkeys\",\n      \"description\": \"Display the key\'s subkeys\",\n      \"point\": \"card_widget:gpg_public_key\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_subkeys\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Subkeys\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.sheet\",\n      \"pos\": \"3\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"data_query\": \"type:gpg.keyinfo\\nfilter:subkeys\\nfingerprint:{{record_fingerprint}}\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: yes\\n  paging@bool: yes\\n  #title_column: _label\\n\\ncolumns:\\n  text/fingerprint:\\n    label: Fingerprint\\n\\n  date/expires:\\n    label: Expires\\n    params:\\n      #image@bool: yes\\n      #bold@bool: yes\\n\\n  icon/can_sign:\\n    label: Sign\\n    params:\\n      image_template@raw:\\n        {% if can_sign %}\\n        circle-ok\\n        {% endif %}\\n\\n  icon/can_encrypt:\\n    label: Encrypt\\n    params:\\n      image_template@raw:\\n        {% if can_encrypt %}\\n        circle-ok\\n        {% endif %}\\n\\n  \"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (62,'cerb_card_widget_gpg_public_key','UIDs','Display the key\'s UIDs','','card_widget:gpg_public_key',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: GPG Public Key UIDs\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"UIDs\",\n      \"uri\": \"cerb_card_widget_gpg_public_key\",\n      \"description\": \"Display the key\'s UIDs\",\n      \"point\": \"card_widget:gpg_public_key\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_uids\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"UIDs\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.sheet\",\n      \"pos\": \"2\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"data_query\": \"type:gpg.keyinfo\\nfilter:uids\\nfingerprint:{{record_fingerprint}}\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\n  style: table\\n  headings@bool: no\\n  paging@bool: no\\n  #title_column: _label\\n\\ncolumns:\\n  search/uid:\\n    label: UID\\n    params:\\n      label_key: uid\\n      context: address\\n      query_template@raw:\\n        {% set email = uid|parse_emails %}\\n        {% if email|length > 0 %}\\n        email:{{email|first.email}}\\n        {% endif %}\\n\\n  \"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (63,'cerb_card_widget_group_tickets','Tickets','Display the group\'s itemized ticket counts','','card_widget:group',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Group Tickets\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Tickets\",\n      \"uri\": \"cerb_card_widget_group_tickets\",\n      \"description\": \"Display the group\'s itemized ticket counts\",\n      \"point\": \"card_widget:group\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_848\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Tickets\",\n      \"record_type\": \"cerberusweb.contexts.group\",\n      \"extension_id\": \"cerb.card.widget.fields\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.group\",\n        \"context_id\": \"{{record_id}}\",\n        \"search\": {\n          \"context\": [\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\"\n          ],\n          \"label_singular\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"label_plural\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"query\": [\n            \"group.id:{{record_id}} status:!d\",\n            \"group.id:{{record_id}} status:o\",\n            \"group.id:{{record_id}} status:w\",\n            \"group.id:{{record_id}} status:c\"\n          ]\n        }\n      }\n    }\n  ]\n}');
