INSERT INTO `package_library` VALUES (65,'cerb_card_widget_snippet_content','Content','Display the snippet\'s content','','card_widget:snippet',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Snippet Content\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Content\",\n      \"uri\": \"cerb_card_widget_snippet_content\",\n      \"description\": \"Display the snippet\'s content\",\n      \"point\": \"card_widget:snippet\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_snippet_content\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Content\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.sheet\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"data_query\": \"type:worklist.records\\nof:snippet\\nexpand: [custom_,]\\nquery:(\\n  id:{{record_id}}\\n  limit:1\\n  sort:[id]\\n)\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\n  style: fieldsets\\n  headings@bool: no\\n  paging@bool: no\\n\\ncolumns:\\n  text/content:\\n    label: Content\\n    params:\\n      value_template@raw:\\n        {{content|e|nl2br}}\\n\\n  \"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (66,'cerb_card_widget_worker_tickets','Tickets','Display the worker\'s itemized ticket counts','','card_widget:worker',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Worker Tickets\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Tickets\",\n      \"uri\": \"cerb_card_widget_worker_tickets\",\n      \"description\": \"Display the worker\'s itemized ticket counts\",\n      \"point\": \"card_widget:worker\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_848\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Tickets\",\n      \"record_type\": \"cerberusweb.contexts.worker\",\n      \"extension_id\": \"cerb.card.widget.fields\",\n      \"pos\": \"0\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"context\": \"cerberusweb.contexts.worker\",\n        \"context_id\": \"{{record_id}}\",\n        \"search\": {\n          \"context\": [\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\",\n            \"cerberusweb.contexts.ticket\"\n          ],\n          \"label_singular\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"label_plural\": [\n            \"All\",\n            \"Open\",\n            \"Waiting\",\n            \"Closed\"\n          ],\n          \"query\": [\n            \"owner.id:{{record_id}} status:!d\",\n            \"owner.id:{{record_id}} status:o\",\n            \"owner.id:{{record_id}} status:w\",\n            \"owner.id:{{record_id}} status:c\"\n          ]\n        }\n      }\n    }\n  ]\n}')