INSERT INTO `package_library` VALUES (67,'cerb_profile_widget_ticket_status','Status','A widget that display the current ticket group/bucket and status, and allows quick move','','profile_widget:ticket',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Profile: Ticket Status\",\n    \"revision\": 2,\n    \"requires\": {\n      \"cerb_version\": \"10.4.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Status\",\n      \"uri\": \"cerb_profile_widget_ticket_status\",\n      \"description\": \"A widget that display the current ticket group/bucket and status, and allows quick move\",\n      \"point\": \"profile_widget:ticket\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"chooser\",\n          \"label\": \"Profile Dashboard\",\n          \"key\": \"profile_tab_id\",\n          \"hidden\": true,\n          \"params\": {\n            \"context\": \"cerberusweb.contexts.profile.tab\",\n            \"single\": true,\n            \"query\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"widget_ticket_status\",\n      \"_context\": \"profile_widget\",\n      \"name\": \"Status\",\n      \"profile_tab_id\": \"{{{profile_tab_id}}}\",\n      \"pos\": 0,\n      \"width_units\": 4,\n      \"zone\": \"sidebar\",\n      \"extension_id\": \"cerb.profile.tab.widget.sheet\",\n      \"extension_params\": {\n        \"data_query\": \"type:worklist.records\\r\\nof:ticket\\r\\nquery:(\\r\\n  id:{{record_id}}\\r\\n  limit:1\\r\\n  sort:[id]\\r\\n)\\r\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\r\\n  style: fieldsets\\r\\n  headings@bool: no\\r\\n  paging@bool: no\\r\\n  title_column: image\\r\\n  colors:\\r\\n    labels@csv: #898989, #646464\\r\\n    labels_dark@csv: #898989, #cccccc\\r\\n    statuses@csv: #66aa57, #5585cc, #636363, #d3352a\\r\\n\\r\\ncolumns:\\r\\n  icon/image:\\r\\n    params:\\r\\n      record_uri@raw: cerb:group:{{group_id}}\\r\\n      text_size@raw: 400%\\r\\n  \\r\\n  card/group__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_size: 135%\\r\\n      text_color@raw: labels:0\\r\\n  \\r\\n  card/bucket__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_color@raw: labels:1\\r\\n      text_size: 200%\\r\\n  \\r\\n  text/status:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      text_size: 145%\\r\\n      value_template@raw:\\r\\n        {{status|capitalize}}\\r\\n        {% if reopen_date and status in [\'waiting\',\'closed\'] %}\\r\\n        (<abbr title=\\\"{{reopen_date|date(\'r\')}}\\\">{{reopen_date|date_pretty}}</abbr>)\\r\\n        {% endif %}        \\r\\n      text_color@raw: statuses:{{status_id}}\\r\\n  \\r\\n  toolbar/actions:\\r\\n    label: Actions\\r\\n    params:\\r\\n      kata:\\r\\n        interaction/reopen:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id) or \'open\' == status}}\\r\\n          label: Re-open\\r\\n          icon: upload\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            #confirm@bool: yes\\r\\n            status: open\\r\\n        interaction/move:\\r\\n          uri: cerb:automation:cerb.ticket.move\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id)}}\\r\\n          label: Move\\r\\n          icon: send\\r\\n          keyboard: M\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n        interaction/close:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or status in [\'closed\',\'deleted\']\\r\\n            }}\\r\\n          label: Close\\r\\n          icon: circle-ok\\r\\n          keyboard: C\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: closed\\r\\n        interaction/delete:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or \'deleted\' == status \\r\\n              or not cerb_has_priv(\'contexts.cerberusweb.contexts.ticket.delete\')\\r\\n            }}\\r\\n          label: Delete\\r\\n          icon: circle-remove\\r\\n          keyboard: X\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: deleted\",\n        \"toolbar_kata\": \"\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (68,'cerb_card_widget_address_compose','Compose','Shortcut for sending email to the address','','card_widget:address',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: Compose\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Compose\",\n      \"uri\": \"cerb_card_widget_address_compose\",\n      \"description\": \"Shortcut for sending email to the address\",\n      \"point\": \"card_widget:address\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_compose\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Actions\",\n      \"record_type\": \"cerberusweb.contexts.address\",\n      \"extension_id\": \"cerb.card.widget.form_interaction\",\n      \"pos\": \"99\",\n      \"width_units\": \"4\",\n      \"zone\": \"content\",\n      \"extension_params\": {\n        \"interactions_kata\": \"interaction/compose:\\n  label: Compose\\n  uri: cerb:automation:cerb.mail.compose\\n  icon: send\\n  inputs:\\n    record_type@key: record__context\\n    record_id@key: record_id\\n  after:\\n    refresh_widgets@csv: Actions\"\n      }\n    }\n  ]\n}');
