INSERT INTO `package_library` VALUES (71,'cerb_card_widget_gpg_public_key_ascii','Public Key','Display the public key in text format','','card_widget:gpg_public_key',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Card Widget: GPG Public Key ASCII\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.6.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Public Key\",\n      \"uri\": \"cerb_card_widget_gpg_public_key_ascii\",\n      \"description\": \"Display the public key in text format\",\n      \"point\": \"card_widget:gpg_public_key\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [\n      ],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Record Type\",\n          \"key\": \"prompt_record_type\",\n          \"hidden\": true,\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"card_widget_public_key\",\n      \"_context\": \"cerb.contexts.card.widget\",\n      \"name\": \"Public Key\",\n      \"record_type\": \"{{{prompt_record_type}}}\",\n      \"extension_id\": \"cerb.card.widget.sheet\",\n      \"pos\": \"3\",\n      \"width_units\": \"4\",\n      \"zone\": \"\",\n      \"extension_params\": {\n        \"data_query\": \"type:worklist.records\\nof:gpg_public_key\\nquery:(\\n  id:{{record_id}}\\n  limit:1\\n  sort:[id]\\n)\\nformat:dictionaries\",\n        \"cache_secs\": \"\",\n        \"placeholder_simulator_kata\": \"\",\n        \"sheet_kata\": \"layout:\\n  style: fieldset\\n  headings@bool: no\\n  paging@bool: no\\n\\ncolumns:\\n  text/_label:\\n    label: Label\\n    params:\\n      value_template@raw:\\n        <pre>\\n        {{key_text}}\\n        </pre>\\n\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (72,'cerb_connected_service_huggingface','Hugging Face','Integration with Hugging Face','# Instructions\r\n\r\n* Enter your API key from <https://huggingface.co/settings/tokens>','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: Hugging Face\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"10.0.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"Hugging Face\",\n      \"uri\": \"cerb_connected_service_huggingface\",\n      \"description\": \"Integration with Hugging Face\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* Enter your API key from <https://huggingface.co/settings/tokens>\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"API Key\",\n          \"key\": \"prompt_api_key\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your API Key)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Alias\",\n          \"key\": \"prompt_name\",\n          \"params\": {\n            \"default\": \"huggingface\",\n            \"placeholder\": \"(enter a URI, a-z,0-9,_)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_huggingface\",\n      \"_context\": \"connected_service\",\n      \"name\": \"Hugging Face\",\n      \"extension_id\": \"cerb.service.provider.token.bearer\",\n      \"params\": {\n        \"token_name\": \"Bearer\"\n      }\n    },\n    {\n      \"uid\": \"account_huggingface\",\n      \"_context\": \"connected_account\",\n      \"name\": \"Hugging Face\",\n      \"service_id\": \"{{{uid.service_huggingface}}}\",\n      \"owner__context\": \"cerberusweb.contexts.app\",\n      \"owner_id\": \"0\",\n      \"uri\": \"{{{prompt_name}}}\",\n      \"params\": {\n        \"token\": \"{{{prompt_api_key}}}\"\n      }\n    }\n  ]\n}');
INSERT INTO `package_library` VALUES (73,'cerb_connected_service_openai','OpenAI','Integration with OpenAI','# Instructions\r\n\r\n* Enter your API key from <https://platform.openai.com/account/api-keys>','connected_service',UNIX_TIMESTAMP(),'{\n  \"package\": {\n    \"name\": \"Connected Service: OpenAI\",\n    \"revision\": 1,\n    \"requires\": {\n      \"cerb_version\": \"9.2.0\",\n      \"plugins\": [\n\n      ]\n    },\n    \"library\": {\n      \"name\": \"OpenAI\",\n      \"uri\": \"cerb_connected_service_openai\",\n      \"description\": \"Integration with OpenAI\",\n      \"instructions\": \"# Instructions\\r\\n\\r\\n* Enter your API key from <https://platform.openai.com/account/api-keys>\",\n      \"point\": \"connected_service\",\n      \"image\": \"data:image/png;base64,\"\n    },\n    \"configure\": {\n      \"placeholders\": [],\n      \"prompts\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"API Key\",\n          \"key\": \"prompt_api_key\",\n          \"params\": {\n            \"default\": \"\",\n            \"placeholder\": \"(paste your API Key)\"\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Alias\",\n          \"key\": \"prompt_name\",\n          \"params\": {\n            \"default\": \"openai\",\n            \"placeholder\": \"(enter a URI, a-z,0-9,_)\"\n          }\n        }\n      ]\n    }\n  },\n  \"records\": [\n    {\n      \"uid\": \"service_openai\",\n      \"_context\": \"connected_service\",\n      \"name\": \"OpenAI\",\n      \"extension_id\": \"cerb.service.provider.token.bearer\",\n      \"params\": {\n        \"token_name\": \"Bearer\"\n      }\n    },\n    {\n      \"uid\": \"account_openai\",\n      \"_context\": \"connected_account\",\n      \"name\": \"OpenAI\",\n      \"service_id\": \"{{{uid.service_openai}}}\",\n      \"owner__context\": \"cerberusweb.contexts.app\",\n      \"owner_id\": \"0\",\n      \"uri\": \"{{{prompt_name}}}\",\n      \"params\": {\n        \"token\": \"{{{prompt_api_key}}}\"\n      }\n    }\n  ]\n}');
