INSERT INTO `profile_widget` VALUES (98,'Status',39,'cerb.profile.tab.widget.sheet','{\"data_query\":\"type:worklist.records\\r\\nof:ticket\\r\\nquery:(\\r\\n  id:{{record_id}}\\r\\n  limit:1\\r\\n  sort:[id]\\r\\n)\\r\\nformat:dictionaries\",\"cache_secs\":\"\",\"placeholder_simulator_kata\":\"\",\"sheet_kata\":\"layout:\\r\\n  style: fieldsets\\r\\n  headings@bool: no\\r\\n  paging@bool: no\\r\\n  title_column: image\\r\\n  colors:\\r\\n    labels@csv: #898989, #646464\\r\\n    labels_dark@csv: #898989, #cccccc\\r\\n    statuses@csv: #66aa57, #5585cc, #636363, #d3352a\\r\\n\\r\\ncolumns:\\r\\n  icon\\/image:\\r\\n    params:\\r\\n      record_uri@raw: cerb:group:{{group_id}}\\r\\n      text_size@raw: 400%\\r\\n  \\r\\n  card\\/group__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_size: 135%\\r\\n      text_color@raw: labels:0\\r\\n  \\r\\n  card\\/bucket__label:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      underline@bool: no\\r\\n      text_color@raw: labels:1\\r\\n      text_size: 200%\\r\\n  \\r\\n  text\\/status:\\r\\n    params:\\r\\n      bold@bool: yes\\r\\n      text_size: 145%\\r\\n      value_template@raw:\\r\\n        {{status|capitalize}}\\r\\n        {% if reopen_date and status in [\'waiting\',\'closed\'] %}\\r\\n        (<abbr title=\\\"{{reopen_date|date(\'r\')}}\\\">{{reopen_date|date_pretty}}<\\/abbr>)\\r\\n        {% endif %}        \\r\\n      text_color@raw: statuses:{{status_id}}\\r\\n  \\r\\n  toolbar\\/actions:\\r\\n    label: Actions\\r\\n    params:\\r\\n      kata:\\r\\n        interaction\\/reopen:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id) or \'open\' == status}}\\r\\n          label: Re-open\\r\\n          icon: upload\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            #confirm@bool: yes\\r\\n            status: open\\r\\n        interaction\\/move:\\r\\n          uri: cerb:automation:cerb.ticket.move\\r\\n          hidden@raw,bool: {{not cerb_record_writeable(\'ticket\', id)}}\\r\\n          label: Move\\r\\n          icon: send\\r\\n          keyboard: M\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n        interaction\\/close:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or status in [\'closed\',\'deleted\']\\r\\n            }}\\r\\n          label: Close\\r\\n          icon: circle-ok\\r\\n          keyboard: C\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: closed\\r\\n        interaction\\/delete:\\r\\n          uri: cerb:automation:cerb.ticket.status\\r\\n          hidden@raw,bool:\\r\\n            {{\\r\\n              not cerb_record_writeable(\'ticket\', id) \\r\\n              or \'deleted\' == status \\r\\n              or not cerb_has_priv(\'contexts.cerberusweb.contexts.ticket.delete\')\\r\\n            }}\\r\\n          label: Delete\\r\\n          icon: circle-remove\\r\\n          keyboard: X\\r\\n          inputs:\\r\\n            ticket@raw: {{id}}\\r\\n            confirm@bool: yes\\r\\n            status: deleted\",\"toolbar_kata\":\"\"}','sidebar',1,4,UNIX_TIMESTAMP(),NULL);
