INSERT INTO `profile_widget` VALUES (117,'Actions',42,'cerb.profile.tab.widget.html','{\"template\": \"{% set is_editable = cerb_record_writeable(record__context, record_id) %}\\r\\n{% if is_editable %}\\r\\n\\t<div style=\\\"padding:0px 5px 5px 5px;\\\">\\r\\n\\t\\t<button type=\\\"button\\\" data-shortcut=\\\"impersonate\\\">\\r\\n\\t\\t\\t<span class=\\\"glyphicons glyphicons-user\\\"></span> {{\'common.impersonate\'|cerb_translate|capitalize}}\\r\\n\\t\\t</button>\\r\\n\\t</div>\\r\\n{% endif %}\\r\\n\\r\\n<script type=\\\"text/javascript\\\">\\r\\n$(function() {\\r\\n\\tvar $widget = $(\'#profileWidget{{widget_id}}\');\\r\\n\\r\\n\\t{% if is_editable %}\\r\\n\\t\\tvar $button_impersonate = $widget.find(\'button[data-shortcut=\\\"impersonate\\\"]\');\\r\\n\\t\\r\\n\\t\\t$button_impersonate\\r\\n\\t\\t\\t.on(\'click\', function(e) {\\r\\n\\t\\t\\t\\tvar formData = new FormData();\\r\\n\\t\\t\\t\\tformData.set(\'c\', \'profiles\');\\r\\n\\t\\t\\t\\tformData.set(\'a\', \'invoke\');\\r\\n\\t\\t\\t\\tformData.set(\'module\', \'worker\');\\r\\n\\t\\t\\t\\tformData.set(\'action\', \'su\');\\r\\n\\t\\t\\t\\tformData.set(\'worker_id\', \'{{record_id}}\');\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\tgenericAjaxPost(formData,null,null,function(o) {\\r\\n\\t\\t\\t\\t\\twindow.location = window.location;\\r\\n\\t\\t\\t\\t});\\r\\n\\t\\t\\t})\\r\\n\\t\\t\\t;\\r\\n\\t{% else %}\\r\\n\\t\\t$widget\\r\\n\\t\\t\\t.closest(\'.cerb-profile-widget\')\\r\\n\\t\\t\\t.remove()\\r\\n\\t\\t\\t;\\r\\n\\t{% endif %}\\r\\n});\\r\\n</script>\"}','sidebar',2,4,UNIX_TIMESTAMP(),NULL);
